-- =============================================================================
-- city_data Wikipedia leírások – 2/4. fájl
-- Települések: 773 (Gadány … Magyarszombatfa)
-- Futtasd az előző batch(ek) után.
-- =============================================================================

UPDATE public.city_data AS c
SET panel_leiras = v.panel_leiras
FROM (
  VALUES
    ('Gadány', 'Marcali dél-délnyugati szomszédságában fekszik, a város központjától légvonalban 7, közúton körülbelül 9,5 kilométerre. A további közvetlenül határos települések: kelet felől Kelevíz, délkelet felől Mesztegnyő, dél felől Szenyér, délnyugat felől Nagyszakácsi, északnyugat felől pedig Somogyzsitfa. Zsáktelepülés, mivel szilárd burkolatú úton csak keleti irányból közelíthető meg, a 68-as főútról Kelevíz déli részén leágazó 68 108-as számú, rövid bekötőúton helyezkedik el.'),
    ('Gagyapáti', 'Nevének előtagját 1905-ben kapta Alsó- és Felsőgagy után azokhoz való közelsége miatt, az országban található számtalan Apáti nevű falutól való megkülönböztetésül. Alsógagytól mindössze 2 kilométer választja el, Encstől (amely a legközelebbi város is egyben) 15 kilométerre található. Neve eredetileg csak Apáti volt, és az egész középkor folyamán így hívták.'),
    ('Gagybátor', 'A legközelebbi települések Gagyvendégi mintegy 2 kilométer, illetve Abaújlak körülbelül 5 kilométer távolságra helyezkedik el. A legközelebbi város Encs, körülbelül 22 kilométerre helyezkedik el. Nevét 1323-ban említették először az oklevelek Bathur néven. 1332-ben a neve Bator, Batur'' formában volt említve.'),
    ('Gagyvendégi', 'Légvonalban 4-5 kilométernyi távolságban található még délkeleti irányban Abaújlak és Gadna, kelet felől pedig Gagyapáti és Felsőgagy is. A legközelebbi város Encs, körülbelül 19 kilométerre helyezkedik el. Gagyvendégi (Gagy-Vendégi, Puszta-Vendégi) az Aba nemzetségből származó Gagyi család birtoka volt. 1327-ben Gagyi Gereven kapta királyi adományként Károly Róbert királytól.'),
    ('Galambok', 'A településen polgárőrség működik. Környező települések: Zalakaros, Nagyrécse, Zalasárszeg, Zalakomár. A község fontos hadiút mellett feküdt, ezt egy 1420-ból származó oklevél említi. Az 1550-es években - miként a környező településeket is - Galambokot is feldúlta a török. A megszállás ideje alatt a falu sokat szenvedett, nem csak a török, hanem császári seregek…'),
    ('Galgaguta', 'A község a fővárostól mintegy 60 kilométer-re, a megyeszékhelytől 75 kilométer, Váctól valamint Balassagyarmattól egyaránt 30 kilométer, Aszódtól 27 kilométer, Pásztótól 45 kilométer távolságra fekszik.'),
    ('Galgagyörk', 'A Cserhát déli részén fekszik, a Galga patak mellett, Budapesttől mintegy 50 kilométerre északkeletre. Belterületének túlnyomó része a Galga bal parti oldalán helyezkedik el. A közvetlenül határos települések: észak felől Püspökhatvan, dél felől Galgamácsa, délnyugat felől Váckisújfalu, nyugat felől pedig Püspökszilágy. [Kelet felől Galgamácsa kiterjedt északi külterületei határolják.] Főutcája az Aszódot Balassagyarmattal összekötő 2108-as út, ezen érhető el, Galgamácsa vagy Püspökhatvan érintésével.'),
    ('Galgahévíz', 'A Gödöllői-dombság keleti nyúlványán és a Hatvani-sík nyugati peremén, a Galga-patak jobb partján helyezkedik el. A Pest megye keleti széle közelében található település északkeleti szomszédja, Kerekharaszt már Heves megyéhez tartozik. A további határos települések: kelet felől Tura, dél felől Vácszentlászló, nyugat felől Bag és Hévízgyörk, észak felől pedig Kartal.'),
    ('Galgamácsa', 'A Galga-patak völgyében található települést Budapest felől Fót és Veresegyház érintésével a 2102-es, Vác térsége felől a 2105-ös, Aszód és Balassagyarmat irányából pedig a két várost összekötő 2108-as úton érhető el. A legközelebbi megállóhelyek: Aszód irányában Iklad-Domony felső, a váci vonalon Váckisújfalu, az ipolytarnócin pedig Galgagyörk. Galgamácsa nevét az ismert források először a középkorból említik, bár a környezete nagyon régóta lakott.'),
    ('Galvács', 'Szendrő keleti szomszédságában fekszik, attól mintegy 5 kilométerre, a megyeszékhely Miskolctól közúton 38 kilométerre északra. Észak felől Meszessel, északkelet felől Rakacaszenddel, dél felől pedig a 6 kilométerre fekvő Aboddal is határos, de közúti kapcsolata csak Szendrővel és Aboddal van, mindkettővel a 2615-ös út köti össze. Neve feltehetően egy szláv eredetű szóból eredhet, melynek jelentése nagy fejű ember.'),
    ('Gamás', 'Kaposvár és a Balaton között nagyjából félúton fekszik. Az északról a Vörös-heggyel, nyugatról a Malom-patakkal, keletről a Tetves-patakkal határolt területet nevezhetjük Gamás vidékének. Jellegzetesen somogyi táj, észak–déli dombvonulatokkal, amiket rövidebb oldalágak és helyenként tekintélyes vízmosások osztanak fel. Változatos formavilága -mely a lankás oldalaktól a meredek letörésekig terjed- minden nézőpontból más képet tár elénk.'),
    ('Ganna', 'Két, egymástól némileg elkülönülő településrésze Nagyganna és az attól kissé északabbra elterülő, nevéhez híven valóban kisebb területen fekvő Kisganna. Ganna Árpád-kori település. A falu első említése egy 1171-es oklevélben található, amikor…'),
    ('Gara', 'A Bácskai-síkvidéken helyezkedik el. A legközelebbi város Baja, melytől dél-délkeleti irányban, mintegy 15 kilométerre fekszik, a szerb határ mellett. A szomszédos települések a határ magyar oldalán: észak felől Vaskút, északkelet felől Bácsborsód, dél felől Bácsszentgyörgy, délnyugat felől Dávod, nyugat felől pedig Csátalja. Délkelet felől a legközelebbi település a már Szerbiához tartozó Regőce (Риђица / Riđica).'),
    ('Garabonc', 'A településen polgárőrség működik. A falu a középkorban a veszprémi káptalan birtoka volt, aki egy 1342-es keltezésű határvita során is említette Garabonc nevét, mely per során a káptalan több előző keltezésű oklevéllel is igazolta, hogy Garabonc ősi idők óta az ő birtoka volt. Így Imre király 1203-as, IV. Béla magyar király 1254-es keltezésű oklevelével is. 1496-ban már templomos hely volt.'),
    ('Garadna', 'A Hernád völgye és a Cserehát határán fekszik, a megyeszékhely Miskolctól 50 kilométerre északkeletre, Encstől 10 kilométerre északra. A közvetlen szomszédos települések észak felől Hernádvécse, dél felől pedig Novajidrány. Neve szláv eredetű (grad na), jelentése „várhoz tartozó”, eszerint eredetileg várbirtok volt. Egy, a 19. századból fennmaradt irat tanúsága szerint a jegyző és a bíró úgy hivatkoztak rá, hogy nevének jelentése Vári, az első „a” betű pedig utóbb került bele a névbe, a könnyebb kiejthetőség miatt.'),
    ('Garbolc', 'A Túr mentén fekszik, annak bal partján, az ország keleti határán. Közigazgatási határszélén található Magyarország, Románia és Ukrajna hármas határa, bő 2 kilométerre kelet-északkeleti irányban a település központjától. A határ magyar oldalán mindössze két településsel szomszédos: északnyugat felől Nagyhódossal, délnyugat felől pedig Méhtelekkel. Északkelet felől az ukrajnai Fertősalmáshoz (Фертешолмаш), délkelet felől pedig a romániai Szárazberekhez (Bercu) tartozó területek határolják.'),
    ('Garáb', 'A Cserhát vidékének egyik legszebb, legmagasabban fekvő települése, amely a Kelet-cserháti Tájvédelmi Körzet területén található, 375 méter tengerszint feletti magasságban. Pásztó és Szécsény között körülbelül félúton helyezkedik el, előbbihez kicsit közelebb. Budapesttől körülbelül 75 kilométerre fekszik. Turisták által is kedvelt környezetben, erdőségek, források és régi vulkáni hegyek között húzódik meg.'),
    ('Garé', 'A településnév valószínűleg a középkorban itt birtokos Gara család nevéből ered, eredeti jelentése ez esetben: Garáé. Pesty Frigyes szerint a település nevét a falutól északra, az ún. Domb-dűlő helyén egykor állt Gara vára után kapta. A Dél-Dunántúlon fekszik, Pécstől légvonalban mintegy 17, közúton 21 kilométerre délre. A falut a Szőkei- és a Bostai-árok veszi körül.'),
    ('Gasztony', 'A falu a Rába völgyében, a Lahm patak bal partján fekszik. Neve a szláv goszt (= vendég) főnévből származik. Más feltevés szerint azonban a francia eredetű Gaszton személynévből ered. A középkor folyamán a források többnyire együtt említik a szomszédos, azóta elpusztult Kövesszarv nevű településeel. 1271-ben Terra Kueszoru, 1375-ben Poss. Kweszarm et Gozton, 1436-ban Gozthon, 1452-ben Joh.'),
    ('Gecse', 'A Bakony nyúlványai és a Kisalföld síkvidékének találkozásánál, a Sokoróalja délnyugati részén, a Pannonhalmi borvidék mentén fekszik. A szomszédos települések: északkelet felől Szerecseny (3 kilométerre), délkelet felől Lovászpatona (légvonalban 8, közúton mintegy 14-15 kilométerre), dél felől Vaszar (6 kilométerre), nyugat felől pedig Gyarmat (3 kilométerre).'),
    ('Gelej', 'A település lakosságának közel 100 %-a magyar nemzetiségűnek vallja magát. Legközelebbi szomszédjai a 4 kilométerre fekvő Mezőnagymihály és a 11 kilométerre lévő Mezőcsát. Mezőkeresztestől 8, Csincsétől mintegy 15 kilométerre fekszik. A települést a Csincse-patak szeli ketté. Gelej Árpád-kori település. A 14. században a Geley család, az Örsúr nemzetség Geszty ága volt itt birtokos.'),
    ('Gellénháza', 'Gellénháza neve 1490-ben szerepel először oklevélben, egy nemes család nevének említésekor. Gellénháza a Gellén család ősi fészke. Felső részét valaha Kisbudának nevezték, mivel a Budayak laktak itt. A másik részét Gellénházának és Józseffalvának, az illető családok után helyezkedik el. Lakosai nagyobbrészt köznemesek voltak. A Gellénháza elnevezés előtagja a latin Chilianus magyar személynévi megfelelője.'),
    ('Gelse', 'Az Árpád-kor óta lakott település, első okleveles említése 1280 körüli: Guelse-néven. Más forrás szerint: a falu első írásos említése az 1226-os dátumhoz kapcsolható, már akkor a Gelse alak volt használatos. Később megjelent a Kyus Gelse (1270), a Gelsa (1320) és 1786-ban a Gölse elnevezés is. A név eredete bizonytalan: talán a szláv gol=csupasz, meztelen szóból származó Galesa, Golisa személynevekkel függ össze, de lehet, hogy a Gellért vagy Gellén név becéző képzős változatából jött létre.'),
    ('Gelsesziget', 'Nagykanizsától 13 kilométerre északra fekszik. Önálló vasútállomással nem rendelkezik, a magyarszerdahelyi megállóhelyen és a gelsei vasútállomáson (2,5 illetve 4,5 kilométer távolságra) keresztül érhető el vasúton. Tipikus zalai szalagtelkes falu. Elsősorban a Nagykanizsa–Pacsa, valamint a Nagykanizsa–Orosztony közötti helyközi járatok állnak meg a településen, de távolsági járat is érinti a községet (Nagykanizsa–Szombathely).'),
    ('Gelénes', 'Természeti értékei: Bockereki-erdő, Báb-tava. A szomszédos települések: észak felől Barabás, kelet felől Beregdaróc, dél felől Csaroda, délnyugat felől Tákos és Vásárosnamény (Gergelyiugornya), nyugat felől pedig Vámosatya. Autóbusszal 26 kilométerre van Vásárosnaménytól. Gelénes nevét az oklevelek 1301-ben említették először Gelienus néven helyezkedik el.'),
    ('Gemzse', 'Az Északkelet-Nyírség középső részén található, Vásárosnaménytól 11 kilométerre nyugat-északnyugatra, Kisvárdától pedig 15 kilométerre délkeletre. A közvetlen szomszédos települések: észak felől Lövőpetri, északkelet felől Gyüre, délkelet felől Ilk, dél felől Nyírmada, nyugat felől Gyulaháza, északnyugat felől pedig Szabolcsbáka. A Kállayak még a század végén is birtokolták. 1426-ban a Losonczy, 1440-ben pedig a Rozsályi Kún és a Kusalyi Jakcs család is birtokosa volt.'),
    ('Gencsapáti', 'A Gyöngyös-sík nyugati részén fekszik, Szombathely észak-északnyugati szomszédságában, a Gyöngyös-patak partján észak-déli irányban 4 kilométer hosszan elnyúlva. Az egykori Nagygencs községből alakult mai falurész alkotja a település déli felét, míg Gyöngyösapáti településrész Gencsapáti északi részén terül el. A szomszédos települések: észak felől Gyöngyösfalu, északkelet felől Pusztacsó, kelet felől Söpte, dél felől Szombathely, nyugat felől Bucsu, északnyugat felől pedig Perenye.'),
    ('Gerde', 'Pécstől délnyugatra, Szentlőrinctől dél-délkeletre fekszik. A szomszédos települések: északkelet felől Szabadszentkirály, kelet felől Velény, délkelet felől Téseny, dél felől Kisasszonyfa, délnyugat felől Magyartelek, nyugat felől pedig Királyegyháza. Gerde a középkorban nem a mai helyén állt, hanem az Acsóta és a Füzes-víz összefolyásánál és a Velemény nevű birtok része volt.'),
    ('Gerendás', 'Békéscsaba és Orosháza között helyezkedik el, mindkét várostól közel azonos távolságra. Szomszédai: észak felől Csorvás, északkelet felől Telekgerendás, délkelet felől Csabaszabadi, dél felől Csanádapáca, délnyugat felől Pusztaföldvár, nyugat felől pedig Orosháza. Déli szomszédja, Csanádapáca felől a 4453-as úton közelíthető meg. Oklevél először 1418-ban említette a települést, ami jelentős falu lehetett, hiszen gerendákkal készült temploma volt.'),
    ('Geresdlak', 'A Geresdi-dombság délkeleti részén fekszik, Pécsváradtól délkeletre. A szomszédos települések: észak felől Erdősmecske, északkelet felől Feked, kelet felől Szűr, délkelet felől Himesháza, dél felől Erdősmárok, délnyugat felől Maráza, nyugat felől Kékesd, északnyugat felől pedig Fazekasboda. Kisgeresd településrész csak egy számozatlan, alsóbbrendű önkormányzati úton érhető el, Geresd nyugati széle után észak felé letérve.'),
    ('Gerjen', 'Pakstól 22 kilométerre délre, Szekszárdtól 27 kilométerre északkeletre fekszik, a Duna jobb partján, a folyó 1514-es folyamkilométer-szelvényében. Vele szemben a bal parton Kalocsa Meszes nevű üdülőterülete (Foktő enklávéja) található. Legközelebbi szomszédai Dunaszentgyörgy, Fadd és a Duna túloldalán Bátya. Az átkelő átadását követően megszűnt a Gerjen és Kalocsa - Meszes közötti kompjárat.'),
    ('Gersekarát', 'Vasvártól nyugat-délnyugatra 10 kilométerre, Körmendtől kelet-délkeletre 16 kilométerre, a Sárvíz-pataktól északra terül el, a Kemenesháton. Területén hosszú ideig erdőség volt. Erre vonultak az 1051-es német támadás csapatai. Gerse első okleveles említése 1272-ből, Karátföldé 1313-ból való. Mindkettő irtásfalu.'),
    ('Gerényes', 'Komlótól északra, Kisvaszar, Ág, Tékes és Vásárosdombó között fekvő település. Közigazgatási területén áthalad a Mecsekjánosi-Vásárosdombó közti 6546-os út, de központjába csak az abból kiágazó 65 176-os út vezet (amely Gerényes utolsó házait elhagyva még továbbhalad kelet felé, a zsákfalunak tekinthető Ág községbe). Gerényes és környéke ősidők óta lakott hely volt, a falu határában, a Csákó és Sásos nevű dűlőkben szántás közben máig sok cseréptöredék kerül felszínre.'),
    ('Geszt', 'Természetföldrajzi szempontból annak keleti peremén fekszik. Határszéli település, legkeletibb fekvésű házai alig fél kilométerre állnak a magyar-román határ legközelebbi pontjától helyezkedik el. Központja mintegy 2 kilométerre van attól. Szomszédai: észak felől Biharugra, nyugat felől Mezőgyán, északnyugat felől pedig Zsadány. Kelet és dél felől Romániához tartozó területek határolják.'),
    ('Gesztely', 'Központja és közigazgatási területének nagy része a folyó bal parti oldalán terül el, de mintegy 4 négyzetkilométernyi terület hozzá tartozik a Hernád jobb parti oldaláról is. A szomszédos települések: észak felől Újcsanálos, északkelet felől Megyaszó, kelet felől Taktaszada, délkelet felől Hernádnémeti, dél felől Hernádkak, nyugat felől pedig Onga.'),
    ('Geszteréd', 'A szomszédos települések: észak felől Nagykálló, kelet felől Balkány, dél felől Hajdúsámson, délnyugat felől Hajdúhadház és Bököny, északnyugat felől pedig Érpatak. Településrészei: Lovastanya Balkánytól 3, Geszterédtől 1 kilométerre található. A Lovas család birtoka volt évekig. 1990-ig Balkányhoz tartozott. Található itt egy magtár. Nyíritanya Geszterédtől 2 kilométerre északra található.'),
    ('Gibárt', 'Encstől 3 kilométerre keletre fekszik, a Hernád mentén. A folyó lényegében kettészeli a települést. A várost leszámítva mindössze két települési szomszédja van: kelet felől Abaújkér, délnyugat felől pedig Hernádbűd. Észak és dél felől is Abaújkérhez tartozó külterületek határolják. A környék már a 4. században is lakott volt. E korból származnak a Hernádbűd és Gibárt határában talált tárgyak: vaskard, vaskés, kardok és lándzsa.'),
    ('Gic', 'Környékét a Bornát-ér és mellékerei hálózzák be, talajadottságai gyengék, magas a talajvíz. Télen gyakoriak a hófúvások. Északra Győr, délnyugatra Pápa, északkeletre Kisbér, Komárom, dél felé Veszprém vonzáskörzetébe tartozik. A környék lokális központja Veszprémvarsány, de az elvándorlás, a térségi mozgások (munkahely, ellátás) a már említett távolabbi központok felé irányulnak.'),
    ('Gige', 'A település Kaposvártól délnyugatra 23 kilométerre fekszik. Ezzel az összekötő műúttal kapcsolódott be a település a megye vérkeringésébe. Két másik szomszéddal, Kisasszonddal és Bárdudvarnokkal a községet csak földút köti össze, korábban tervezték Bárdudvarnokkal a szilárd burkolatú út építését. A község neve már az 1332-37-es pápai tizedjegyzékben szerepel, egy évszázaddal később Hedrehely mezővároshoz tartozott, és Gegeh alakban említették nevét.'),
    ('Gilvánfa', 'A település közigazgatási ügyeit 2008. január 1. óta Magyarmecske, Magyartelek és Kisasszonyfa községekkel együttműködve, a Magyarmecske községben működő körjegyzőség látja el. A faluban cigány nemzetiségi önkormányzat is működik. Pécstől mintegy 35, Sellyétől 10, Vajszlótól 12 kilométer távolságra fekszik, az Ormánságban. A 6-os főútról Szentlőrinc központjában leágazó, Sellye térségéig (Csányoszró-Nagycsány határáig) vezető 5805-ös út mentén fekszik, közúton csak azon érhető el mindegyik említett település felől.'),
    ('Girincs', 'Miskolctól kb. 20 kilométerre délkeletre található, a Sajó mentén. Teljes belterülete és közigazgatási területének túlnyomó része is a folyó bal parti oldalán helyezkedik el, de egy kisebb területrésze átnyúlik a túlpartra is. Kiterjedt külterületei révén észak felől Sajóhídvéggel és Tiszalúccal, északkelet felől Kesznyétennel, dél felől pedig a Sajó túlsó partján fekvő Sajóörössel, Sajószögeddel és Nagycséccsel is határos.'),
    ('Golop', 'Alsógolop a Golopy család ősi fészke, a 14. századtól egyházas hely, Felsőgolop pedig várbirtok volt. A török hódoltsági időkben elpusztult, főként református magyar lakossággal újratelepült falvak birtokosa a 18–20. században a báró Vay család volt, akik Alsógolopon alakították ki birtokközpontjukat. Nekik is köszönhető, hogy a település a 18. század óta a tokaji borvidék része. 1882-ben a két települést Golop néven egyesítették, ezt követően épült fel római katolikus temploma.'),
    ('Gomba', 'Budapest 50 kilométer, Monor 9 kilométer, Üllő 17 kilométer, Tápióbicske 16,5 kilométer, Káva 6,5 kilométer, Pánd 10 kilométer-re van tőle. Nevét Gomba, Gombad, Gombal neveken írták. Először egy 1337-es oklevélben említik. Első ismert pecsétjét – GOMBA.FALV.PÖCHETI felirattal – a 18. század első felében használták, az ezt követőt – SIGILLVM.GOMBA – 1776-1844 között.'),
    ('Gombosszeg', 'A település Magyarország huszonhatodik legkisebb települése lakónépesség szerint. A falu 216 hektáron terül el, amelyen mindössze 37 fő él 33 lakóházban. A faluban a népsűrűség 21,76 fő/ km². A falutól keletre folyik a Cserta folyó. A települést délkelet-kelet felől félkörívben gazdasági hasznosítású erdőrészletek, erdőtagok határolják, ám a település gazdasági szerepe nem számottevő.'),
    ('Gordisa', 'Siklóstól délre, Harkánytól délkeletre fekszik, a Drávától és a horvát határtól mindössze 2 kilométerre. A további szomszédos települések: kelet felől Matty, nyugat felől Drávaszabolcs, északnyugat felől pedig Ipacsfa. Községhatára délen egy rövid (pár száz méteres) szakaszon egybeesik az országhatárral, abban az irányban a legközelebbi szomszédos település a horvátországi Alsómiholjáchoz (Donji Miholjac) tartozó Szentgyörgy (Sveti Đurađ).'),
    ('Gosztola', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik. A község a Lentit övező dombhátak rejtekében fekszik, a szlovén határtól nem messze. A hegyes-völgyes vidék miatt a falu egyutcás, egy dombháton fut végig helyezkedik el. A környéken a legközelebbi vízfolyás a Liponyak-patak, mely a közeli völgyben kialakított tavat is táplálja. A falut körülveszi az erdő, mely vadban igen gazdag.'),
    ('Grábóc', 'Ortodox búcsújáróhely. A Szekszárdi-dombság nyugati részén fekszik, a legközelebbi várostól, Bonyhádtól mintegy 9 kilométerre keletre. Légvonalban nem sokkal nagyobb a távolsága a megyeszékhelytől, Szekszárdtól sem, melytől mintegy 10,5 kilométer választja el, de sokáig a közúton mérhető távolság ennek nagyjából kétszerese volt. 2023-ban azonban átadásra került Grábóc és Szálka közötti beton burkolatú összekötő út, mely jelentősen lecsökkentette a megyeszékhely és Grábóc közti távolságot.'),
    ('Gulács', 'Területe 2330 hektár, ebből a belterület 148 hektár, a külterületen található szántók, rétek, legelők, erdők és gyümölcsösök együttes területe pedig összesen 1690 hektár. A fennmaradó részek művelésből kivett területek (például árkok, utak, vízállások, mocsarak). A település határában húzódik a Tiszának két holtága is. A közvetlen szomszédos települések: észak felől Hetefejércse, északkelet felől Tarpa, délkelet felől Tivadar, dél felől Kisar, délnyugat felől Panyola, északnyugat felől pedig Jánd.'),
    ('Gutorfölde', 'A településhez tartozik Náprádfa és Rádiháza. A településen polgárőrség működik. Területén a Bak-Páka között húzódó 7543-as út halad végig, utóbbiból itt, a település központjában ágazik ki észak felé, Zalatárnok irányában a 7545-ös út és nyugatnak, Mikekarácsonyfa felé a 7546-os út is. Gutorfölde Árpád-kori település, mely a Haholt-Buzád nemzetség ősi birtoka volt.'),
    ('Gyalóka', 'Éghajlata mérsékelt, az Alpok közelsége miatt hűvösebb, szelesebb és csapadékosabb az országos átlagnál helyezkedik el. Első írásos említése 1308-ból ismert. Középkori birtokosai az Osl nemzetségből leszármazott családok és a Kanizsayak voltak. 1544 táján még jobbágyközség volt, Koroknay Péter és Ládonyi Lászlóné, született Gyalókay Dóra tulajdonában.'),
    ('Gyanógeregye', 'A falu a Sorok-patak jobb partján fekszik, Szombathelytől 15 kilométerre délkeletre. Kelet-nyugati irányban a 8702-es, dél-északi irányban pedig a 8703-as út halad végig a területén, közúton csak ezeken érhető el, a szomszéd települések valamelyikének érintésével. Gyanó neve valószínűleg a Jenő törzsnévből ered, Geregye előzménye a szláv Grde személynév.'),
    ('Gyarmat', 'Földrajzilag a Marcal-medence és a Sokoróaljai-dombvidék találkozásánál fekszik. A település felszíne enyhén dombos, nyugatról keletre fokozatosan emelkedik 120 méteres magasságról 162 méterre. Keresztirányban, keleti és nyugati szomszédaival, Gecsével és Csikvánddal a 8305-ös, illetve a 8461-es utak kötik össze.'),
    ('Gyenesdiás', 'A településen polgárőrség működik. A Keszthelyi-öböl északi partján fekszik, közvetlenül Keszthely mellett és Hévíztől 8 kilométerre keletre, szép természeti környezetben. Északról a Keszthelyi-hegység, délről a Balaton határolja. A közvetlenül határos települések: észak felől Vállus, kelet felől Vonyarcvashegy, nyugat felől pedig Keszthely. Balatoni vízterületei révén határos dél felől Balatonberénnyel és Balatonszentgyörggyel is.'),
    ('Gyepükaján', 'Legközelebbi szomszédai Káptalanfa és Csabrendek. A település és környéke az itt talált sírkőmaradványokból következtethetően már a római korban lakott hely volt. A mai falu területén egykor két falu is állt: Gyepü és Kajánföldje. A Gyepű védősávot, elválasztó határt jelentett, nevét 1353-ban említette először oklevél. Gyepű települést 1894-ben egyesítették a szomszédos Kajánföldjével.'),
    ('Gyermely', 'Hozzá tartozik Gyarmatpuszta is. Esztergomtól 28 kilométerre délnyugatra helyezkedik el. Tatabányától 22, Tatától 30 kilométerre keletre, Budapesttől pedig 39 kilométerre nyugatra található. Környező települések: Szomor, Zsámbék, Máriahalom, Epöl, Bajna, Tarján, Csabdi, Mány. Gyermely és környéke az itt talált régészeti leletek tanúsága szerint a már az ősidők óta lakott helyek közé számítható.'),
    ('Gyomaendrőd', 'A város neve Gyoma és Endrőd településrészek neveinek összevonásából keletkezett. Gyoma a régi magyaroktól használt személynév volt. A Szinnyei Merse család ősét pl. Gyoma tehát első Gyoma nevű tulajdonosától vagy lakosától vette nevét. Endrődöt Endre nevű tulajdonosáról vagy lakosáról nevezték el. A szomszédos települések: észak felől Túrkeve, északkelet felől Dévaványa, kelet felől Körösladány, délkelet felől Csárdaszállás és Mezőberény, dél felől Hunya, délnyugat felől Örménykút és Szarvas, északnyugat felől pedig Mezőtúr.'),
    ('Gyugy', 'Lengyeltótitól északkeletre, Szőlősgyörök és Hács között fekvő település. Szőlő- és borgazdasági szempontból a Balatonboglári borvidék részét képezi. Gyugy már az avar korban is település volt. Ennek tanúja a Kossuth utcában talált avar kori temető. A katolikus templom 900 éves, az Árpád-korban épült, romanikus stílusban. A „Gyugynak harangot hozott a víz” legenda miatt lett Gyugy búcsújáró hely. 1322-ben a Dorozsma…'),
    ('Gyula', 'Története az Árpád-korig nyúlik vissza, első írásos említése 1313-ból származik. A 15. században jelentős végvárrá épült ki, a híres téglavárát Maróti János kezdte építeni. A törökök 1566-ban elfoglalták, és közel 130 évig uralmuk alatt tartották. A Habsburgok felszabadítása után a város fokozatosan fejlődött, majd a 19. században fontos ipari és kulturális központtá vált.'),
    ('Gyulaháza', 'Gyulaháza a Közép-Nyírség északkeleti részén fekszik. Nyugati külterületei között elhalad a 4105-ös út is, amely Baktalórántháza és Kisvárda térsége között húzódik. A település feltehetően már az őskorban is lakott terület volt. Több, ebből az időből származó régészeti leletet is feltártak. A település névadója Gyula vezér, akit a község első birtokosaként tartanak számon helyezkedik el.'),
    ('Gyulaj', 'Tamásitól délre, a Gyulaji erdő déli peremén helyezkedik el. Keleti szomszédjával, Szakállyal csak egy önkormányzati fenntartású út köti össze, északi és keleti szomszédai, Tamási és Dalmand felől közúton csak kerülővel közelíthető meg. A község nevével 1357-től találkozunk írásos emlékben. A település valaha két részből állt. Gyulán laktak a magyarok, Jováncán pedig a rácok, ahogy errefelé a törökök kiűzése után itt maradt ortodox vallású délszlávokat nevezték.'),
    ('Gyulakeszi', 'A község a Balaton-felvidéken, Tapolcától alig 4 kilométerre, a Csobánc hegy nyugati lábánál fekszik, a Badacsonytomajt Tapolcával összekötő 7316-os úton. A település déli szélén ér véget az előbbi útba csatlakozva, közel 20 kilométer után a Zánkától induló és a Káli-medence területén kelet-nyugati irányban végighúzódó 7313-as út is. A posta melletti épület kéményén gólyafészek található.'),
    ('Gyál', 'A Pesti-hordalékkúpsíkságon, Budapesttől délkeletre, közvetlenül a főváros határában elhelyezkedő település. Vonattal a 142-es számú Budapest–Kecskemét-vasútvonalon közelíthető meg, amelyen egy állomás (Gyál) és egy megálló (Gyál felső) található a város területén. Gyál területe már a 13. század végén lakott volt, erről egy 1293. augusztus 21-én kelt okirat is tanúskodik.'),
    ('Gyékényes', 'A horvát határ közvetlen közelében fekszik, néhány kilométerre a Dráva folyásától. Az állomás maga egyébként nem Gyékényesen, hanem a szomszédos Zákány közigazgatási területén található. Gyékényes és környéke már a Római Birodalom idején is lakott hely volt, amit az 1971-es ásatásokon előkerült római korból származó leletek is bizonyítanak.'),
    ('Gyód', 'A falu egy völgyben helyezkedik el. Környékét a baranyai falvakhoz hasonlóan szőlők határolják. Mindössze három települési szomszédja van: északkelet és kelet felől Keszüvel, dél felől Regenyével, nyugat és északnyugat felől pedig Pellérddel határos. Közúton ma csak Keszün át közelíthető meg, az 5816-os útból dél felé kiágazó 58 101-es számú mellékúton helyezkedik el.'),
    ('Gyóró', 'Magyarország északnyugati részén, Kapuvártól délre helyezkedik el. Kapuvár és Gyóró között rendszeresen indulnak autóbuszjáratok is. 1241-ből maradt fenn első írásos említése Villa Gyorou alakban. A 13. századig a soproni királyi várnak erdőőrei és katonái lakják. 1401-ben árvíz pusztítja el a települést. A 16. század első felében a Csák nemzetségből származó Kisfaludy és Ládonyi, valamint a szentandrási Monthorok birtokolták…'),
    ('Gyömöre', 'A kedvezőtlenebb fekvésű Gyömöre vasútállomáson, annak kihasználatlansága miatt 2019 decembere óta szünetel a személyforgalom. Ősidők óta lakott hely. Az avar gyűrű feltehetőleg idáig terjedt, legalábbis ennek emlékét sejtjük a határ gyürháti…'),
    ('Gyöngyfa', 'Szigetvártól délkeleti, Szentlőrinctől déli, Sellyétől észak-északkeleti irányban fekszik, majdnem félúton a két utóbbi települést összekötő országút mentén. Közúton elérhető szomszédai északról Királyegyháza, délről Magyarmecske. Közúton Szentlőrinc központja felől közelíthető meg, az 5805-ös úton, vagy délről, Sellye térsége (Csányoszró-Nagycsány) felől ugyanezen az úton helyezkedik el.'),
    ('Gyöngyös', 'Gyöngyöspüspöki, Mátrafüred, Mátraháza, Sástó, valamint Kékestető közigazgatási szempontból a városhoz tartoznak. Északról a Mátra, délről az Alföld határolja, emiatt a Mátra kapujának is szokás nevezni. Északkeleti irányból a Sár-hegy emelkedik a város fölé. Belterületét átszeli a Gyöngyös-patak, a Külső-Mérges-patak, a Belső-Mérges-patak és a Tarján-patak is.'),
    ('Gyöngyösfalu', 'A Gyöngyös-sík északnyugati részén fekszik, Szombathelytől 10 kilométerre északnyugatra, a Gyöngyös-patak mentén. Határa a keleti oldalon sík, nyugaton észak-déli irányban szőlőhegy húzódik. Korábban különálló (mára gyakorlatilag összenőtt) településrészei: Ludad és Seregélyháza a központjától déli, illetve Pöse attól nyugati irányban helyezkedik el.'),
    ('Gyöngyöshalász', 'Gyöngyöstől 4 kilométerre délre, Hatvantól 26 kilométerre keletre fekszik. Belterületét átszeli a Belső-Mérges-patak, amely a község határában éri el a Gyöngyös-patakot. Közúton a 3-as főútról a 3203-as számú mellékúton érhető el. A település határában fekvő Ocskay-laposa elnevezésű terület régészeti feltárásakor 1993-ban vaskori urnatemetőt tártak fel.'),
    ('Gyöngyösmellék', 'A szomszédos települések: észak felől Pettend, északkelet felől Kistamási és Molvány, kelet felől Várad, dél felől Kétújfalu, délnyugat felől pedig Szörény. Közigazgatási területén áthalad a Szigetvárt Sellye térségével (Drávafokkal) összekötő 5808-as út, így ezen közelíthető meg mindhárom említett település felől. Horvátul Meljek (lakócsaiak használják) ill.'),
    ('Gyöngyösoroszi', 'Különálló belterületi településrésze a központjától 7 kilométerre északra fekvő Károlytáró, ahol színesfémbányászat folyt évtizedeken át. Itt mintegy 70 lakóház található. Fontosabb külterületei: Bagolyvár, Vízgát és Templomrét, egy-egy lakóegységgel. A közvetlenül szomszédos települések: észak felől Mátraszentimre, kelet felől Gyöngyössolymos, délnyugat felől Gyöngyöstarján, északnyugat felől pedig Mátrakeresztes (Pásztó része).'),
    ('Gyöngyöspata', 'Magyarország egyik legkisebb városa. Gyöngyöspata a Mátra délnyugati lábánál, Gyöngyöstől 11 kilométer-re nyugatra, a 2402-es és a 2406-os utak találkozásánál fekszik. Ez a terület már a magyarok előtt is lakott volt. Vaskori, avar és a honfoglalás kori sírokat is tártak itt fel. A honfoglalás idején az Aba nemzetségnek jutott a terület. A településen a 10. században várat építettek (Pata vára).'),
    ('Gyöngyössolymos', 'A Kis-hegy déli lábánál elterülő község Gyöngyös központjától 4 kilométer-re északra húzódik meg a Nagy-patak völgyében. [A két település lakott területei közötti távolság kevesebb mint 800 méter.] Jelenlegi közigazgatási határa egészen Galyatetőig nyúlik fel. Lényegében az a Nagy-patak vízgyűjtő-területét foglalja magába. Tájképileg meghatározó eleme a Mátra hegység fő tömegéből előretörő, riolit kőzetanyagú Kis-hegy 383 méteres tömbje, illetve annak délnyugati letörése, a Csák-kő.'),
    ('Gyöngyöstarján', 'A Mátra déli oldalán, a Tarján-patak völgyében helyezkedik el, Gyöngyöstől 6 kilométer-re északnyugatra, valamint Budapest fővárostól mintegy 90 kilométer-re északkeletre. A szomszédos települések: északkelet felől Gyöngyösoroszi, kelet felől Gyöngyössolymos, délkelet felől Gyöngyös, dél felől Nagyréde, nyugat felől Gyöngyöspata, északnyugat felől pedig Mátrakeresztes (Pásztó része).'),
    ('Gyönk', 'Tolna megye középső részén, a Tolnai-Hegyhát tájegységben fekszik. A 65-ös főúttal a központjában induló és Hőgyészig vezető 6315-ös út kapcsolja össze. Gyönk első ismert említése az 1280-as évekből származik, viszont a környék (és Gyönk) már korábban is lakott térség volt. A község területe a török idők alatt is lakott…'),
    ('Györgytarló', 'A Bodrogközben, a Tisza jobb parti oldalán fekszik, Miskolctól közúton 95 kilométerre keletre. A környező települések közül Kenézlő 8, Bodroghalom és Tiszakarád 18-18, Tiszacsermely 19 kilométerre található, a legközelebbi város a szintén 19 kilométerre fekvő Sárospatak. Hivatalosan a községnek nincs Tisza-partja, de a folyó a település központjától alig több mint 2 kilométerre húzódik.'),
    ('Györköny', 'A község Pakstól 15 kilométerre nyugatra, Nagydorogtól 5 kilométerre keletre, Pusztahencsétől 5 kilométerre északra található. A régészeti leletek többek közt egy valamikori római település nyomait jelzik. Ennek korabeli nevét nem tudjuk, csak annyi bizonyos, hogy a Duna menti védvonallal párhuzamosan, kicsit beljebb, egy második településsor vonala rajzolható meg, amely helyek feltehetően utánpótlási és visszavonulási célokat szolgáltak.'),
    ('Gyúró', 'A szomszédos települések: kelet felől Tárnok és Pusztazámor, észak felől Etyek és Alcsútdoboz, nyugat felől Vál, dél felől pedig Tordas. A legközelebbi város Martonvásár. A település jellegzetes dombjai a 194 méter magas Páskom-hegy, a 178 méteres magasságú Öreg-hegy és a 162 méterig emelkedő Új-hegy. A község címere ívelt talpú pajzs, a pajzs alsó részén zöld, hármas halom, melyet vízszintesen a községen átfolyó patak kékje szel át.'),
    ('Gyügye', 'A megye keleti részén, a Szatmári-síkságon fekszik, a Szamos jobb partján. Szomszédai: északkelet felől Zsarolyán, kelet felől Szamosújlak, dél felől Porcsalma, délnyugat felől Rápolt, északnyugat felől pedig Cégénydányád. Két legközelebbi szomszédja Szamosújlak és Cégénydányád, előbbitől 2, utóbbitól mintegy 2,5 kilométer választja el. A környék más fontosabb települései közül Fehérgyarmat 8,5, Mátészalka 29, Tunyogmatolcs 13, Szamossályi 8,5, Hermánszeg pedig 11 kilométer távolságra található.'),
    ('Gyüre', 'A szomszédos települések: észak felől Aranyosapáti, északkelet felől a folyó túlsó partján fekvő Tiszavid és Tiszaszalka, dél felől Nagyvarsány (mellyel szinte egybeépült), délnyugat felől Ilk és Gemzse, nyugat felől pedig Lövőpetri. Közúton a Záhonytól Vásárosnaményig vezető 4115-ös úton érhető el, Aranyosapátin vagy Nagyvarsányon keresztül. Gyüre nevét az oklevelek 1270-1290 között említették először az Isztokról idevezető úttal kapcsolatban.'),
    ('Győr', 'Győr Magyarországon helyezkedik el. A Dunántúl második és Magyarország hatodik legnépesebb települése, továbbá a Nyugat-Dunántúl legnagyobb és a Dunántúl második legnagyobb közigazgatási területű települése, gazdasági, kulturális, egyetemi és sportközpont, az ország egyik legdinamikusabban fejlődő városa. A Bécs–Pozsony–Budapest innovatív tengelyen fekszik, kiváló közlekedési adottságokkal.'),
    ('Győrasszonyfa', 'Pannonhalmától délre, a Bakony hegység északi szélénél, a Sokorói-dombság két domborulata között, többnyire sík szántóterület veszi körül. A község területén talált legrégebbi régészeti leletek Kr. előtt 5000 évvel ezelőtti időből, az újkőkorszakból valók. Ezt követően a vaskorból és a rómaiak korából kerültek elő értékes leletek. Tézslakuti dűlőben épületalapokat, faragott köveket találtak.'),
    ('Győrladamér', 'Egyes szakírók a falu első írásos említését – Nádor lovag tulajdonaként – 1146-ra teszik, majd ezt követően 1271-re, amikor V. István pallosjoggal ruházta fel az akkori birtokos Kurig-családot. Tény viszont, hogy az Árpád-kori Magyarország történetét feldolgozó Györffy György professzor nem tud ezen forrásokról. Az általunk ismert legrégebbi adat 1418-ból, a Hédervári család oklevéltárából származik.'),
    ('Győrszemere', 'A Sokorói (Pannonhalmi)-dombvidék nyugati vonulatának, a Sokorónak északi végén kiépült falu a dombság és a Kisalföld találkozásánál helyezkedik el. Enyhe dombokkal és hosszan elnyúló hátságokkal tűzdelt területen fekszik. Maga a község földrajzi helyzeténél fogva, településszerkezeti szempontból nem mutat egységes képet. Négy elkülöníthető részre tagolódik: a falui, a hegyi, az erdősori és a nagyszentpáli részre helyezkedik el.'),
    ('Győrság', 'Győrság Győrtől 17 kilométer-re délkeletre fekvő önálló község. Északon Töltéstava, keleten, délkeleten Pázmándfalu, délen, délnyugaton Pannonhalma, nyugaton, északnyugaton Nyúl község határolja. Első okleveles említése 1216-ból való Saag néven helyezkedik el. A település az Árpád korban több faluból álló településcsoport volt. Egyikben a várnépek, másikban az udvarnokok, a harmadikban és a negyedikben a Pannonhalmi Bencés Főapátság népei laktak.'),
    ('Győrsövényház', 'Magyarország északnyugati részén, a Tóközben, a Rábca mellett helyezkedik el. Fehértóval a 8503-as út köti össze, északnyugati határszélét pedig súrolja még a 8528-as út is. Győrsövényház az autóút csomópontjától 6, a 85-ös elágazásától 7,5 kilométerre fekszik. A település neve a 14. század végéig Sövényszád volt (ezt Suuenzad alakban írták), ez a név először egy 1396-os oklevélben fordult elő.'),
    ('Győrtelek', 'A település a Szatmári síkságon, Nyíregyházától 67, Csengersimától 29, Mátészalkától 12, Nagyecsedtől 10, Fehérgyarmattól ugyancsak 10 kilométer távolságra található, a kanyargó Holt-Szamos partján. Vonattal a Kocsord–Csenger-vasútvonalon érhető el. A vonalon a falunak két megállója is van, Győrtelek megállóhely és Győrtelek alsó megállóhely. A falu nevét 1380-ban említik először: p.'),
    ('Győrvár', 'A község a Kemenesháton, a Sárvíz-patak völgyében fekszik, Vasvártól 7 kilométerre délre, Zalaegerszegtől 16 kilométerre északra. A közvetlenül határos települések: észak felől Pácsony, északkelet felől Olaszfa, kelet felől Nagytilaj, dél felől Gősfa, délnyugat felől Lakhegy, nyugat felől Hegyhátszentpéter, északnyugat felől pedig Vasvár. A község területén már ősidők óta élnek emberek.'),
    ('Győrzámoly', 'Győrzámoly nevének eredetére több különböző magyarázat létezik: az egyik szerint szláv eredetű és zátony mögötti helyet (zá morje) jelent, a másik szerint a zsámolyból származik (a szigetközi tájszólásban a község neve Zámú vagy Zámol), esetleg a Hédervári család Sámuel nevű tagjának nevéből. Első okleveles említése 1271-ből ismert: ekkor mint Malomsokkal határos települést említik.'),
    ('Győröcske', 'A határ magyar oldalán csak két szomszédja van: északkelet felől Záhony, dél felől pedig Tiszabezdéd. Szlovákia felől (a Tisza túlpartján) a két legközelebbi település Nagytárkány (Veľké Trakany) és Kistárkány (Malé Trakany), úgy tűnik, hogy Győröcske mindkettővel határos.'),
    ('Győrújbarát', 'Magyarország északnyugati részén, Győrtől 8 kilométerre délre, a Sokorói-dombság és a Kisalföld találkozásánál, a dombvidék Ravazd-Csanaki vonulatának északi végén helyezkedik el. Közvetlenül szomszédos települések Győr-Ménfőcsanak és Nyúl, amelyekkel egybeépült településláncot alkot. Bár nem Győr közigazgatási része, a megyeszékhely közvetlen agglomerációs körzetéhez tartozik.'),
    ('Győrújfalu', 'Első írásos említése 1328-ből ismert. Ebből az évből a Magyarország történeti statisztikai helységnévtára Vyfalu, Wyfalu névvel hivatkozik rá. É-i részén, Győr mellett’ 1328>364: Vyfalu, p. ~ Wyfalu”. Később, 1341-ből egy másik írásos emlék maradt fenn arról, hogy a települést Baráti Pál Szentviddel és Esztergővel együtt cserébe átadta a királynak. 1477-től a Héderváry család tulajdonát képezte.'),
    ('Gyűrűs', 'Zalaegerszegtől kelet-északkeletre, Zalaistvánd és Orbányosfa között fekszik. Gyűrűs az őskor óta lakott hely. Az oklevelekben 1292-ben szerepel, mint a Ják nembeli Sitkei család ősi birtoka, Dyrus néven helyezkedik el. Régi egyházas hely, a török többször is elpusztította a falut, 1624-ben is lakatlan pusztaként említették. 1657-ben birtokosa Sitkey Gábor szabadságlevelet adott a gyűrűsi faluhelyre települőknek.'),
    ('Gáborján', 'Berettyóújfalutól keletre fekszik, nem messze a román határtól. A szomszédos települések: észak felől Konyár, kelet felől Hencida, délkelet felől Bojt, dél felől Váncsod, nyugat felől pedig Szentpéterszeg. Csak közúton közelíthető meg, közvetlen szomszédai közül Szentpéterszeg, illetve Hencida felől a 4812-es, Mezőpeterd-Váncsod felől pedig a 4815-ös úton helyezkedik el.'),
    ('Gáborjánháza', 'Igazgatási szempontból a rédicsi körjegyzőséghez tartozik. Hetés tájegységben fekszik, közvetlenül a szlovén határ mellett. A határ magyar oldalán mindössze két települési szomszédja van: kelet felől a másfél kilométerre lévő Szijártóháza, északnyugat felől pedig Bödeháza, mely a központjától mintegy három kilométerre esik. A szlovén oldalon a legközelebbi település Göntérháza (Genterovci), kevesebb, mint két kilométerre délnyugatra helyezkedik el.'),
    ('Gádoros', 'A megye nyugati szélén, Orosházától északra fekvő település. Közigazgatási területe emellett dél-délkelet felől határos Orosházával, délnyugatról pedig Árpádhalommal is. A megyeszékhely Békéscsaba irányából két, közel azonos hosszúságú útvonalon is elérhető, vagy Kondoros, vagy Csorvás érintésével, Budapest irányából pedig Szarvas érintésével, Nagyszénáson keresztül.'),
    ('Gálosfa', 'Kaposvártól délkeletre, Hajmás és Bőszénfa között fekszik. Gálosfa nevét 1425-ben említette először oklevél Galusfalva alakban írva. Az oklevél szerint Szerdahelyi Csepel János fiai, Imre és Dancs, valamint Szerdahelyi Dersfi Márton, a zselicszentjakabi apátsággal szemben tartottak jogot e helységre. 1489-ben Szerdahelyi István birtokaként volt említve.'),
    ('Gánt', 'A csapadék karsztvíz formájában raktározódik. A Vértes hegység földtani felépítése szerint fődolomitra épül, amit bauxitréteg fed. Ez volt Magyarország első, Európában is ismert bauxitlelőhelye. Gánt első ismert említése 1193-ból származik, amikor III. Béla király egy oklevelében bukkan fel a neve. A török időkben teljesen elnéptelenedett. 1750-es években kezdték benépesíteni szlovák, majd német telepesek. 1776–1777-ben megépült a katolikus templom. 1781-ben már katolikus iskolája is volt. 1920-ban fedezték…'),
    ('Gárdony', 'Fontosabb városrészei: Gárdony, Agárd, Dinnyés, Csiribpuszta. A Velencei-medence és a Közép-Mezőföld határán, a fővárostól 50, a megyeszékhelytől, Székesfehérvártól 17 kilométerre helyezkedik el. A település gazdaságát a turizmus határozza meg, vonzerejét elsősorban a Velencei-tó strandjainak köszönheti. A város utóbbi időkben tapasztalható komoly fejlődésének egyik fő oka lehet a nagy beköltözési vágy.'),
    ('Gátér', 'Gátér a Dél-alföldi régióban, a Kiskunság keleti részén található. Kelet és északkelet felől Csongrád, nyugat és északnyugat felől Kiskunfélegyháza határolja, további szomszédai: délkelet felől Felgyő és Tömörkény, délnyugat felől pedig Pálmonostora. A környező kisebb települések közül Tömörkénnyel és Pusztaszerrel a 4518-as, Pálmonostorával a 4503-as út köti össze.'),
    ('Gávavencsellő', 'A korábban önálló Gáva és Vencsellő települések egyesítésével jött létre. A Tokaj és Nyíregyháza turisztikai térség része. A Rétköz nyugati peremén helyezkedik el. A megyeszékhely Nyíregyházától körülbelül 30 kilométerre északnyugatra található. Az egykor önálló települések közül Gáva ma a keleti, Vencsellő pedig a nyugati településrészét képezi. Aránylag nagy kiterjedésű, jobbára lakatlan külterületi településrész tartozik hozzá a Tisza jobb parti oldalán.'),
    ('Géberjén', 'A környező települések közül Mátészalka 14, Fehérgyarmat 9, Kocsord 6, Fülpösdaróc 3, Győrtelek 2 kilométerre található. Közigazgatási területének érdekessége, hogy enklávéként közrefog egy nagyjából háromszög alakú, Győrtelekhez tartozó, nagyjából 45 hektáros területet. Neve puszta személynévből vált településnévvé, és ez a falu igen korai, 10–13. század közötti keletkezésére utal.'),
    ('Géderlak', 'A település a Kalocsai-Sárköz északnyugati peremén, a Duna bal partján fekszik. Belterülete 110 hektár, a hozzá tartozó külterület 1700 hektár. Kalocsa városától 16, Dunapataj nagyközségtől 9 kilométerre fekszik. Ezek a szerzetesek, papok az érsekséghez tartozó GEDIR dombjára építették a prépostságot, melynek maradványait a mai templom alapozásakor megtalálták…'),
    ('Gégény', 'A közvetlenül szomszédos települések: kelet felől Pátroha, délkelet felől Nyírtass, dél felől Berkesz, délnyugat felől Demecser, északnyugat felől pedig Dombrád. A térség fontosabb települései közül Demecser 4, Pátroha 5, Berkesz és Nyírtass 6-6, Székely 7,5, Dombrád 11, Nyírbogdány 12, Ajak pedig 13 kilométer távolságra található. Feketetanya Gégény centrumától 4 kilométerre fekszik, északi irányban. 2011-es adatok szerint a lakónépessége 54 fő, a lakások száma 20 volt.'),
    ('Gérce', 'A Kemenesalján fekszik. A szomszédai: észak felől Sitke, kelet felől Vásárosmiske, dél felől Káld, északnyugat felől pedig Sárvár. Közigazgatási területei délnyugati irányban egy aránylag hosszabb szakaszon érintkeznek Bejcgyertyános, és egy sokkal rövidebb szakaszon Sótony határszélével is, a két utóbbi község között fekvő Nyőgérrel ellenben nem határos.'),
    ('Gétye', 'Gétye a Zalai-dombság legkeletibb vonulatán fekszik. A Zala folyótól Bókaháza zárja el. Zsáktelepülésnek tekinthető, közúton ugyanis csak a 75-ös főútból Zalaapáti nyugati külterületén északnak kiágazó 73 211-es számú bekötőúton érhető el. Bókaháza, Zalacsány és Szentpéterúr felé csak kis forgalmú, változó minőségű, de jobbára szilárd burkolat nélküli utak vezetnek.'),
    ('Gógánfa', 'Nem tévesztendő össze az Egyházasfaluhoz csatolt Kisgógánfa településsel, amelyet szintén említenek Gógánfa néven helyezkedik el. A Marcal jobb partján fekszik. A szomszédok települések: északkeletről Ukk, délkeletről Zalagyömörő, északnyugatról pedig Dabronc. A legközelebbi város Sümeg, körülbelül 9 kilométerre délkeletre helyezkedik el. Több eredete is lehet a település nevének.'),
    ('Gór', 'A Répce jobb partján fekszik, Büktől 5 kilométerre délkeletre. Északi részén terül el a Répce árvízi vésztározója, a Bük–Bő–Gór-víztározó. A szomszédos települések: észak felől Bő, északkelet felől Chernelházadamonya, kelet felől Répceszentgyörgy, dél felől Szeleste, délnyugat felől Acsád, nyugat felől Csepreg, északnyugat felől pedig Bük.'),
    ('Göd', 'A Dunakanyar délkeleti részén fekszik, a Vác–Pesti-Duna-völgyben, a váci Duna-ág bal partján. A "Dunakanyar kapujaként" is szokták nevezni. Budapesttől mintegy 25 kilométerre északra, Váctól 9 kilométerre délre található. A város keleti határában a Pesti-hordalékkúpsíkság keskeny északi nyúlványa húzódik. A várost függőlegesen átszelő Budapest–Szob-vasútvonalnak Gödön három megállási pontja van: Alsógöd megállóhely…'),
    ('Gödre', 'Közigazgatási területe változékony domborzatú, egyes részei dombosak, más részei egy elnyúló völgyben helyezkednek el. A mai Gödre három, egykor különálló település egyesítésével jött létre: ezek közül Gödre volt a leginkább központi fekvésű, északi szomszédja volt Kiskeresztúr – 1954-es egyesítésüktől a Gödrekeresztúr nevet viselték –, a harmadik településrész pedig az 1969-ben előbbiekkel egyesített Gödreszentmárton, mindkettőtől jó 2 kilométerre keletre.'),
    ('Gödöllő', 'Legismertebb nevezetességei a Grassalkovich-kastély és a Magyar Agrár- és Élettudományi Egyetem. A város szülötte Török Ignác honvéd tábornok. Gödöllő Budapesttől 30 kilométerre északkeletre, a Gödöllői-dombságban a Rákos-patak széles völgyében terül el. (Az északnyugati irányban szomszédos Szada településsel szinte teljesen összeépült.) Az átlagosan 1-3 méter széles patak Szada délkeleti határában ered.'),
    ('Gölle', 'A módos gazdák lakta[forrás?] település címerében a korona és egy fehér ló látható. A hagyomány szerint a tatárok elől menekülő IV. Béla király és kísérete ezen a tájon eltévedt és az ott élő jobbágyok és kanászok mutatták meg a Dalmáciába vezető utat. Béla király lovát hívta Göllének. Ezért a település róla kapta a nevét. A községet egy 1550-ből származó oklevél említi először.'),
    ('Gömörszőlős', 'A Putnoki-dombságban, völgyekkel szabdalt területen, a Keleméri-patak völgyében helyezkedik el, Aggtelektől 15 kilométerre, Miskolctól közúton 45 kilométerre északnyugatra, a szlovák határ mellett. A régi neve, Poszoba, szláv személynév. Írták: Pozoba, Pozuba és Puzaba alakban is. 1906-tól lett Gömörszőlős, ez régi, nagy kiterjedésű szőlőbirtokra utal.'),
    ('Gönc', 'Hazánk legészakibb városa, emellett a megye második legkisebbje. A megyeszékhely Miskolctól mintegy 65 kilométerre északkeletre helyezkedik el, közel a szlovák határhoz, a Hernád völgyében, a folyó bal parti oldalán. Az ország legészakibb fekvésű (é. sz. 48° 28′ 16″) városi rangú települése. A közvetlenül határos települések: észak felől Zsujta, kelet felől Telkibánya, délkelet felől Fony, dél felől Göncruszka, nyugat felől Hernádszurdok, északnyugat felől pedig Hidasnémeti és Tornyosnémeti.'),
    ('Göncruszka', 'Az államalapítás óta Abaúj (vár)megye települése, melynek eredeti székhelye Kassa, ami csupán 30 kilométerre van. Miskolctól 60 kilométerre északkeletre található, a Hernád völgyében, a folyó bal (keleti) partján. A legközelebbi város a 4 kilométerre északra lévő Gönc, két másik szomszédja délkelet felől Hejce (7 kilométerre), dél felől Vilmány (4 kilométerre).'),
    ('Gönyű', 'Jelentős kikötőtelepülés. Magyarország északnyugati részén, az ott határfolyóként húzódó Duna jobb partján, a Kisalföld északkeleti peremén, a Győr–Tatai-teraszvidéken helyezkedik el, a megyeszékhely Győrtől 16 kilométerre keletre, csodálatos természeti környezetben. Északról a Duna határolja, délről pedig természetvédelmi területnek nyilvánított erdő.'),
    ('Görbeháza', 'Különálló településrésze Bagota, mely a központjától 9 kilométerre délre fekszik. A közvetlenül határos települések: északkelet-kelet felől Hajdúnánás, délkelet felől Hajdúböszörmény, dél felől Balmazújváros, délnyugat felől Újszentmargita, nyugat felől Folyás, északnyugat felől pedig Polgár.'),
    ('Görcsöny', 'A közeli községekre oly jellemzően kialakult régi falurésze völgyben, új lakótelepe pedig fennsíkon helyezkedik el. Hozzá tartozik még Keresztespuszta külterületi településrész is, mely a község északi határa közelében fekszik. A szomszédos települések: észak felől Aranyosgadány és Pellérd, kelet felől Regenye, dél felől Ócsárd és Kisdér, délnyugat felől Baksa, északnyugat felől pedig Zók.'),
    ('Görcsönydoboka', 'Mohácstól északra helyezkedik el, a Baranyai-dombság keleti részén, Somberek nyugati szomszédjában, a Csele-patak mellett. A mai települést alkotó, egykor különálló két falu ma is jól láthatóan elkülönül egymástól, Cselegörcsöny a nagyobb és északabbra fekvő településrész, míg Cseledoboka az előbbi központjától bő egy kilométerre délkeletre helyezkedik el.'),
    ('Görgeteg', 'Közigazgatási területéhez tartozik az egykori Rinyatamási, ahol gróf Széchenyi Aladár felépítette a ma is álló vadászkastélyt. Görgeteg nevét 1360-ban említette először oklevél Gurgeteg alakban írva, majd 1436-ban Gergetheg írásmóddal fordul elő. Mint a Veszprémi egyházmegye birtoka. Az 1536 évi adólajstrom szerint Pekry Lajos, 1550-ben Alya Mátyás volt a birtokosa.'),
    ('Gősfa', 'A közvetlenül határos települések: észak felől Győrvár, kelet felől Nagytilaj, délkelet felől Pókaszepetk és Kemendollár, dél felől Vasboldogasszony, délnyugat felől Egervár, nyugat-északnyugat felől pedig Lakhegy. Gősfa első írásos említése 1389-ből ismert. A középkorban az egervári uradalomhoz tartozott. 1532-ben a Kőszeg fele vonuló török…'),
    ('Hagyárosbörönd', 'Két különálló településrész alkotja, a kiterjedtebb Börönd és a lényegében egy utcás Hagyáros, az előbbitől jó másfél kilométerre keletre. A közvetlenül határos települések: észak felől Sárfimizdó, északkelet felől Szentpál, kelet felől Vitenyéd, délkelet felől Felsőbagod (mindhárom utóbbi Bagod része), dél felől Zalaszentgyörgy, délnyugat felől Velence (Vaspör része), nyugat felől Vaspör, északnyugat felől pedig Ozmánbük és Halastó.'),
    ('Hahót', 'Korábban különálló településrészei voltak Alsó- és Felső-Hahót, de ezek már teljesen összeépültek, 1901-ben hivatalosan is egyesítették őket Hahót néven helyezkedik el. Szokás nevezni Hahótot Magyarország egyik leghosszabb községének is, mivel eredetileg egyutcás település volt és lakott területrészei szokatlanul hosszan – mintegy 6 kilométeres hosszúságban – nyúlnak el az észak-déli tengelyét képező műút mellett.'),
    ('Hajdúbagos', 'A szomszédos települések: észak felől Debrecen, kelet felől Hosszúpályi, dél felől Konyár, délnyugat felől Derecske, nyugat felől Sáránd, északnyugat felől pedig Mikepércs. Központjába azonban csak a 48 104-es számú mellékúton lehet eljutni. A vasútnak egy megállási pontja volt a határai között, Hajdúbagos megállóhely, a belterülettől kissé északra.'),
    ('Hajdúböszörmény', 'A megyeszékhely után a megye második legnépesebb települése, területi kiterjedés szerint pedig az egész országban a negyedik legnagyobb. A Hajdúság tájegységnek a legnagyobb települése, nevezik a „hajdúk fővárosának” is. Hajdúböszörmény mai nagy kiterjedésű határával együtt az Alföld, közelebbről a Tiszántúl egyik jellegzetes települése, olyan város a Nyírség és a Hajdúság találkozásánál, amely megjelenésében ma is hordozza történetiségét.'),
    ('Hajdúdorog', 'A város területe északon Nagycserkesz és Tiszavasvári területeivel határos, de ezeket a településeket az észak felé vezető tokaji úton nem lehet elérni aszfalt borítású műúton. Nyugatra Hajdúnánás, délre Hajdúböszörmény, keletre pedig Kálmánháza és Újfehértó közigazgatási területei találhatók. Közúton a várost 2007 óta az M3-as autópályán a legegyszerűbb elérni, amelynek 203-as, hajdúnánási kijárata van a legközelebb Hajdúdoroghoz.'),
    ('Hajdúhadház', 'Közigazgatási területe 8780 hektár (87,8 négyzetkilométer). A közvetlen szomszédos települések: észak felől Téglás, északkelet felől Bököny és Geszteréd, délkelet felől Hajdúsámson, dél felől Bocskaikert, nyugat felől Hajdúböszörmény. Dél-délnyugat felől egy rövid szakaszon határos még Debrecennel is.'),
    ('Hajdúnánás', 'A megye ötödik legnépesebb települése. A Hajdúságban, az Alföld északi peremén található, Debrecentől 40 kilométerre északnyugatra, Nyíregyházától 25 kilométerre délnyugatra. Területe 259,62 km², ebből 12,54 km² a belterület. Legnépesebb különálló településrésze Tedej, mely az északi határszéle közelében fekszik. A közvetlenül határos települések: észak felől Tiszavasvári, kelet felől Hajdúdorog, dél felől Hajdúböszörmény, nyugat felől Görbeháza, északnyugat felől pedig Polgár.'),
    ('Hajdúszoboszló', 'A megyeszékhely Debrecen és Hajdúböszörmény után a megye harmadik legnépesebb települése. Elismertségét elsősorban gyógyvizének és gyógyfürdőjének köszönheti. Hajdúszoboszló Magyarország egyik minősített gyógyhelye, ahol 1925-ben termálvizet találtak, és azt a gyógyhatásoknak köszönhetően nem sokkal később gyógyvízzé minősítettek. Az üdülőhely a kereskedelmi szálláshelyeken eltöltött vendégéjszakák tekintetében Magyarország harmadik legnépszerűbb települése Budapest és Hévíz után.'),
    ('Hajdúszovát', 'A szomszédos települések: kelet felől Derecske, dél felől Földes, délnyugat felől Tetétlen, nyugat felől Kaba, északnyugat felől pedig Hajdúszoboszló. [Észak felől ez utóbbi városhoz tartozó külterületek határolják.] Csak közúton érhető el, Hajdúszoboszló felől a 4804-es, Debrecen, illetve Földes felől a 4805-ös, Derecske felől pedig a 4816-os úton.'),
    ('Hajdúsámson', 'A legnagyobb olyan település Magyarországon, ahol több férfi él, mint nő. Az Alföld határ menti térségében, Debrecentől 10 kilométerre északkeletre helyezkedik el. Részei Martinka, Melegoldal, Oncsatelep és Sámsonkert. Melegoldal (vagy Melegoldal tanya) 3 kilométerre délkeletre fekszik Hajdúsámsontól. Hajdúhadházzal a 4902-es, Vámospérccsel a 4908-as út köti össze.'),
    ('Hajmás', 'Kaposvártól körülbelül 14 kilométerre délkeletre fekszik a Surján-patak völgyében. A közvetlenül határos települések: észak felől Szentbalázs, észak-északkelet felől Kaposkeresztúr, kelet felől Gödre, délnyugat felől Gálosfa, nyugat felől Kaposgyarmat, északnyugat felől pedig Cserénfa. Első írásos említése 1346-ból ismert, ekkor Szerdahelyi Dersfi Péter birtokába került, majd 1425-ben Haghmasnak írták a nevét.'),
    ('Hajmáskér', 'A Balaton északkeleti szegletétől 14 kilométerre fekszik, Várpalota és Veszprém között nagyjából félúton, a Keleti-Bakony délkeleti lejtőin. A legközelebbi települések: dél felől Sóly, kelet felől Öskü, nyugat felől pedig a Veszprémhez tartozó Gyulafirátót (észak felől a községet a Tési-fennsík 400 méter feletti, kietlen magaslatai határolják).'),
    ('Hajós', 'Közigazgatási területe 8990 hektár, ebből 289 hektárnyi belterület. A települési szomszédai észak felől Homokmégy, északkelet felől Császártöltés, kelet felől Kéleshalom, délkelet felől Borota, dél felől Érsekhalma, délnyugat felől Nemesnádudvar, nyugat felől Dusnok, északnyugat felől pedig Miske. Évszázadokig a kalocsai érsekség uradalmához tartozott.'),
    ('Halastó', 'A halastó olyan, vízfeltöltést és -lecsapolást biztosító, a gazdálkodás során teljesen lecsapolható, műtrágyázott vízterület, amely érvényes vízjogi engedéllyel rendelkezik, és a haltenyésztés céljait szolgálja. A halastó leeresztőzsilippel van ellátva, mögötte halágy található, itt gyűjthetőek össze a halak a tó teljes lecsapolásakor. Az édesvízi haltenyésztés termelési céljai közül első helyen áll a halhús, mint emberi táplálék előállítása.'),
    ('Halimba', 'Területén jó minőségű és nagy mennyiségű krétakori bauxittelepeket fedeztek fel, amelyek kitermelése 2013. február végén befejeződött. A Bakony délnyugati lábánál fekvő település, alatta húzódik a Dunántúl egyik legjelentősebb karsztvíz-bázisa. Északkeletről Ajka-Padragkút, nyugatról Szőc, déli irányból Taliándörögd község határolja. A község közelében honfoglalás előtti időkből csiszolt kőbaltát, kelta sírokat és római kori szarkofágot találtak.'),
    ('Halmaj', 'A Hernád völgyében fekszik, a folyó jobb parti oldalán, a megyeszékhely Miskolctól mintegy 25 kilométerre északkeletre. A közvetlenül szomszédos települések: észak felől Kázsmárk (kb. 4 kilométer), kelet felől Kiskinizs (4 kilométer), délkelet felől a Hernád túlpartján fekvő Nagykinizs és Szentistvánbaksa, délnyugat felől pedig Aszaló (5 kilométer).'),
    ('Halmajugra', 'Gyöngyöstől 10 kilométerre keletre fekszik, keletről a Bene-patak, északról a Borhy-völgyi-patak határolja. Településrészei Gyöngyöshalmaj és a tőle keletre fekvő, kisebb Hevesugra helyezkedik el. A közvetlenül határos települések: észak felől Markaz, kelet felől Detk, dél felől Ludas, délnyugat felől Karácsond, nyugat felől pedig Visonta. Határszélét nyugaton érinti még a 24 145-ös út is.'),
    ('Halogy', 'Halogy a Vasi-Hegyhát szélén helyezkedik el, néhány kilométernyire Körmendtől és hasonló távolságra a magyar-osztrák államhatártól, melynek a településhez legközelebbi pontja Kemestaródfa külterületén található (légvonalban a legközelebbi ausztriai település Lovászad). A közvetlen szomszédos települések észak felől Horvátnádalja (Körmend településrésze), északkelet felől Körmend, kelet felől Nádasd, déli irányból Daraboshegy, nyugat felől pedig Csákánydoroszló.'),
    ('Halászi', 'Halászi Mosonmagyaróvártól 4 kilométerre fekszik a Mosoni-Duna partján, a Szigetközben. A községhez tartozik a szomszédos Arak település mintegy 170 lakossal. A település a 14 106-os úton érhető el Halászi és Darnózseli felől is. Arak első okleveles említését 1413-ból ismerjük. Neve feltehetően az árok szóból ered. Arak önállósága 1934-ben szűnt meg, amikor Halászihoz csatolták, majd 1950–1976 között Máriakálnokhoz tartozott, ezt követően pedig ismét Halászi része lett.'),
    ('Halásztelek', 'A Csepel-sziget északi részén, a Duna főágának bal parti oldalán található, annak Érddel szemben elterülő oldalán. Dél felől a tököli repülőtér határolja. A mai település területén már a kőkorszakban is élt ember. Ezt a Duna közeléből előkerült lelet bizonyítja. A területen jeges és őszi árvizek által időről-időre lakhatatlanná tett kis szigetek…'),
    ('Hangony', 'Ózdtól 9, Miskolctól 55 kilométerre nyugatra fekszik, a Hangony-patak völgyében. A környező települések közül Kissikátor 2, Domaháza 9 kilométerre található, a legközelebbi város Ózd. Csak közúton érhető el, a 2306-os úton. Neve Anonymus Gesta Hungaroroumában jelenik meg először, ekkor még a völgyön végigfutó Hangony-patak neveként (fluvium Hongun).'),
    ('Hangács', 'A település a Cserehát délkeleti szélén fekszik, Miskolctól körülbelül 25 kilométerre északra, a 7 kilométer hosszú Hangács-patak völgyének végében, három irányból domboktól körülvéve. Szomszédos települések: Nyomár, Damak, Hegymeg, Tomor, Homrogd, Alsóvadász és Boldva. Ezen a helyzetet szüntette meg a kétezres évek elején az Európai Unió támogatásával Damak felé megépült, a közforgalom számára is nyitott, szilárd burkolatú mezőgazdasági út.'),
    ('Hantos', 'A Mezőföld középső részén fekszik, Sárosd szomszédságában. A környező települések közül Nagylók 4,5, Sárosd 6,5, Szabadegyháza 12,5, Mezőfalva 11, Sárbogárd pedig 17 kilométer távolságra található. Közvetlenül határos keleten Perkátával is, de e településsel nincs közúti kapcsolata. Hantos és környéke már ősidők óta lakott hely volt. Területén kőkori és római kori leletek kerültek felszínre.'),
    ('Harasztifalu', 'Az osztrák határ közelében helyezkedik el, nyugati határszélét az államhatártól alig egy kilométernyi távolság választja el. A szomszédos települések: észak felől Nagykölked, északnyugat felől Rádóckölked, délkelet felől Körmend, dél felől a városhoz tartozó Felsőberkifalu, délnyugat felől Magyarnádalja és Vasalja, északnyugat felől pedig Szentpéterfa.'),
    ('Harc', 'A község a Tolnai-Hegyhát délkeleti határában, a Sió felett, néhány kilométerre a Hegyhát legdélibb pontján fekvő Leányvártól északra található. A két emelkedő utca három domb közötti két völgyben települt. A vidék jellegét alapvetően a Sió közelsége határozza meg, ez a folyó, pontosabban csatorna a község keleti határa helyezkedik el. A Siót és Sárvizet a 18-19. században szabályozták, ekkor ármentesítették a harci határt is.'),
    ('Harka', 'Magyarország északnyugati részén, az Alpokalján, Soprontól 5 kilométerre délre, közvetlenül az osztrák határ mellett helyezkedik el. A határ magyar oldalán csak két települési szomszédja van: észak felől Sopron, kelet felől pedig Kópháza. Délkeleti szomszédja Sopronkeresztúr (Deutschkreutz), délnyugat felől pedig Hasfalva (Haschendorf) és Sopronnyék (Neckenmarkt) településekkel határos.'),
    ('Harkakötöny', 'Az ország dél-alföldi részén fekszik, nagyjából félúton Kiskunhalas és Kiskunmajsa között. A szomszédos települések: északkelet felől Bodoglár [egykor önálló, ma Kiskunmajsához tartozó falu], kelet felől Kiskunmajsa, délnyugat felől Kiskunhalas, északnyugat felől pedig Tázlár. Csak kevés híja van annak, hogy nem határos dél felől még Zsanával is. A Harka név egy 1451. évi okmányon fordul elő először.'),
    ('Harkány', 'Egyedülálló, kénes gyógyvizének értékét a 19. század óta használják ki. A Drávatamási– Harkányfürdő–Siklós vonal jelöl ki a Dráva mentén egy Harkány térségi területet, a Szigetvár–Harkány–Nyárádi pedig egy löszfelszínt határol. A Zselicből, Mecsekből erre a területre vízfolyások futnak. Drávatamási, Harkányfürdő vonaltól északi irányba kavicsos rétegeket a talajban nem „harántoltak”, ebből arra következtettek, hogy a Dráva nem járt arra a pleisztocén idejében helyezkedik el.'),
    ('Harsány', 'Miskolctól közúton 11 kilométerre délre fekszik, a Csincse-patak mentén. A környező települések: északkelet felől Bükkaranyos (kb. 5 kilométer), délkelet felől Emőd (10 kilométer), dél felől Vatta (8 kilométer), délnyugat felől Borsodgeszt, északnyugat felől pedig Kisgyőr (9 kilométer). A település nevének eredete vitatott.'),
    ('Harta', 'Horvátul a településnek két ismert neve van. A felsőszentivániak Karta, a bátyaiak Hartava néven említették. A Duna mellett helyezkedik el, Budapesttől mintegy 100 kilométerre délre. A szomszédos települések: észak felől Solt, északkelet felől Dunatetétlen, kelet felől Akasztó, délkelet felől Kiskőrös, dél felől Dunapataj, nyugat felől Madocsa, északnyugat felől pedig Bölcske, utóbbi két település már a Duna túlsó partján terül el.'),
    ('Hatvan', 'Nevét a kézenfekvő tőszámnév helyett a besenyő-török eredetű chatwan/chatmanból valószerű származtatni. Jelentése „töredéknép, résznép”: a magyarországi besenyőket az ország különböző részein telepítették le, akik identitásukat és együvé tartozásukat új hazájukban a Hatvan helységnév által tartották fenn. Némelyek tévesen annak tulajdonítják Hatvan nevét, hogy bár légvonalban 51 kilométerre fekszik Budapesttől, autóval viszont 60 kilométer.'),
    ('Hedrehely', 'A Zselic délnyugati lankáin, Kaposvártól 33 kilométerre, délnyugatra fekszik. A legközelebbi város, Kadarkút 6 kilométerre található. A település környéke már a római korban lakott volt, nevét viszont csak az 1332-37-es pápai tizedjegyzékben említik először írásban, Hedruch alakban. 1403-ban itt ültek össze a Zsigmond uralmával elégedetlen urak, hogy az ország lakosságához kiáltványt intézzenek. 1443-ban Héderváry Lőrinc nádor birtokába került a település, amely ekkorra városi rangot kapott.'),
    ('Hegyesd', 'A Tapolcai-medence és a Déli-Bakony találkozásánál, az Eger-víz mellett helyezkedik el. A közvetlenül határos települések: északkelet felől Monostorapáti, délkelet felől Szentbékkálla, dél felől Mindszentkálla, délnyugat felől Diszel (Tapolca része), északnyugat felől pedig Sáska. Nyugat felől a legközelebbi település Zalahaláp, de a közigazgatási területeik nem érintkeznek.'),
    ('Hegyeshalom', 'A település német neve Straß-Sommerein. Samaria al. nom Hegyeshalm, 1451 Poss. Hegyeshalm, 1462 Samarya alias Heghalom, 1550 Hegyeshalom, 1570-71Hegieshalom, 1649 Hegyes Halom, 1659 Hegyeshalom, 1674, Szumeriein sen Hegyeshallom, 1680 Hegyeshalom, 1696 Hegyeshalom Sommerein am Strass 1773 Hegyes.Halom, Strass Sumerein Horvátul két neve ismert. A bezenyeiek Štruos-nak, a fertőhomokiak Smierna-nak nevezik a nagyközséget.'),
    ('Hegyfalu', 'A Répce mentén, annak jobb parti oldalán fekszik. A szomszédos települések: észak felől Tompaládony, északkelet felől Vasegerszeg, délkelet felől Zsédeny, délnyugat felől Pósfa, nyugat felől Répceszentgyörgy, északnyugat felől pedig Chernelházadamonya és Mesterháza. Közigazgatási területe délen messze elnyúlik a községtől, ott ezért érintkezik még az amúgy távolabb fekvő Rábapaty határszélével is.'),
    ('Hegyháthodász', 'A közvetlenül határos települések: észak felől Nagymizdó, északkelet felől Szarvaskend, kelet felől Halastó, délkelet felől Ozmánbük, délnyugat felől Vaspör, nyugat felől Nádasd, északnyugat felől pedig Hegyhátsál. Lakott területe azonban csak arról letérve érhető el, északi irányból a 74 166-os számú mellékúton, vagy kelet felől, egy jelöletlen elágazástól, egy önkormányzati úton.'),
    ('Hegyhátmaróc', 'Mágocstól 11 kilométer-re található. A környező települések Szászvár, Bikal, Egyházaskozár, Tófű, Vékény és Köblény. Hegyhátmaróc neve a morva jelentésű marót, maróc szóból ered. A település első írásos említése 1328-ból származik, egy oklevélben ekkor Morouth néven szerepel, majd 1399-ben már Marócként említik. Az Egyházasmarócnak és Nagymarócnak is nevezett falu a szalatnaki uradalom része volt, földesurai a Treutel és a Lévai család voltak.'),
    ('Hegyhátszentjakab', 'A község a Vasi-Hegyháton, Körmendtől 20 kilométerre délre, Zalalövőtől 7 kilométerre északnyugatra helyezkedik el. A falu keletkezéséről és nevének eredetéről sincsenek konkrét adatok, csak mondák maradtak fenn a szájhagyomány útján helyezkedik el. Azonban ami biztos, hogy a község már a római korban is lakott volt, ezt bizonyítják a határában az 1970-es években megtalált római sírok.'),
    ('Hegyhátszentmárton', 'Az Őrségi Nemzeti Parkban található. Hegyhátszentmárton Árpád-kori település. Első temploma feltehetően még a 13. században épült. A 16-17. században az Ivánczy család tulajdona, amelynek egyik tagja, Ivánczy Péter az 1500-as évek első felében a település északi részén kisebb várkastélyt épített. A kastély 1580 körül elpusztult, de árkai, sáncai ma is jól láthatóak.'),
    ('Hegyhátszentpéter', 'Mindkét várossal közvetlen autóbuszjáratok kötik össze. 1381-ben Zentpeturfolua alakban említik először. 1404-ben Poss. Zedthpeterfalua, 1450-ben Zenthpeterfolua néven szerepel. A Hídvégi, majd a Gersei Pető család birtoka volt. Postája Andrásfa, távírója Győrvár. Kath. temploma 1700. körül épűlt.'),
    ('Hegyhátsál', 'A Felső-Kemenesháton fekszik, a legközelebbi várostól, Körmendtől 7 kilométerre délkeletre. A közvetlenül határos települések: északkelet felől Nagymizdó, délkelet felől Hegyháthodász, nyugat felől Nádasd, északnyugat felől pedig Katafa. A korábbi nyomvonal ezután egy ideig országos közútként a 74 195-ös útszámozást viselte. 2024 decemberi állapot szerint azonban már önkormányzati útnak minősül.'),
    ('Hegykő', 'A Fertő hatalmas nádasokkal övezett déli partja felett emelkedő, kavicstakaróval borított dombvonulat oldalán és tetején helyezkedik el, a Hidegség és Fertőszéplak közötti lapályon. Három határátkelőhelyhez is közel van Ausztria felé. Soprontól 20, Fertődtől 5 kilométerre épült ki.'),
    ('Hegymagas', 'A Balaton-felvidék nyugati felében, a Tapolcai-medence területén található, a Szent György-hegy délnyugati lábánál, a Balaton-felvidéki Nemzeti Park területén. A Balatontól körülbelül 5 kilométerre fekszik. Határában folyik el a Nyirádnál induló és a Balatonba Szigligetnél beletorkolló Kétöles-patak. A település területén áthalad az Országos Kéktúra 5. számú szakasza is.'),
    ('Hegymeg', 'Edelénytől 11 kilométerre keletre, a megyeszékhely Miskolctól 32 kilométerre északra fekszik. A környező települések: észak felől Lak (2 kilométer), kelet felől Tomor (4 kilométer), dél felől Hangács, délnyugat felől pedig Damak (4 kilométer). A legközelebbi város Edelény. Csak közúton közelíthető meg, Damak vagy Lak érintésével, a 2616-os úton helyezkedik el.'),
    ('Hegyszentmárton', 'Három különálló településrésze Hegyszentmárton, az attól északnyugatra fekvő Alsóegerszeg és az északkeletre fekvő Monyorósd. Jellegzetessége a mindhárom településrész központjában megtalálható, kőből épült harangtorony. A település Pécstől, Siklóstól és Sellyétől is közel azonos távolságra helyezkedik el. A szomszédos települések: észak felől Tengeri, kelet felől Siklósbodony, délről Kórós, nyugat felől pedig Bogádmindszent.'),
    ('Hejce', 'Miskolctól 60 kilométerre északkeletre található, a Zempléni-hegység nyugati lábainál. Közigazgatási határa a környező településekhez viszonyítva meglehetősen kicsi, így csak három települési szomszédja van: kelet és dél felől Fonnyal, nyugat felől Vilmánnyal, északnyugat felől pedig Göncruszkával határos. Közúton mért távolsága Vilmánytól 4, Göncruszkától 7 kilométer.'),
    ('Hejőbába', 'Miskolctól közúton 23 kilométerre délre fekszik. A környező települések közül Nemesbikk 3, Szakáld 4, Sajószöged 5, Hejőpapi pedig 7 kilométerre található, a legközelebbi város a 11 kilométerre fekvő Tiszaújváros. Először 1234-ben említik, Baba néven, mely egyes feltevések szerint az ószláv baba, azaz vénasszony szóból származik (vö. „bába”.) Kevésbé elfogadott hipotézis az, hogy a magyar "bába" főnévből keletkezett a település neve.'),
    ('Hejőkeresztúr', 'Miskolctól körülbelül 20 kilométerre délre fekszik. A környező települések közül Hejőszalonta 3, Muhi 7 kilométerre található, a legközelebbi város a körülbelül 5 kilométerre fekvő Nyékládháza. Lakott területét kettészeli a Hejő folyása. Közúton Nyékládháza és Mezőcsát felől a 3307-es, Muhi felől a 3308-as úton érhető el. A terület már a honfoglalás korában is lakott volt, de először csak 1333-ban említik egy pápai jegyzékben, Keresztúr néven.'),
    ('Hejőkürt', 'Mezőcsát és Tiszaújváros között nagyjából félúton fekszik, előbbi településhez kicsit közelebb, a Tisza jobb partján, bár a folyótól mintegy 5-6 kilométer távolságra. Másik jelentős folyóvize a nevében is megjelenő Hejő, de az is mintegy 1 kilométerre folyik el a község lakott területeitől. Közigazgatási területe északon Tiszaújvárossal, északkeleten Oszlárral, keleten Polgárral, délen Tiszatarjánnal, nyugaton pedig Nemesbikk-kel határos.'),
    ('Hejőpapi', 'Miskolctól 21 kilométerre délre található. A környező települések: Hejőbába (7 kilométerre keletre), Hejőszalonta (5 kilométerre északra), Igrici (6 kilométerre délre), a legközelebbi város Nyékládháza 14 kilométerre északra helyezkedik el. Közvetlenül határos még északkelet felől Szakálddal, délkelet felől Nemesbikkel, nyugat felől pedig Emőddel is.'),
    ('Hejőszalonta', 'Miskolctól 16 kilométerre délre található. A környező települések közül Hejőkeresztúr és Szakáld 3-3, Hejőpapi 5 kilométerre fekszik, a legközelebbi város a 9 kilométerre fekvő Nyékládháza. Neve puszta személynévből keletkezett magyar névadással. A Zolunta személynév szláv eredetű, előzménye talán a lengyel Suleta (Sulimir - Sulislav) lehetett. Hejőszalonta, Szalonta Árpád-kori település.'),
    ('Helesfa', 'Pécstől mintegy 20 kilométerre nyugatra fekszik, a Bükkösdi-víz völgyében. Szomszédai: észak felől Bükkösd, kelet felől Cserdi, dél felől Csonkamindszent, nyugat felől pedig Dinnyeberki. Nagyon kevés híja van annak, hogy a közigazgatási területe nem határos északon még Ibafa, délnyugat felől pedig Kacsóta területével is. A pápai tizedlajstromban Eleusfolua, Heleusfolua.'),
    ('Helvécia', 'A negyedik Helvécia, a Központi Statisztikai Hivatal szerint. Mögötte olyan nagy városok sorakoznak, mint Szeged vagy Békéscsaba. Budapest és Szeged közt hozzávetőlegesen félúton található, mindkettőtől egyaránt nagyjából 80-80 kilométerre, az M5-ös autópályától 3 (a legközelebbi sztrádacsomóponttól 5) kilométerre. A település Wéber Ede svájci tanárnak köszönhetően jött létre, és az ő végakaratából kapta a Helvécia nevet (Helvetia Svájc latin neve).'),
    ('Hencida', 'Berettyóújfalutól északkeletre helyezkedik el, nem messze a román határtól. A közvetlen szomszédos települések: észak felől Konyár, északkelet felől Esztár, kelet felől Kismarja, dél felől Bojt, nyugat felől pedig Gáborján helyezkedik el. Csak kevés híja van annak, hogy nem határos délkelet felől még Nagykerekivel, délnyugat felől pedig Váncsoddal is.'),
    ('Hencse', 'Kaposvártól délnyugatra, Kadarkút, Hedrehely és Lad közt fekvő település. Hencse nevét a 15. századtól kezdve említik az oklevelekben. 1443-1449 között Hedrehely mezővároshoz tartozott és annak sorsában osztozott, 1443 és 1449-ben vámhely is volt.'),
    ('Herceghalom', 'Belterületének kiterjedéséhez képest a teljes települési területe aránylag kicsi, bár még így is öt települési szomszédja van: észak felől Zsámbék, kelet felől Páty, délkelet felől Biatorbágy, dél felől Etyek, délnyugat felől pedig Mány. A településnek 2800 lakosa van, a község 350 házában 430 lakás található. Mintegy 6 kilométer hosszúságú úthálózata ma már szinte teljesen pormentes.'),
    ('Hercegkút', 'Mindössze három települési szomszédja van: észak felől Makkoshotyka (6 kilométer), délkelet felől Sárospatak, északnyugat felől pedig Komlóska. Keletről, délről és nyugatról egyaránt Sárospatakhoz tartozó külterületek határolják. A község területe a 18. század elejéig a Rákócziak uradalmához tartozott. A település 1750-ben jött létre, mikor a Rákóczi-szabadságharc után elnéptelenedett területre akkori földesura, Trautson herceg német telepeseket hozatott, hasonlóképpen a közeli Károlyfalva (Karlsdorf) és Rátka (Ratkau) falvakkal együtt.'),
    ('Hercegszántó', 'Közúti határátkelőhely Szerbiába. A Bácskai-síkvidék déli szélén helyezkedik el, közvetlenül a szerb határ mellett, a Duna bal parti oldalán, a folyótól 12 kilométerre keletre, Bajától 29 kilométerre délre. A határ magyar oldalán csak három települési szomszédja van: észak felől Dávod, északkelet felől Bácsszentgyörgy, nyugat felől pedig Homorúd. Neve először okiratban Szent István uralkodása alatt említtetik, Zanthow alakban, majd jóval később, 1419-ben Hercegszántó formában helyezkedik el.'),
    ('Herencsény', 'A Cserhát vidékén belül a Terényi-dombságban fekszik, a Fekete-víz völgyében. A Novohrad-Nógrád UNESCO Globális Geopark települése. A közvetlenül határos települések: észak felől Varsány, északkelet felől Nógrádsipek, kelet felől Cserhátszentiván, délkelet felől Kutasó, Bokor és Buják, délnyugat felől Terény, nyugat felől pedig Cserhátsurány. Csak közúton érhető el, keleti és nyugati szomszédai felől egyaránt a 2123-as úton.'),
    ('Herend', 'Nevét világszerte ismerik porcelángyárának köszönhetően helyezkedik el. Átfolyik rajta a Séd patak. A falu határában késő római kori leleteket találtak, míg a község mai területén a középkorban több kisebb falu is állt. A vidék, a környék mindig vadászterület volt, annak megfelelő lakosokkal. Mivel Veszprém 1552 és 1566…'),
    ('Heresznye', 'Nevét már 1219-ben említették az oklevelekben-ben Haraznia iuxta Dravam alakban helyezkedik el. Később, 1332-1337 között a pápai tizedjegyzékben is megtaláljuk, tehát már ekkor egyházas hely is volt, majd 1384-ben pedig már két Heresznye helységről emlékeznek meg az oklevelek. 1399-ben az egyik, Egyházasheresnye, a székesfehérvári káptalané, a másik, Felrétheresnye, az Alsólendvai Bánfiaké volt, majd később a Marczaliak birtokába került, 1495-ben pedig a Báthoriak nyerték adományul.'),
    ('Hermánszeg', 'Hermánszeg a Szatmári-síkságon fekvő középkori eredetű, Szamos-háti település. Szamossályi keleti oldalán, a szabályozás előtti Szamos egyik nagy kanyarulatánál, a Holt-Szamos jobb partján, Mátészalkától 23 kilométer-re K-DK-re fekszik. Vasúton Nyíregyházától Fehérgyarmatig, onnan naponta rendszeres autóbuszjárattal közelíthető meg. A táj szépségét az ártéri növénytársulások, ligeterdők, régi folyómeder-maradványok gazdag vízivilág változatossága jellemzi, amely helyenként érintetlenül pompázik.'),
    ('Hernyék', 'A Zalai-dombság területén fekszik, a Göcsej tájegység déli részén. A közvetlenül határos települések: északkelet felől Nova, kelet felől Zebecke, délkelet felől Kissziget, dél felől Csömödér, délnyugat felől Iklódbördőce. A legközelebbi város Lenti, 9 kilométerre nyugat-délnyugati irányban helyezkedik el. Központja azonban csak arról letérve, a bő egy kilométer hosszú, 75 142-es számú bekötőúton érhető el.'),
    ('Hernád', 'Tőle 13 kilométer-re keletre található Magyarország mértani középpontja Pusztavacs település mellett. Hernádot először egy birtokpert lezáró oklevél említi 1388-ban helyezkedik el. Ekkoriban a falu népes köznemesi település lehetett. A török korszakban Hernád teljesen elnéptelenedett. Területét Nagykőrös szerezte meg és legelőként hasznosította. A 19. században Hernád környékén garázdálkodott Bogár Szabó Imre, a híres betyár.'),
    ('Hernádbűd', 'Miskolctól körülbelül 40 kilométerre északkeletre fekszik. A környező települések közül Pere 2, Abaújkér és Hernádszentandrás 5-5 kilométerre található. A legközelebbi városok Encs és Abaújszántó, mindkettőtől egyaránt körülbelül 8-8 kilométer választja el. Közösségi közlekedéssel a Volánbusz 3816-os járatával közelíthető meg. A terület az őskor óta lakott, késő kőkori földvár maradványaira bukkantak a környéken.'),
    ('Hernádcéce', 'A megyeszékhely Miskolctól 60 kilométerre, Encstől 15 kilométerre északkeletre helyezkedik el, a Hernád partján. A környező települések közül Vizsoly 4, Boldogkőváralja és Korlát 5-5 kilométerre fekszik. A két legközelebbi város a bő 11 kilométerre fekvő Abaújszántó és a 15 kilométerre lévő Encs. A közvetlen szomszédos települések: észak felől Vizsoly, kelet felől Arka, délkelet felől Boldogkőváralja, dél felől Abaújkér, nyugat felől pedig Méra helyezkedik el.'),
    ('Hernádkak', 'A környező települések közül Gesztely 1, Hernádnémeti 4, Bőcs 8 kilométerre található, a legközelebbi város a 12 kilométerre fekvő Felsőzsolca. A környék már a honfoglalás előtt is lakott volt, a magyarok pedig már a honfoglaláskor megtelepedtek itt. A zárda romjai ma is láthatóak.'),
    ('Hernádkércs', 'A Hernád folyó mellett fekszik, Miskolctól 30 kilométerre északkeletre. Lakott területe és közigazgatási területének túlnyomó része a folyó bal parti oldalán helyezkedik el, de hozzá tartozik néhány kisebb terület a jobb parti oldalról is. A szomszédos települések: észak felől Csobád (légvonalban 5, közúton 11 kilométerre), északkelet felől Felsődobsza (4 kilométerre), délkelet felől Monok (légvonalban 8, közúton több mint 20 kilométerre), délnyugat felől Nagykinizs (2 kilométerre), északnyugat felől pedig Kiskinizs (2 kilométerre).'),
    ('Hernádnémeti', 'Miskolctól 14 kilométerrel délkeletre esik. Az Északi-középhegységben helyezkedik el, a megyeszékhely Miskolctól alig 14 kilométerre kelet-délkeletre, a Hernád mellett. Belterülete és közigazgatási területének túlnyomó része a folyó bal parti oldalán helyezkedik el, de mintegy 2,5 négyzetkilométernyi terület hozzá tartozik a jobb parti oldalról is.'),
    ('Hernádpetri', 'A Cserehát északkeleti peremén, a szlovák határ mellett, Miskolctól 55 kilométerre helyezkedik el. A település a középkor nagy részében párhuzamosan két nevet viselt. Eredeti, korai neve Garadna volt, mivel a Garadna patak – a későbbi térképeken Petri-patak – mellett feküdt. Idővel a név Felgaradnára változott, hogy megkülönböztessék a pataknak Bársonyosba való torkolatánál fekvő, alsóbb Garadnától.'),
    ('Hernádszentandrás', 'A Hernád völgyében fekszik, a Cserehát és a Zempléni-hegység között, a megyeszékhely Miskolctól 35 kilométerre északkeletre. Teljes lakott területe és közigazgatási területének túlnyomó része is a folyó jobb partján található, de egy kisebb, hozzávetőleg egy négyzetkilométernyi területrésze a túlparti oldalon helyezkedik el. A közvetlenül határos települések: észak felől Forró, kelet felől Pere, dél felől Felsődobsza, nyugat felől pedig Ináncs.'),
    ('Hernádszurdok', 'Miskolctól 57 kilométerre északkeletre található. A Hernád folyó jobb partján, a Cserehát peremén fekszik. Vonattal ugyancsak elérhető a község, a Felsőzsolca–Hidasnémeti-vasútvonalon helyezkedik el. A környező fontosabb települések: Hidasnémeti 2, Tornyosnémeti pedig 6 kilométerre északi, Garadna 8 kilométerre déli irányban helyezkedik el. A legközelebbi város Gönc, 6 kilométerre keletre helyezkedik el.'),
    ('Hernádvécse', 'Dimbes-dombos tájakon, erdők és gyümölcsöskertek között fekszik, a Garadna és a Mogyorós-patak völgyében, Miskolctól 50 kilométer-re északkeletre, Kassától 30 kilométer-re délre. Közigazgatási területe 1694 hektár, lakásainak száma 295. A közvetlenül szomszédos települések a határ magyar oldalán: észak felől Hernádpetri (6 kilométer), északkelet felől Hernádszurdok (8 kilométer), kelet felől Göncruszka, délkelet felől Vilmány, dél felől Garadna (3 kilométer), nyugat felől Fulókércs, északnyugat felől pedig Pusztaradvány (6 kilométer).'),
    ('Heréd', 'Éghajlata mérsékelten meleg, mérsékelten száraz. A csapadék évi összege 530–610 mm, az évi középhőmérséklete 9,5-10 °C, az évi napsütéses órák száma 1920 körül alakul. Leggyakrabban északnyugati szél fúj. Az enyhén délkeletnek lejtő dombság legnagyobb tengerszint feletti magassága 157,8 méter (Kerek-halom). Enyhén szeizmikus terület, természetes vizekben szegény.'),
    ('Hetefejércse', 'Két, korábban önálló település, Hete és Fejércse egyesüléséből jött létre 1977-ben. A két különálló településrész közül Hete a nagyobbik, Fejércse jóval kisebb és az előbbitől bő egy kilométerre északra fekszik. A szomszédos települések: észak felől Csaroda, északkelet felől Márokpapi, délkelet felől Tarpa, dél felől Gulács, délnyugat felől pedig Jánd.'),
    ('Hetes', 'Ily módon, az említett utak révén Kaposvár, Marcali és Somogysárd felé is vannak közúti összeköttetései. 1997-ben kezdték el a Hetest Kaposmérővel összekötő 3,6 kilométeres önkormányzati út építését, a beruházás 70 millió forintba került. A megyeszékhely autóbusszal könnyen elérhető, óránként közlekednek a járatok. Hetes elnevezése a hét számnévből, illetve az azt felvevő ''hetes szolgáltató'' nevéből ered.'),
    ('Hetvehely', 'A Mecsek nyugati felében helyezkedik el, a Pécs-Dombóvár-Szentlőrinc háromszög középpontjától nem messze, de a három közül utóbbi városhoz a legközelebb. Szomszédai: észak felől Szentkatalin, északkelet felől Okorvölgy, kelet felől Abaliget, délkelet felől Kővágótöttös ás Bakonya, délnyugat felől Bükkösd, nyugat felől pedig Ibafa. Határszéle érintkezik még délen Boda, északnyugaton pedig Tormás, Bakóca és Kisbeszterce határával is.'),
    ('Hetyefő', 'A Kemenesalján, a Marcal mellett fekszik, két szomszédja dél felől Dabronc, északnyugat felől pedig Zalaerdőd,Szalapától északra található. Közúton csak e két település irányából érhető el, a 7331-es és 7337-es utakat összekötő 73 168-as számú úton. Hetyefő Árpád-kori település. Nevét az oklevelek 1241-ben említették először Terra Heghe formában helyezkedik el.'),
    ('Heves', 'Heves vasútállomása a Kál-Kápolna-Kisújszállás mellékvasútvonalon található, ahol a vonal két végállomásáig közlekedő vonatok járnak. Északnyugati irányban Gyöngyös, délkelet felé pedig Kisköre irányában indulnak innen mellékutak (3204-es és 3209-es számmal), továbbá Pély és Kál felé (utóbbi száma 3207-es). Helyközi járatok kötik össze Egerrel, Gyöngyössel, Jászberénnyel és Kiskörével.'),
    ('Hevesaranyos', 'Településszerkezete U alakú, az U két szárát képező falurészek a Laskó-patakba torkolló Aranyos-patak két ága mentén jöttek létre helyezkedik el. Belterülete 153, külterülete 1549 hektár, lakossága alig több mint 600 fő. Egyik legnagyobb előnye a természeti szépsége. Területe a Tarnavidéki Tájvédelmi Körzet része. A településen nincs jelentősebb szennyezésű ipari tevékenység, a közúti forgalom is csekély.'),
    ('Hevesvezekény', 'A középkori eredetű település a Hanyi-ér vízgyűjtő területén fekszik, Heves várostól mintegy 7 kilométerre délkeletre. A további szomszédos települések: észak felől Átány, északkelet felől Kömlő, délkelet felől Tarnaszentmiklós, dél felől pedig Pély. Keleti irányból a legközelebbi település Tiszanána, nyugat felől pedig Jászivány, de közigazgatásilag ezek egyikével sem határos.'),
    ('Hidas', 'A település nevét a település melletti Völgységi-patakon átívelő hídjáról kapta. Hidas és környéke már a csiszolt kőkorszakban lakott volt. Később kelták, majd rómaiak éltek itt. A honfoglalás után pedig Ete telepedett le itt.'),
    ('Hidasnémeti', 'A Hernád völgyében fekszik, a folyó jobb parti oldalán, a szlovák határ közvetlen közelében, a megyeszékhely Miskolctól körülbelül 60 kilométerre északkeletre. A közvetlenül határos települések: észak felől Tornyosnémeti (3 kilométerre), délkelet felől Gönc (5 kilométerre), délnyugat felől Hernádszurdok (2 kilométerre), nyugat felől pedig Hernádpetri (légvonalban 5, közúton több mint 15 kilométerre).'),
    ('Hidegkút', 'Hidegkút a Balaton-felvidéken, a Déli-Bakonyban fekszik, Veszprémtől 15 kilométerre, Balatonfüredtől légvonalban csak 6, közúton viszont mintegy 13 kilométerre. A csodálatos völgyben fekvő kis falut erdők, és hegyek veszik körbe, mint például a Recsek-hegy – mely szívesen látogatott hely a turisták számára is, hisz itt található a Noszlopy Gáspár-kilátó – de a völgy magasabban fekvő pontjairól Tihanyt és a Balaton déli partját is megcsodálhatjuk.'),
    ('Hidegség', 'Természetföldrajzi szempontból a Nyugat-Magyarországi peremvidék részeként nyilvántartott Ikva-medencéhez tartozik a falu. A település határától északra elterülő Fertő-tó közelsége a történelem folyamán mindvégig meghatározta a község lakóinak életét: a növénytermesztés bizonyos ágainak fejlődését lehetetlenné tette, ugyanakkor például a zöldségtermesztés számára kedvező feltételeket biztosított a vízparti környezet.'),
    ('Hidvégardó', 'A környező falvak közül Becskeháza 5, Tornaszentjakab 6, Tornanádaska 7 kilométerre fekszik, a legközelebbi város a határ magyar oldalán a mintegy 30 kilométerre fekvő Szendrő. Az államhatár szlovák oldalán a legközelebbi falu Bódvavendégi (Host’ovce), a legközelebbi város pedig a mintegy 20 kilométerre található Szepsi (Moldava nad Bodvou). Autóbusszal a község a Volánbusz által üzemeltetett 3707-es és 4136-os busszal közelíthető meg.'),
    ('Himesháza', 'A szomszédos települések: észak felől Szűr, kelet felől Görcsönydoboka, délkelet felől Székelyszabar, dél felől Kisnyárád, délnyugat felől Erdősmárok, nyugat felől pedig Geresdlak. Szűrtől alig 2,5 kilométer, Székelyszabartól 5 kilométer, Erdősmároktól bő 7 kilométer, Geresdlaktól pedig kb. 4 kilométer választja el, Görcsönydobokával nincs közvetlen közúti összeköttetése.'),
    ('Himod', 'A Rábaköz déli részén, a Répce-síkság határán, sík területen fekszik, Kapuvártól 12 kilométerre délre. Területe nagyrészt a Rába észak felé lejtő, megsüllyedt, jelenkori folyóvízi üledékkel borított hordalékkúp-lejtője. A faluról 1408-ból származik az első írásos emlék: nevét „Hymod" alakban említették.'),
    ('Hirics', 'Az Ormánság középső-déli részén helyezkedik el, Vajszlótól dél-délkeleti irányban. Déli határszéle közel 4 kilométer hosszan egybeesik a déli országhatárral. A további szomszéd települések határ magyar oldalán: északkelet felől Baranyahídvég, kelet felől Kisszentmárton, nyugat felől Vejti, északnyugat felől pedig Lúzsok. Dél felől a legközelebbi település a horvátországi Monoszló (Podravska Moslavina).'),
    ('Hobol', 'A település horvát neve a szigetváriak által használt Obol, de a szentborbásiak Oboljnak, felsőszentmártoniak Obojnak, a révfalusiak Vobolnak nevezték a falut. A megyeszékhely, Pécs felől Szigetváron át közelíthető meg a legegyszerűbben helyezkedik el. Hobol és környéke már az újkőkorszakban lakott hely volt. A lengyeli kultúra népe élt itt.'),
    ('Hodász', 'A környező települések közül Kántorjánosi 5, Nyírmeggyes 8, Őr 10 kilométer távolságra található. A legközelebbi város a 13 kilométerre fekvő Mátészalka, de Nyírbátortól is közel azonos távolság választja el. A szomszédos települések: észak felől Őr, északkelet felől Jármi, kelet felől Nyírmeggyes, dél felől Nyírkáta, nyugat felől Nyírderzs, északnyugat felől pedig Kántorjánosi.'),
    ('Hollád', 'Balatonberénytől délre, Tikos és Marcali közt fekvő település. Szőlő- és borgazdasági szempontból a Balatonboglári borvidék részét képezi. Az 1715 évi összeírás feljegyzése szerint 1715 előtt három évvel települt…'),
    ('Hollóháza', 'Az Eperjes–Tokaji-hegység (ezen belül a Zempléni-hegység) egyik völgyében terül el. A megyeszékhelytől, Miskolctól közúton 81 kilométerre északkeletre, Sátoraljaújhelytől 28 kilométerre északnyugatra, a magyar-szlovák határtól 3,5 kilométerre délre fekszik. Közigazgatási határszélét szinte minden irányból Füzérhez tartozó külterületek veszik körül, csak azért nem tekinthető Füzér enklávéjának, mert egy-egy rövidke szakaszon határos Füzérkomlóssal és a már Szlovákiához tartozó Eszkárossal (Skároš) is.'),
    ('Hollókő', 'Magyarország egyetlen olyan faluja, amely szerepel az UNESCO világörökség listáján, és így világszerte ismert. A legfontosabb feltételnek, azaz az egyedi és egyetemes jelentőségnek Hollókő azzal tesz eleget, hogy a 17–18. században kialakított falu a népi építészet és a 20. századot megelőző falusi élet olyan páratlan példája, amelyet sikerült eredeti állapotában megőrizni.'),
    ('Homokbödöge', 'A település a Bakonyalján fekszik, Pápától 15 kilométer-re. A környék kiváló túrázási lehetőségeket nyújt (Homokbödöge – Nagytevel – Király-kapu – Bakonybél). A község csak közúton közelíthető meg, a Pápa-Béb között húzódó 8303-as úton. Bödöge a szláv Budigaj személynévből származik. Feltételezések szerint a honfoglalók szláv népeket találtak a környéken, akik később beolvadtak a magyarságba.'),
    ('Homokkomárom', 'A Zalai-dombságban fekszik, az Egerszeg–Letenyei-dombság területén, a Principális-völgy peremén. Viszonylag kiterjedt külterületekkel rendelkezik, ezek révén több környékbeli községgel is határos. A közvetlenül szomszédos települések: északon Magyarszerdahely, Magyarszentmiklós és Fűzvölgy, északkeleten Hosszúvölgy és Korpavár, keleten Palin (utóbbi kettő Nagykanizsa része), délkeleten Nagykanizsa, délen Sormás, nyugaton pedig Obornak (Eszteregnye része).'),
    ('Homokmégy', 'A földrajzi nevek etimológiája szerint a név utótagja, a mégy a Kecskemét helynévhez hasonlóan száraz meder, időnként kiszáradó ér jelentésű lehetett. (Hasonlóképpen a Nemesmedves névhez is.) Homokmégy az Alföldön fekszik. Területe tehát jobbára síkság. Kalocsa vonzáskörzetében helyezkedik el, a város központjától mintegy 8 kilométerre kelet-délkeleti irányban.'),
    ('Homokszentgyörgy', 'A megye déli részén fekszik, a Lad-Barcs közti 6623-as út mentén, Barcstól bő húsz kilométerre északra, Lad és Szulok között. Nevét 1425-ben említették először írásos formában helyezkedik el. Az 1536. évi adólajstrom pedig Kálmáncseh és Öszpöte között sorolta fel. 1583-ban Ungnád Kristóf, 1598-1599 között Nádasdy Ferenc birtokaként volt említve. Az 1565-66. évi török kincstári fejadólajstromban Musa-Szent-György néven található, mely 30 házból állt.'),
    ('Homorúd', 'A Mohácsi-szigeten fekszik, annak névadó városa, Mohács délkeleti szomszédságában. A Duna–Dráva Nemzeti Park egyik fontos tájegysége. A település központját szinte minden irányból Mohácshoz tartozó határrészek veszik körül, de délkeleti külterületei révén határos kelet felől Dávoddal, délkelet felől Hercegszántóval, délnyugat felől Kölkeddel, sőt déli határszéle egy rövidke szakaszon még az államhatárral is egybeesik.'),
    ('Homrogd', 'A Cserehát középső-déli részén helyezkedik el, Szikszótól északra, a megyeszékhely Miskolctól kb. 25 kilométerre északkeletre. A közvetlenül határos települések: észak felől Monaj, északkelet felől Léh, kelet felől Kázsmárk, dél felől Alsóvadász, nyugat felől pedig Hangács. Keleti és nyugati szomszédaival nincs kiépített közúti kapcsolata.'),
    ('Hont', 'Közvetlenül a szlovák határ mellett fekszik. A közvetlenül szomszédos települések: észak felől, az Ipolyon túl, Szlovákia területén Tesmag, kelet felől Drégelypalánk, nyugat felől pedig Bernecebaráti (dél felől a két utóbbi településhez tartozó, börzsönyi erdőségek határolják). A település határában található a Duna–Ipoly Nemzeti…'),
    ('Horpács', 'Tagja a Sugárkankalin Turisztikai Egyesületnek, melynek célja a térség turizmusának fejlesztése, és természeti értékeinek bemutatása. A község a Palóc út egyik állomása is. Lankás dombokkal közrefogott völgyben helyezkedik el, Balassagyarmattól mintegy 15 kilométerre délnyugatra. A település neve elhelyezkedésére utalva horpadást jelent. 1473-ban a Szobi család birtokos a faluban, de 1480-ban birtokukat elcserélték az Almássyakkal.'),
    ('Hort', 'A terület átmenet a síkság és a dombvidék között. A szomszédos települések: észak felől Ecséd, északkelet felől Nagyréde, kelet felől Atkár, délkelet felől Csány, délnyugat felől pedig Hatvan helyezkedik el.'),
    ('Hortobágy', 'A Hortobágy Magyarország egyik kistája, a Közép-Tisza-vidék része. A gyéren lakott vidék nagy része nemzeti park. A hortobágyi puszta és a hozzá társított alföldi pásztor- és betyárromantika az ország egyik idegenforgalmi vonzereje. A kistáj a Hajdúság és a Tisza folyó között terül el. A Tisza és mellékfolyóinak munkája feltűnően kiegyenlített, tökéletes sík felszínt eredményezett, aminek tengerszint feletti magassága 87–110 méter (átlag 92 méter).'),
    ('Horváthertelend', 'A Zselic tájegységben fekszik, zsáktelepülés, közúton csak Szentlászló és Almamellék érintésével érhető el. A falu horvát neve a szigetváriak által használt Ertelen, de régen használták a szigetváriak a Retlenda, és a nagyhajmásiak a Hertalan alakot is. A település egyik első ismert okleveles említésénél – egy 1332-ben készült oklevélben – Horcholond alakban olvasható a község neve.'),
    ('Horvátlövő', 'Szombathelytől mintegy 15 kilométerre délnyugatra fekszik, a Pinka bal partján, közvetlenül az osztrák határ mellett. A szomszédos települések: észak felől Vaskeresztes, kelet felől Nárai, dél felől pedig Pornóapáti. Nyugat felől a már Ausztriához tartozó Németlövő (Deutsch-Schützen) határolja. Neve arra utal, hogy egykor határőrző íjászok faluja volt, nevének előtagját horvát lakosságáról kapta.'),
    ('Horvátzsidány', 'Szombathelytől 30 kilométerre északra, Kőszegtől 7 kilométerre északkeletre fekszik, az osztrák határ közvetlen közelében, attól alig több mint 2 kilométerre. A szomszédos települések: északkelet felől Peresznye, kelet felől Kiszsidány, délnyugat felől Kőszeg, nyugat felől pedig Ólmod. Közigazgatási területe délen, pontszerűen érinti még Kőszegpaty területét is, az államhatárral viszont nem érintkezik, a legközelebbi pontja, északnyugati határszéle attól légvonalban szűk fél kilométerre van.'),
    ('Hosszúhetény', 'A falusi turizmus jelentős központja a Mecsek hegységben, a Zengő lábánál. Hosszúhetény festői fekvésű falu a Kelet-Mecsek déli szegélyén, a Mecsek legmagasabb csúcsa, a 682 méter magas Zengő délkeleti lankái és a Hármashegy lába közti völgyekben és dombokon, a 6-os főúttól néhány kilométerre helyezkedik el. Pécstől 16 kilométerre kelet-északkeletre, Pécsváradtól nyugatra, Komlótól délkeletre helyezkedik el.'),
    ('Hosszúpereszteg', 'Belterületén ágazik ki a 8-as főútból dél felé a Mikosszéplakig vezető 7365-ös út, illetve utóbbiba szintén a településen torkollik bele a Bögötéről, a 7355-ös út ottani szakaszából kiinduló, rövid 7366-os út.'),
    ('Hosszúpályi', 'A közvetlen szomszéd települések: észak felől Debrecen, kelet felől Monostorpályi, délkelet felől Pocsaj, dél felől Esztár, délnyugat felől Konyár, nyugat felől pedig Hajdúbagos. Északnyugat felől a legközelebbi település Mikepércs, de közigazgatási területeik nem határosak. Előbbin azonban 2009. december 12-én megszűnt a forgalom. Hosszúpályi megállóhely egyébként a település központi részének északi…'),
    ('Hosszúvíz', 'Marcali dél-délkeleti szomszédságában helyezkedik el, a város központjától légvonalban 7,5, közúton körülbelül 11 kilométerre. Mindössze két további településsel határos közvetlenül: keleti szomszédja Libickozma, a nyugati pedig Mesztegnyő. Dél felől ez utóbbihoz tartozó, jobbára lakatlan külterületek határolják. Északnyugat felől még közel fekszik hozzá Kelevíz is, de a közigazgatási területeik nem érintkeznek.'),
    ('Hottó', 'A településen polgárőrség működik. Zalaegerszegtől közúton 8 kilométerre nyugatra, a Göcseji dombság egy viszonylag magas északi pontján fekszik. Közvetlen szomszédos települések keletre Teskánd, nyugatra pedig Böde. Lakott területe közúton két irányból közelíthető meg, de mindkettőhöz a 7405-ös útról kell letérni Teskánd közigazgatási területén. Neve valószínűleg kiszáradt, víztelen, vagyis holt tóra vezethető vissza (Holtou tó).'),
    ('Hugyag', 'Balassagyarmattól keletre, Őrhalom és Szécsény közt fekvő település. Az itteni megállóhely Őrhalom és Szécsény között található. Hugyag nevét az 1332. évi pápai tizedjegyzék említette először, tehát ekkor már egyházas hely volt. A Szécsényi család tagjainak 1333 évi birtokmegosztásakor Szécsényi Tamás erdélyi vajda és testvére Péter, birtokában volt.'),
    ('Hunya', 'Gyomaendrődtől délre, Örménykút és Mezőberény közt fekvő település. Szomszédai: észak felől Gyomaendrőd, kelet felől Mezőberény, délkelet felől Kamut, dél felől Kondoros, nyugat felől pedig Örménykút. Légvonalban közel van még hozzá északkeleti irányban Csárdaszállás is, de a két település közigazgatási területe nem érintkezik egymással. Hunya területén az első, emberi megtelepedésre utaló régészeti leletek a késő bronzkorból származnak.'),
    ('Hunyadfalva', 'Szolnoktól körülbelül 30 kilométerre, északkeletre fekszik. A település a Tisza-tó turisztikai régióhoz tartozik. Mindössze négy települési szomszédja van: északkelet felől Kőtelek, délkelet felől Nagykörű, dél felől Csataszög, nyugat felől pedig Besenyszög. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Nevét is róluk kapta. 1913-ban már Hunyadfalva néven említi a helynévtár.'),
    ('Husztót', 'Pécs felől Abaligeten át érhető el. Az eddig ismert források először 1542-ben említik a község nevét. A középkorban a györgényi kolostor, később a Pécsi Káptalan, majd a pécsi pálosok tulajdona volt a falu. A török hódoltság alatt valószínűleg lakott volt a falu, de a felszabadító háborúk során elnéptelenedett. A 18. század elején is lakatlan volt, csak 1729-ben kezdték benépesíteni a környék magyar falvaiban élők.'),
    ('Hács', 'A Dunántúl észak-somogyi részét a Kapos-völgye és a Balaton között már régóta Külső-Somogy néven ismerik. Domborzatára jellemző, hogy a nyugati részén a párhuzamos hosszanti völgyek közé fogott Gamási-hát megszakítás nélkül halad a Balatontól a Kapos völgyéig. A Gamási-hát a Külső-Somogyi dombság leghosszabb és legszélesebb része. Szélessége 5-10, hosszúsága 30–35 kilométer.'),
    ('Háromfa', 'Délen Babócsával és Bolhóval, északon Tarannyal, keleten Bakházával, délkeleten Rinyaújnéppel határos. Közigazgatási területe északon egy-egy rövid szakaszon érintkezik Rinyaszentkirályhoz és Nagyatádhoz tartozó területekkel is. Háromfa első ismert okleveles említése 1377-ből való, amikor a nevét Harumfa formában jegyezték fel. Később Háromfafalvának nevezték, majd az idők folyamán ez rövidült Háromfára. (A legenda szerint három nagy nyárfa állt egy dombon, innen kapta a falu a nevét.'),
    ('Háromhuta', 'Három (négy), többé-kevésbé különálló településrészből áll, melyek közül Óhuta fekszik legnyugatabbra, a hegységet keresztirányban átszelő országút mentén, Középhuta és Újhuta pedig az úttól több kilométerrel keletebbre. Negyedik településrészének tekinthető az az újabb keletkezésű kis települési alközpont, amely a Közép- és Újhutára vezető elágazás mellett, valamelyest Óhutától is elkülönülten jött létre.'),
    ('Hárskút', 'A Bakony legmagasabban fekvő települése. Veszprémtől északnyugatra 18 kilométerre található az Északi-Bakony szívében. A pénzesgyőri és a lókúti út télen nem mindig járható. Budapest felől közúton az M7-es autópályán, majd Székesfehérvárnál a 8-as főútra letérve érhető el a leggyorsabban. Szombathely felől a 8-as főúton közelíthető meg. Mindkét esetben Márkónál kell északnak kanyarodni.'),
    ('Hásságy', 'Pécstől mintegy 17 kilométerre délkeletre fekszik. A szomszédos települések: észak felől Berkesd, kelet felől Máriakéménd, délkelet felől Olasz, dél felől Birján, nyugat felől Magyarsarlós, északnyugat felől pedig Ellend. Közúti kapcsolata csak Olasszal és Ellenddel van. Az Árpád-kori település, Hásságy neve az oklevelekben 1058-ban tűnt fel először Hashag néven helyezkedik el.'),
    ('Hédervár', 'A település a Szigetközben, Győr és Mosonmagyaróvár között nagyjából félúton fekszik. A szomszédos települések – mint az a Szigetközben gyakori – nagyon közel vannak egymáshoz: Ásványráró másfél, Darnózseli kettő, Lipót három, Kimle három és fél, a legtávolabbi szomszéd, Mecsér pedig közúton nyolc, földúton három kilométer távolságra helyezkedik el a községtől.'),
    ('Héhalom', 'Környező települések még: Szirák és Egyházasdengeleg északnyugatra, Palotás északkeletre, Erdőtarcsa délkeletre és Nagykökényes délnyugatra helyezkedik el. Héhalom nevét a 13–14. században említették először az oklevelekben Hywhalom alakban írva. Egy 1439-es oklevél szerint akkoriban, Báthory István birtokaként a bujáki vár tartozéka volt, később vámhelyként működött.…'),
    ('Héreg', 'Héreg a Gerecse hegység keleti lábánál, festői völgyben fekvő, mintegy 1015 lakosú település. Héreg területe, és környéke már a rómaiak idején is lakott hely volt. Az „újhegyi” szőlő dűlőjének tetején sokáig látható volt egy sánc, ahol többször találtak római kori (Nero római császár idejéből való) pénzérméket. A község határában a hagyományok szerint a domonkos-rendi barátoknak klastromuk is volt, de nyomai már nem láthatók.'),
    ('Hét', 'A Sajó bal oldalán, Ózdtól 15 kilométerre keletre, Miskolctól 45 kilométerre északnyugatra fekszik. Különálló településrésze Pogonypuszta, a központjától északra helyezkedik el. A környező települések: kelet felől Putnok (7 kilométer), dél felől (a Sajó túlpartján) Sajónémeti, nyugat felől Bánréve (4 kilométer), észak felől pedig Serényfalva (4 kilométer).'),
    ('Hévíz', '830 hektáros kiterjedésével a megye és a Dunántúl legkisebb közigazgatási területű városa. Fő nevezetessége az Európában egyedülálló természetes tőzegmedrű melegvizű tava, melynek köszönhetően a település Magyarország egyik első számú turisztikai célpontja.'),
    ('Hévízgyörk', 'A település az őskortól a középkoron át napjainkig lakott volt. Múltjának egyik meghatározó emléke középkori temploma, amelyet a helybeliek Öregtemplomként emlegetnek. Az 1988-ban helyreállított és azóta gondosan karbantartott épület méltán tart számot az idelátogatók érdeklődésére.'),
    ('Hódmezővásárhely', 'Hódmezővásárhely a Dél-Alföldön. A megye és a Dél-Alföld legnagyobb területű települése. Valamikor egyike volt az Alföld legfontosabb gazdasági és kulturális központjainak, a legsikeresebb egykori mezővárosok közé tartozott. A 20. század közepéig az ország legnépesebb városai közé tartozott: 1920-ban az ötödik, 1930-ban a tizedik helyen állt, 2010-ben már csak a huszonkettedik. 1950 és 1961 között Csongrád megye székhelye volt.'),
    ('Hövej', 'Magyarország északnyugati részén, Kapuvártól mintegy 8 kilométerre délre helyezkedik el, a Répcétől és a Rábától nyugatra, kisebb patakokkal szabdalt sík területen. A szomszédos települések: északkelet felől Kapuvár, dél felől Himod, délnyugat felől Csapod, északnyugat felől pedig Vitnyéd. Az M85-ös autóútról is könnyen elérhető, a 44. kilométere előtt található kapuvári csomópontnál lehajtva.'),
    ('Hőgyész', 'A Kapos jobb parti oldalán helyezkedik el, Siófoktól 60 kilométerre délkeletre, Szekszárdtól 32 kilométerre északnyugatra. Területe észak-déli irányban meglehetősen kiterjedt – legészakibb és legdélebbi pontjai között a távolság több mint 14 kilométer –, így viszonylag sok települési szomszédja van. A közvetlenül határos települések: észak felől Szárazd, északkelet felől Diósberény, kelet felől Kalaznó, délkelet felől Murga, dél felől Tevel, délnyugat felől Mucsi, nyugat felől Dúzs, északnyugat felől pedig Szakály és Regöly.'),
    ('I. kerület', 'Az I. kerület, vagy hivatalos nevén Budavár a magyar főváros, Budapest egyik történelmi kerülete, amely a Duna jobb partján, Budán fekszik. Északon a II. kerület, nyugaton a XII. kerület, délen a XI. kerület, míg keleten a Duna által az V. kerület határolja. A kerületnek jelenleg 5 városrésze van: a Budai Várnegyed, a Gellérthegy egy része, a Krisztinaváros egy része, a Tabán, és a Víziváros egy része.'),
    ('Ibafa', 'A Dunántúli-dombságban, a Zselic keleti dombjai közt, Szigetvártól északkeletre, Horváthertelendtől délre, Almáskeresztúrtól északkeletre, Almamelléktől keletre fekvő zsáktelepülés. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. A falu első okleveles említése 1425-ből származik. Eredetileg birtokosa után, mely feltehetően német személynévből alakulhatott ki, Ibafalvának nevezték.'),
    ('Iborfia', 'Iborfia a göcseji kultúrtáj aprófalvas, szeres településeinek egyik kevésbé jellegzetes, kevés lakosú példája. Területe igazi zalai dombvidék, amelynek felszíni vizeit több vízfolyás szállítja el. A település az érett középkor óta létezik, virágkorát a múlt század első felében élte, ám a huszadik század második felétől kezdve lélekszáma jelentősen megfogyatkozott az elvándorlás és az elöregedés együttes hatásainak következtében.'),
    ('Ibrány', 'Teljes lakott területe és közigazgatási területének döntő többsége a folyó bal parti oldalán helyezkedik el, de hozzá tartozik három kisebb – együttesen is csak kb. 2 négyzetkilométernyi – területrész a jobb partról is. A közvetlen szomszédos települések: észak felől a Tisza túlpartján fekvő Tiszakarád, északkelet felől Tiszatelek, kelet felől Nagyhalász, dél felől Kótaj, délnyugat felől Buj, nyugat felől pedig Paszab.'),
    ('Igar', 'A környező települések közül Simontornya 2, Mezőszilas és Tolnanémedi egyaránt 8,5-8,5, Cece 10, Ozora 11, Pincehely 12, Dég 14, Enying pedig 29 kilométer távolságra található. A település és környéke már a bronzkorban is lakott hely volt, amit a környékén (Galástya, Vámszőlőhegy) talált bronzkori leletek igazoltak. Az avar korból származó előkelő leletei (a közeli ozora-tótipusztai leletekkel együtt), és a falu határában található Árpád-korból származó földvár a terület jelentőségére mutatnak rá a kora középkortól kezdve.'),
    ('Iharos', 'Iharos a Kelet-Zalai-dombság és a Belső-Somogy homokvidéke határán terül el. A jelenlegi falu, mint azt a 2. katonai felmérés térképei is bizonyítják, a 19. század második felében alakult ki, Iharos község és Sukorot puszta egyesülésével. A közvetlenül határos települések: észak felől Iharosberény, kelet felől Kaszó, délkelet felől Somogycsicsó, dél felől Csurgónagymarton, délnyugat felől Porrog, nyugat felől pedig Liszó.'),
    ('Iharosberény', 'Felszíne változatos, ahol a dombvidéki és a síkvidéki jelleg egyszerre van jelen, éppen ezért túrázók számára ideális hely. A környék növényzetére a kocsánytalan tölgy, a bükkös és a cseres tölgyes jellemző, valamint értékesek szőlő- és gyümölcstermelő területei is. Ez a vidék a magyar szelídgesztenye őshazája, itt van az ország egyik legnagyobb ültetvénye.'),
    ('II. kerület', 'A II. kerület, vagy hivatalos nevén Rózsadomb a magyar főváros, Budapest egyik kerülete, mely a Duna jobb partján, Budán fekszik. Északon a III. kerület, északkeleten Solymár, nyugaton Nagykovácsi és Budakeszi, délen a XII. kerület és az I. kerület, míg keleten a Duna által az V. kerület és a Margit-sziget határolja. Jelentősebb terei többek között az Elvis Presley tér, a Széll Kálmán tér, a Széna tér, a Bem József tér és a Zsigmond tér.'),
    ('III. kerület', 'A III. kerület, vagy hivatalos nevén Óbuda–Békásmegyer a magyar főváros, Budapest egyik kerülete, amely a Duna jobb partján, Budán fekszik. Északon Budakalász és Üröm, nyugaton Solymár, délen a II. kerület, míg keleten a Duna által az XIII. kerület és a IV. kerület határolja. Jelentősebb terei többek között a Flórián tér, a Fő tér, a Kolosy tér és a Szentlélek tér.'),
    ('Ikervár', 'Szombathelytől 25 kilométerre keletre, Sárvártól 8 kilométerre délre, Sótonytól 5 kilométerre nyugatra, Rumtól 10 kilométerre északra fekszik, a Rába folyó bal partján. A Rába két partján emelt várakról kapta a nevét. Területén már a késő bronzkorban éltek emberek, ezt bizonyítja a Rába partjából itt előkerült edény, mely a sárvári múzeum tulajdona.'),
    ('Iklad', 'A településhez legközelebb lévő város Aszód 3, Gödöllő 14, Budapest 40, Hatvan 17, Vác 28 kilométerre fekszik. Iklad főutcája az Aszódtól Galgamácsán át Balassagyarmatig vezető 2108-as út, ezen érhető el mindhárom említett település irányából. A Galga-mente dús rétjei, vadban gazdag erdei már az ősidőktől fogva kedvező feltételeket nyújtottak az emberi letelepedéshez.'),
    ('Iklanberény', 'Csepregtől 9 kilométerre keletre fekszik, a Metőc-patak mellett. A szomszédos települések: észak felől Újkér, kelet felől Simaság, dél felől Lócs, nyugat felől pedig Tormásliget. Nevének első része a régi magyar Icol személynévből származik, melynek előzménye az ikol (= hőköl) ige. A név második része törzsnévi eredetű. Ez az ótörök berendi (megadta magát) névből származik.'),
    ('Iklódbördőce', 'A Mura vízrendszeréhez tartozó Kerka és más patakok alakították ki a Lenti-medencét, melynek északi peremén helyezkedik el. Termőtalaja e sík felszínén, de agyagon képződött, minősége közepes. A településen keresztülfolyik a Cserta folyó, amely Szécsisziget irányában, a falutól nyugatra torkollik bele a Kerkába, amely a Dráva bal parti mellékfolyója.'),
    ('Ikrény', 'Magyarország északnyugati részén, Győrtől nyugat-délnyugatra 8 kilométer-re helyezkedik el. Természetföldrajzilag a Rábaköznek a Tóköz névvel illetett részéhez tartozik. A falu teljes egészében a Rába bal partján épült. Ikrény és Rábapatona között egy északnyugat-délkelet irányban húzódó dűnesáv található, ennek feltárásánál 3-4 méter vastag futóhomokréteget találtak.'),
    ('Iliny', 'Balassagyarmattól délkeletre, Csitár déli szomszédságában fekszik. Bizonyos régi ellentmondást olvashatunk az Esztergomi Káptalan bizonyság levele szerint 1348. esztendőben, melyben ezen helység Inini nevezettel íratott. Később Illény formában volt a község neve bejegyezve, az 1877-es évtől pedig a mai nevén tartják nyilván a községet. Ilíny Balassagyarmat közelében fekvő magyar kisközség 48 házzal és 187 római katolikus vallású lakossal.'),
    ('Ilk', 'A Nyírség északkeleti részén fekszik, Vásárosnamény nyugati szomszédjában. A közvetlen szomszédos települések: észak felől Gyüre, északkelet felől Nagyvarsány és Kisvarsány, kelet felől Vásárosnamény, délnyugat felől Nyírmada, északnyugat felől pedig Gemzse. A Kisvárdát Vásárosnaménnyal összekötő 4108-as út mentén fekszik, ezen érhető el mindkét végponti város felől.'),
    ('Illocska', 'Villánytól dél-délkeleti irányban fekszik, közvetlenül a déli (magyar-horvát) államhatár mellett, bár határátkelőhellyel nem rendelkezik. Határában húzódik a Karasica-patak található, mely az elmúlt évszázadok során meghatározó volt az itt élők életében. A szomszédos települések a határ magyarországi oldalán: észak felől Kislippó, északkelet felől Ivándárda, nyugat felől Beremend, északnyugat felől pedig Lapáncsa.'),
    ('Imola', 'A Galyaság tájegység déli részén helyezkedik el, a megyeszékhely Miskolctól közúton mintegy 45 kilométerrel északnyugatra. Az Aggteleki Nemzeti Parkkal határos. A környező települések: kelet felől Kánó (5 kilométer), délkelet felől Zubogy, délnyugat felől Ragály (4 kilométer), nyugat felől Trizs, északnyugat felől pedig Aggtelek (13 kilométer). A legközelebbi városok: Rudabánya (15 kilométer), Putnok (25 kilométer) és Kazincbarcika (27 kilométer).'),
    ('Imrehegy', 'Imrehegy a Duna–Tisza köze nyugati felén, három történeti-néprajzi táj: a Kiskunság, a Bácska és a Kalocsai-Sárköz találkozásánál fekszik. A szomszédos települések: észak felől Soltvadkert, északkelet felől Pirtó, délkelet felől Kiskunhalas, délnyugat felől Császártöltés, északnyugat felől pedig Kecel. Csak kevés híja van annak, hogy nem határos dél felől még Kéleshalommal is.'),
    ('Inke', 'Különálló településrésze az egykor önálló – még ma is saját temetővel rendelkező – Kisdencs, a központjától mintegy másfél kilométerre északnyugatra. A közvetlenül határos települések: észak felől Pat és Varászló, északkelet felől Nemesdéd, kelet felől Vése, dél felől Kaszó, nyugat felől pedig Iharosberény. A többi környező községgel csak mezőgazdasági utak kötik össze.'),
    ('Ináncs', 'A Hernád folyó völgyének déli részén, a Cserehát dombvidéke és a Zempléni-hegység között fekszik, a megyeszékhely Miskolctól 35 kilométerre északkeletre. A közvetlenül határos települések: észak felől Forró, kelet felől Hernádszentandrás, délnyugat felől Csobád, nyugat felől Léh, északnyugat felől pedig Rásonysápberencs és Detek. Dél felől a legközelebbi település a Hernád túlsó partján fekvő Felsődobsza, de a közigazgatási területeik – kevés híján – nem érintkeznek.'),
    ('Inárcs', 'Területének északkeleti része a kiskunsági homokhátság buckáira, déli része a Pesti-síksághoz tartozó ócsai lápterület határára terjed ki. A községterület jelentős részét erdők borítják. A sztrádának inárcsi csomópontja ugyan nincsen, de a 35-ös kilométerénél kialakított pihenőhely így is lehetőséget biztosít a helyiek és az ide látogatók számára a le- és felcsatlakozásra.'),
    ('Ipacsfa', 'A további szomszédos települések: délkelet felől Gordisa, dél felől Drávaszabolcs, nyugat felől pedig Kovácshida. Ipacsfa nevének első említését 1554-re datálják, azonban valószínűleg már korábban is létezett. Egyesek az 1237-es évszámhoz kötik a falu első említését. A korábbi dátum annál is valószínűbb, mivel az Ipacsfa határának déli részén található Iszró nevű dűlőnév még az 1852-es kataszteri térképen is szerepelt Izro-, az 1883-as térképen pedig Iszró néven.'),
    ('Ipolydamásd', 'Külterületi településrészei: Ódamásd A falu közigazgatási területe régészeti lelőhelyekben igen gazdag, az Árpád-korban még az Ipoly völgyében és a Damásdi-patak völgyében is több lakott hely létezett, melyek a 13. század végére, 14. század elejére elnéptelenedtek. Nem tudni, hogy az Árpád-kor végét jellemző anarchikus állapotok, vagy esetleg tudatos telepítéspolitika (összefüggő királyi vadászterület biztosítása) következtében helyezkedik el.'),
    ('Ipolyszög', 'A település határában terül el az Égerláp természetvédelmi terület. A közvetlenül határos települések: kelet felől Balassagyarmat, délkelet felől Csesztve, dél felől Érsekvadkert, nyugat felől pedig Dejtár. Az észak felől legközelebbi település, Kóvár (Koláre) már Szlovákiához tartozik. A község Budapesttől 80, Balassagyarmattól 7 kilométerre fekszik.'),
    ('Ipolytarnóc', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Határában keresztezi az Ipoly a szlovák-magyar szárazföldi országhatárt, és itt kezdődik a folyó völgyének magyarországi szakasza. Budapesttől 140, Szécsénytől 24, Salgótarjántól 25,5 kilométerre fekszik.'),
    ('Ipolytölgyes', 'Ipolytölgyes az Ipoly bal partján fekszik, a Börzsöny nyugati lábánál, Ipolykiskeszivel szemben. A falutól északra ömlik a Ganádi-patak (más néven Cserge-patak) az Ipolyba. A község területének csaknem fele a Duna–Ipoly Nemzeti Park része. Északról és északkeletről Nagybörzsöny, délről Letkés, nyugatról Ipolykiskeszi, délnyugatról pedig Ipolyszalka községekkel határos.'),
    ('Ipolyvece', 'Az Ipoly völgyében fekszik, közvetlenül az országhatár mellett. Közigazgatási területe két különálló területrészből áll. A teljes terület több mint 90 százalékát kitevő – a belterület egészét is magában foglaló – nagyobb részt a másik, jóval kisebb, lakatlan területrésztől egy, Patak községhez tartozó, pár száz méteres sáv választja el. Először 1285-ben említették az oklevelek a települést, akkor Huntfi Demeter drégelyi várának tartozékaként.'),
    ('Iregszemcse', 'Nem messze fekszik a somogyi határtól, a Somogyi-dombság ölelő dombjai között. Emellett itt található Viczay-Kornfeld kastély, mely jelenleg speciális diákotthonnak ad helyet, parkja természetvédelmi terület. Bartók Béla 1907-ben 17 népdalt gyűjtött itt össze, köztük a Hej, Dunáról fúj a szél című, széles körben ismert dalt.'),
    ('Irota', 'Edelénytől 18 kilométerre északkeletre, a megyeszékhely Miskolctól mintegy 40 kilométerre északra fekszik, a Cserehát szívében. A két legközelebbi település a mintegy 2 kilométerre délre fekvő Szakácsi és az annak déli szomszédjában, 6 kilométerre található Lak. A legközelebbi város Edelény. Határos még észak felől Rakacával, északkelet felől Gagybátorral, kelet felől Gadnával, délkelet felől Felsővadásszal, nyugat felől Aboddal, északnyugat felől pedig Rakacaszenddel is, de ezek egyikével sincs közúti kapcsolata.'),
    ('Isaszeg', 'Budapest belvárosától 30 kilométer-re keletre fekszik a Gödöllői-dombságban. Határában folyik a Rákos-patak. Gödöllő, Dány, Pécel, Valkó, Nagytarcsa, Kistarcsa és Kerepes. Első okleveles említése 1274-ből, Ilsuazyg formában szerepelt, későbbi oklevelekben Irsazeg, Irsuazeg, Irsuazhig, Ilsuasak, Ilsuascek, Ilsasceg, Isuasceg, Ilsazig, Ilsasceg, Ilswazyg, Yrsazig, Yrsuazek formákban is szerepel.'),
    ('Ispánk', 'Az Őrségben, a Vasi-Hegyháton, Őriszentpétertől északkeletre fekszik. Ispánk neve szláv eredetű, az ispán becéző alakja. A német szakirodalom az Espenwang/Espang szóból származtatja. Első írásos említése 1393-ból ismert, Yspank formában helyezkedik el. A település népességének változása: A 2011-es népszámlálás során a lakosok 88,9%-a magyarnak mondta magát (11,1% nem nyilatkozott).'),
    ('Istenmezeje', 'Istenmezeje és környéke már a bronzkorban is lakott hely volt, az itt talált leletek szerint. A falu határában 1865-ben késő bronzkori, a pilinyi kultúra korából származó leleteket találtak. Az itt feltárt sírban eltemetett előkelő férfi sírjába beletették a rangját jelző fejdíszét, egy nagyon szép bronzdiadémot is. A koronaszerű fejék az eltemetett férfi csontvázának koponyáján volt, míg a nyak körül egy, ostreaféle kagylók teknőiből szépen faragva és simára csiszolva készült ujjnyi vastagságú gyöngyfüzér szemei feküdtek.'),
    ('Istvándi', 'A legközelebbi városok Barcs és Szigetvár, mindkettőtől nagyjából 15-15 kilométer választja el. A szomszédos települések: észak felől Kálmáncsa, kelet felől Kisdobsza, délkelet felől Zádor, dél felől Darány, nyugat felől pedig Szulok. Első ismert írásos említése az 1332-es pápai tizedjegyzékben található, ekkor Stehpandi alakban írták. Ebben az időben már egyházas hely volt.'),
    ('Iszkaszentgyörgy', 'Iszkaszentgyörgy Székesfehérvártól északnyugati irányban, attól mintegy 10 kilométernyire található. Határát északról a Bakony, nyugatról a belőle délre nyúló Iszka-hegy, délről a Sárrét, keletről pedig a Móri-árok alkotja. Délnyugati szomszédjával, Csórral egy számozatlan, alsóbbrendű út kapcsolja össze. Autóbusszal a fehérvári buszpályaudvar 10-es jelzésű kocsiállásáról induló menetrend szerinti járatokkal.'),
    ('Iszkáz', 'A Hunyor-patak jobb partját kísérő, annak szintjétől körülbelül tizenöt méter magasságig emelkedő dombsor tetején nyúlik el, mintegy két kilométer hosszan. Szomszédai: észak felől Kiscsősz, északkelet felől Kisszőlős, kelet felől Somlószőlős, délkelet felől Somlójenő, dél felől Tüskevár, délnyugat felől Karakószörcsök, nyugat felől pedig Kerta. A mai Iszkáz területe…'),
    ('Isztimér', 'Területe, a mintegy 1000 fős lakosságszámához képest viszonylag nagy. Határában található a megye legmagasabb pontja, a 479,6 méteres Kövesdomb, legnagyobb tájrésze a nagyjából 400 méter magas, 20 négyzetkilométeres kiterjedésű Mellár-fennsík. Isztimér nevének első ismert okleveles említése 1193-ból származik, Stamer alakban helyezkedik el. Mint sok más magyar város és község, Isztimér is a törökök pusztításának lett áldozata.'),
    ('IV. kerület', 'A IV. kerület, vagy hivatalos nevén Újpest a magyar főváros, Budapest egyik kerülete a Duna folyam bal partján, a pesti oldalon helyezkedik el. Északon Dunakeszi, nyugaton a Duna által a III. kerület, délen a XIII. kerület és a XIV. kerület, míg keleten az XV. kerület határolja. A kerületnek jelenleg 6 városrésze van: Istvántelek, a Népsziget északi része, Káposztásmegyer, Megyer, Székesdűlő és Újpest.'),
    ('Ivád', 'Pétervására nyugati szomszédságában fekszik. További közvetlenül határos települések még: dél felől Mátraballa, nyugat felől Mátraterenye, nyugat-északnyugat felől pedig Mátranovák. Csak közúton érhető el, a 23-as főúton, amelyről két helyen is le lehet térni a településre: Bátonyterenye felől a 20+300-as kilométerszelvény közelében, illetve Pétervására felől még a 21. kilométer elérése előtt.'),
    ('Iván', 'Körjegyzőségi székhely. Külterületének 8 tavát a horgászok szívesen keresik fel. A szomszédos települések: észak felől Pusztacsalád, kelet felől Dénesfa, délkelet felől Répceszemere, dél felől Csáfordjánosfa, Csér és Nemesládony, délnyugat felől Sajtoskál, nyugat felől Simaság, északnyugat felől pedig Újkér. A környező községek többsége felől elérhető közúton, alsóbbrendű utakon helyezkedik el.'),
    ('Ivánbattyán', 'Villánytól északnyugatra helyezkedik el, a Villányi-hegység északnyugati részén. A szomszédos települések: észak felől Kiskassa, északkelet felől Nagybudmér, kelet felől Kisbudmér, délkelet felől Kisjakabfalva, dél felől Villánykövesd, nyugat felől pedig Palkonya. Ivánbattyán (Iván) nevét az oklevelek 1332-ben említették először, Iwanként. 1340-ben Iuannak írták nevét.'),
    ('Iváncsa', 'Budapest 51, Százhalombatta 23, Velence és Baracska 19-19, Ercsi 15, Adony pedig 6 kilométer távolságra található. Megállóhelye a település központjától körülbelül 3 kilométerre van a Budapest–Pécs-vasútvonalon, Beloiannisz és Besnyő közigazgatási határa közelében, de beloianniszi területen. Nyugatról az M6-os autópályán, keletről a „régi” 6-os úton közelíthető meg, mindkét irányból a 6205-ös úton helyezkedik el.'),
    ('Ivándárda', 'Mohácstól délre, Villánytól délkeletre helyezkedik el, közvetlenül a déli országhatár mellett. A szomszédos települések a határ magyar oldalán: észak felől Lippó, északkelet felől Sárok, nyugat felől pedig Kislippó. Kelet és dél felől a községhatár egybeesik az államhatárral, ott a község valószínűleg a horvátországi Főherceglak (Kneževo) és Baranyavár (Branjin Vrh) településekkel határos.'),
    ('IX. kerület', 'Az IX. kerület, vagy hivatalos nevén Ferencváros a magyar főváros, Budapest egyik kerülete, amely a Duna bal partján, Pesten fekszik. Északon az V. kerület és a VIII. kerület, nyugaton a Duna által a XI. kerület, délen a XXI. kerület és a XX. kerület, míg keleten az XIX. kerület és a X. kerület határolja. A városrész 1792-ben I. Ferenc trónra lépésének alkalmából kapta ezt a nevet.'),
    ('Izmény', 'A Dunántúli-dombságban, a Mecsektől északra található. Szekszárd, a megyeszékhely körülbelül 35 kilométerre, míg a legközelebbi nagyobb város, Bonyhád körülbelül 15 kilométerre található. A legközelebbi szomszédos település Györe helyezkedik el. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. A régészeti leletek tanúsága szerint már az őskorban, illetve az ókorban is lakott volt a település környéke.'),
    ('Izsák', 'A szomszédos települések: kelet felől Ágasegyháza, délkelet felől Orgovány, dél felől Páhi, délnyugat felől Csengőd és Soltszentimre, nyugat felől pedig Fülöpszállás. Északkelet felől a legközelebbi település Fülöpháza, északnyugat felől pedig Szabadszállás, de közigazgatási területe egyikével sem érintkezik, mindkettőtől elválasztja egy pár kilométeres átlagos szélességű, de kelet-nyugati irányban hosszan elnyúló, Fülöpszálláshoz tartozó külterületi sáv.'),
    ('Izsófalva', 'A környező települések: Ormosbánya (2 kilométerre), Rudolftelep (4 kilométerre), Szuhakálló (4 kilométerre), Múcsony (6 kilométerre). A legközelebbi városok: Rudabánya (6 kilométerre) és Kazincbarcika (10 kilométerre). A települést 1283-ban említik először, Hurva néven helyezkedik el. Valószínűleg horvát telepesek lakták. A török időkben elnéptelenedett, a 18. században települt be újra.'),
    ('Jakabszállás', 'Kecskeméttől 17 kilométerre fekszik, dél-délnyugati irányban. A szomszédos települések: észak felől Helvécia, kelet felől Fülöpjakab, délkelet felől Bugac, dél felől Bugacpusztaháza, nyugat felől pedig Orgovány. A településnek jó az autóbuszközlekedése a megyeszékhely, Kecskemét felé. Az Árpád-kor óta lakott település a török hódoltság korában elnéptelenedett, területe pusztává vált.'),
    ('Jenő', 'Nádasdladány 4 kilométer, Ősi 8,5 kilométer, Füle 8 kilométer, Kőszárhegy 10 kilométer, Szabadbattyán 14 kilométer távolságra található. A falu a Jenő törzsbeliek települése volt, amelyben 1260 körül kisnemesek éltek. A település a török hódoltság alatt osztozott a környék falvai sorsával, hosszú ideig néptelen puszta volt, de később újranépesült. Az 1770-től 1949-ig a falu közigazgatásilag Nádasdladányhoz tartozott. 1950-től vált önálló településsé.'),
    ('Jobaháza', 'Magyarország északnyugati részén, a Kisalföld közepén fekszik, Csornától, a hozzá legközelebbi várostól 8 kilométerre délnyugatra, Győrtől, a megyeszékhelytől 40 kilométerre nyugatra. Határa – mint általában az egykori nemesi falvaké – szűk. Ősi településszerkezete egy út menti falu képét tükrözi, amely szerkezet az évszázadok folyamán további utcákkal egészült ki.'),
    ('Juta', 'Kaposvártól 7 kilométerre északnyugatra fekszik. Lankás dombok veszik körül, a határ szántóföldjeit északon tölgyes, nyugaton többnyire akácerdő tarkítja. Az erdők 171 hektáron terülnek el, a mezőgazdasági termőterület 1560 hektáros. A községet a jutai vízfolyás szeli ketté. A falu valószínűleg már a honfoglalás korától lakott, bár az első okleveles adat 1284-ből származik.'),
    ('Jágónak', 'A Dunántúli-dombságban, a Zselic északi részén, a Sarádi-patak mellett fekszik, Tolna megye délnyugati sarkában. Közigazgatási területe észak-déli irányban hosszan elnyúlik, a legészakibb és legdélibb határpontjai közti távolság majdnem 10 kilométer. A közvetlenül határos települések: észak felől Kapospula, észak-északkelet felől Dombóvár, kelet-északkelet felől Kaposszekcső, kelet felől Vásárosdombó, délkelet felől Tarrós, dél felől Meződ, délnyugat felől Baranyajenő, északnyugat felől pedig Kercseliget.'),
    ('Ják', 'Itt található a magyar romanikus templomépítészet legjelentősebb megmaradt alkotása. Szombathelytől 10 kilométerre délre fekszik, a Jáki-Sorok partján, az osztrák határ közvetlen közelében. Nyugati szomszédja, Felsőbeled (Oberbildein) már Ausztriában található. Balogunyommal és a 86-os főúttal a 8712-es, Náraival a 8715-ös út köti össze, és érinti még a területét egy rövid szakaszon a 8713-as út is.'),
    ('Jákfa', 'Előbbi a mai belterület északi, utóbbi pedig a déli részét képezi. A Rába folyó bal parti oldalán terül el. Északi határában fut a Kőris-patak, amelybe keleti külterületei között torkollik bele a Pereszteg-patak. A szomszédos települések: észak felől Uraiújfalu, kelet felől Ostffyasszonyfa, dél felől Rábapaty, nyugat felől Zsédeny, északnyugat felől pedig Vasegerszeg.'),
    ('Jákfalva', 'A megye északnyugati részén helyezkedik el, Miskolctól mintegy 35 kilométerre északnyugatra. A környező települések: észak felől Felsőkelecsény, kelet felől Felsőnyárád (3 kilométer), dél felől Sajókaza (11 kilométer), nyugat felől pedig Dövény (2 kilométer). A legközelebbi városok: Rudabánya (8 kilométer) és Kazincbarcika (kb. 15 kilométer). Csak közúton érhető el, Felsőnyárád vagy Dövény érintésével, a 2605-ös úton.'),
    ('Jákó', 'Kaposvártól nyugatra, közúton 29, vasúton 20 kilométerre fekszik. Jákó nevét az ismert írott források közül az 1332-1337. évi pápai tizedjegyzék említette először. 1438-ban Albert király Hetesi János itteni birtokait Guthi Ország Mihálynak és Jánosnak adta. 1526-ban II. Lajos király Jákó egy részét Perneszi Ferencnek és testvéreinek, Péternek és Balázsnak adományozta. 1536 és 1559 között több birtokosa is volt.'),
    ('Jánd', 'A közvetlen szomszédos települések: északkelet felől Tákos és Csaroda, kelet felől Hetefejércse, délkelet felől Gulács, dél felől Panyola, délnyugat felől Olcsvaapáti, északnyugat felől pedig Vásárosnamény (Gergelyiugornya). A térség jelentősebb települései közül Vásárosnamény 7, Fehérgyarmat 23, Tarpa és Tivadar 17-17, Kisar 18, a megyeszékhely Nyíregyháza pedig 67 kilométer távolságra található.'),
    ('Jánkmajtis', 'Jánk és Majtis községek egyesítésével keletkezett. A megye keleti részén, a Szamosközben fekszik. Szomszédai: észak felől Darnó, északkelet felől Kisnamény, délkelet felől Császló, dél-délkelet felől Csegöld, dél felől Hermánszeg és Szamossályi, délnyugat felől Szamosújlak, nyugat felől Zsarolyán, északnyugat felől pedig Nagyszekeres és Kisszekeres.'),
    ('Jánoshalma', 'A város a Bácskai-síkvidék és a Bugaci-homokhát találkozásánál helyezkedik el. A határában folyik a Kígyós-főcsatorna. Kiskunhalastól mintegy 20 kilométerre található Baja irányában. Az illancsi vidék adja természeti értékeit. Az 1989-ben várossá lett Jánoshalma 13 220 hektár területen fekszik, melynek kb. 15%-a belterület, 25%-a erdő, 60%-a mezőgazdasági terület, szántó.'),
    ('Jánoshida', 'Jászberény kb. 20 kilométer-re található a megyeszékhellyel ellentétes irányban. Területe síkvidék, a Zagyva árterülete, közepesen vagy jól termő vályogtalajjal. A legkorábbi településnyomok a bronzkorból, az ún. hatvani kultúra idejéből, i. e. 1800-1700 tájáról valók. Az avarok idején is lakott hely volt – nagy jelentőségű volt az avar kettős síp megtalálása – és folyamatosan az is maradt, mert itt volt alkalmas átkelőhely, rév a Zagyva folyón. 1186 körül III.'),
    ('Jánosháza', 'Különálló településrésze Körtvélyespuszta (vagy Körtvélyesmajor), a központjától bő 3 kilométerre nyugat-északnyugatra helyezkedik el. Keleti határa nagyrészt sík, a Marcal felé ereszkedő terület, míg nyugat felől a Mosó-árok völgyének dombosabb térszíne húzódik. A vidék nagy része mezőgazdasági művelés alatt áll, vízfolyásainak mellékét rétek kísérik, míg déli irányban nagyobb kiterjedésű erdők borítják a tájat.'),
    ('Jánossomorja', 'Magyarország északnyugati szélén fekszik, Mosonmagyaróvártól 13 kilométerre délnyugatra, az osztrák–magyar határtól 5 kilométerre. Három, egykor önálló település alkotja – nyugatról kelet felé: Pusztasomorja, Mosonszentjános és Mosonszentpéter –, melyek mára gyakorlatilag összenőttek egymással. Északnyugati szomszédjával, Várbaloggal a 8508-as út kapcsolja össze.'),
    ('Járdánháza', 'Miskolctól közúton kb. 65 kilométer-re nyugatra, Ózdtól 6 kilométer-re délre található, a Hangony-patakba torkolló Hódos-patak völgyében, dombsági területen. Mindössze három települési szomszédja van: észak felől Arló, kelet felől Csernely, dél felől pedig Borsodnádasd. Csak közúton érhető el, a 25-ös főúton. A cseh hospesek által elfoglalt terület eredetileg Arlóhoz tartozott.'),
    ('Jármi', 'Jármi (Jaromtheleke, Jarwmytheleke, Jarmy, Jarmytelek) neve első ízben 1325-ben tűnik fel az oklevelekben, s ekkor még Mátészalkához tartozott. Nevének eredete bizonytalan, járom alapszava déli szláv eredetű magyar köznév, mai alakjában elvonás eredményeként jött létre. A térség fontosabb települései közül Vaja 9,5, Őr 5,5 kilométer távolságra található.'),
    ('Jásd', 'Fekvését a Bakony Tési-fennsík alatti medencéje és a Gaja-patak völgye határozza meg. Közigazgatási területe Tés, Bakonynána, Szápár és Bakonycsernye területével is határos, de belterülete vonatkozásában zsákfalunak tekinthető, közúton csak azon a 3,5 kilométer hosszú, 82 111-es számú mellékúton érhető el, amely a Várpalota és Szápár között húzódó 8213-as útból ágazik ki, Bakonycsernye Inotapuszta nevű külterületi településrészénél.'),
    ('Jászalsószentgyörgy', 'A Jászság legdélibb fekvésű községe a Zagyva bal partján, Szolnok és Jászberény között. A közvetlenül határos községek északkelet felől Jászkisér, kelet felől Jászladány, dél felől Szászberek, délnyugat felől Jászboldogháza, nyugat felől Jánoshida, északnyugat felől pedig Alattyán és Jásztelek. Keletre Jászkisér, Jászladány és Szászberek egyformán 6–6 kilométer távolságra fekszik a falutól.'),
    ('Jászapáti', 'Jászapáti a Jászság második legnagyobb települése. A település a Tisza és a Zagyva folyó közötti síkságon terül el. A közvetlen szomszédos települések: észak felől Jászszentandrás, kelet felől Jászivány, délkelet felől Jászkisér, délnyugat felől Jásztelek, nyugat felől Jászjákóhalma, északnyugat felől pedig Jászdózsa és Tarnaörs. Északi szomszédjával, Jászszentandrással a 3228-as út köti össze.'),
    ('Jászberény', 'Gyakran emlegetik a Jászság fővárosaként. A megye második legnépesebb települése Szolnok után helyezkedik el. A város történelme szorosan összefonódik a jászok történetével, akik a középkorban, a 13. század környékén telepedtek le itt. A település népessége jelentős szerepet játszott a térség gazdasági és kulturális fejlődésében, különösen a mezőgazdaság és az állattenyésztés terén.'),
    ('Jászboldogháza', 'Jászberénytől kb. 15 kilométer-re, délre fekszik. Szomszédos települések: Jánoshida (kb. 5 kilométer), Tápiógyörgye (kb. 8 kilométer). Régészeti leletekben főként a Csíkos nevű határrésze gazdag, ahol réz-, bronz-, szarmata- és népvándorlás kori tárgyak kerültek elő. Különösen jelentős volt a 251 síros avar temető feltárása. A település nevét egy Mátyás…'),
    ('Jászdózsa', 'A történelmi településközpont a Tarna egy viszonylag kanyargósabb – a szabályozások révén mára már lényegében holtággá vált – szakaszának jobb partján jött létre, de a lakott terület néhány utcányi része a bal parton alakult ki, s a két falurész összekapcsolására az idők során összesen három híd létesült. A folyócska mai állapotát tekintve Jászdózsának már szinte a teljes lakott területe (egyetlen belterületi utca, a Széchenyi út keleti része kivételével) a jobb parti oldalon található.'),
    ('Jászfelsőszentgyörgy', 'Szomszédos Jászberény, Szentlőrinckáta, Tóalmás és Nagykáta határaival. Jászfelsőszentgyörgy az önkormányzattal rendelkező települések között a leghosszabb településnévvel rendelkező település Magyarországon. A Szentgyörgy utótagot pedig templomának védőszentje után kapta. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják. Első írásos említése 1331-ből származik, Scentgyurg…'),
    ('Jászfényszaru', 'A környező nagyobb városok közül Hatvantól 11 kilométerre délkeletre, Jászberénytől pedig 17 kilométerre északnyugatra található. Központján a 3106-os út húzódik végig, ez köti össze Zsámbokkal is. Boldog felől a 3126-os úton érhető el, s a határszélét délen érinti még a 3108-as út is. Az ország távolabbi részei felől közúton a legegyszerűbben…'),
    ('Jászivány', 'Jászivány a Jászság keleti részén található.Az Alföld területén fekszik. A település a Tisza és a Zagyva folyók közötti síkságon terül el Jászberény és Heves között. 398 fő a lakossága és 213 a lakások száma. A településen halad át a szarmaták által 324 és 337 között épített, a Dunát a Tiszával összekötő Csörsz árka nyomvonala. Első írásos említése 1234-ből származik, Iwan'' alakban helyezkedik el.'),
    ('Jászjákóhalma', 'A község a Tarna bal partján fekszik, ám a településtől néhány száz méterre folyik a Zagyva is, illetve a déli határszéle közelében található a két folyó összefolyása is. (Érdekesség, hogy bár a Tarna a nagyobb, az egyesült folyó a Zagyva nevet viseli tovább. Ennek oka, hogy a földmozgások következtében a Tarna medre úgy módosult, hogy keresztezte a Zagyva folyását.) Területén belülre esik (mérések szerint) a Jászság közepe.'),
    ('Jászkarajenő', 'Közigazgatási területének nyugati részét egy szakaszon érinti a Nagykőrös–Szolnok közti 4613-as út is, de belterületeit az elkerüli. A Jászkarajenő lakottságára vonatkozó legkorábbi nyomok a kora vaskorra nyúlnak vissza. A település két pusztából: Karából és Jenőből alakult…'),
    ('Jászkisér', 'A megye székhelyétől, Szolnoktól körülbelül 35 kilométerre található. A közvetlenül határos települések: észak felől Jászivány, kelet felől Pély, délkelet felől Tiszasüly, dél felől Jászladány, délnyugat felől Jászalsószentgyörgy, nyugat felől Jásztelek, északnyugat felől pedig Jászapáti. Közúton három irányból közelíthető meg: Jászladány vagy Jászapáti érintésével a 3227-es, Tiszasüly, illetve Besenyszög felől pedig a 3225-ös úton helyezkedik el.'),
    ('Jászladány', 'A megye északi szélén, a Jászság délkeleti részén fekszik. A közvetlenül szomszédos települések: észak felől Jászkisér, kelet felől Tiszasüly, délkelet felől Besenyszög, dél felől Szászberek, nyugat felől pedig Jászalsószentgyörgy. A térség fontosabb települései közül Jánoshida 9, Jászapáti 20, Szolnok pedig 24 kilométer távolságra található. Közúton négy irányból közelíthető meg: Újszász és Jászapáti felől a 3227-es, Jászalsószentgyörgy és Tiszasüly felől pedig a 3226-os úton helyezkedik el.'),
    ('Jászszentandrás', 'Budapestről kb. 100, Szolnoktól kb. 50 kilométer-re található. Szomszédos települések: közúton csak Jászapáti és Heves érhető el. A települést 1399-ben említették először egy oklevélben "Szentandrás" névvel, mint az egri káptalan birtokát. Ezután, mint puszta szerepel a történelemben, bár folyamatosan voltak lakói. 1750-ben kerül Jászárokszállás birtokába.'),
    ('Jászszentlászló', 'Kiskunfélegyháza és Kiskunmajsa között fekszik, előbbitől nagyjából 18 kilométerre délre, utóbbitól 9 kilométerre északra. A Római Birodalom óta illír népek lakták ezt a vidéket. A honfoglalás időszakában őseink a mai község területén nem telepedtek meg. A középkori települést – melyről az ún. Templom halom az egyetlen emlék – minden valószínűség szerint kunok lakhatták, akiket IV.'),
    ('Jásztelek', 'A legközelebbi város az alig 6 kilométerre lévő Jászberény. A megyeszékhely Szolnoktól 40, Budapesttől nagyjából 85 kilométerre helyezkedik el. A szomszédos települések: észak felől Jászjákóhalma (kb. öt kilométerre), dél felől Alattyán (kb. egy kilométerre), északnyugat felől pedig Jászberény. Külterületei érintkeznek még kelet-délkelet felől Jászkisér és Jászalsószentgyörgy, dél-délnyugat felől pedig még Jánoshida határszélével is, de mindhárom utóbbi település valójában aránylag távol esik tőle.'),
    ('Jászágó', 'A megye északnyugati csücskében fekszik, a Jászság északnyugati részén, Hatvantól délkeletre, az Ágói-patak partján. Mindössze négy településsel határos közvetlenül: a szomszédi északkelet felől Jászárokszállás, délkelet felől Jászberény, délnyugat felől Pusztamonostor, északnyugat felől pedig Csány. Pusztamonostorra naponta 1 busz közlekedik, Jászárokszállásra hétköznap 8, szombaton 5, vasárnap pedig mindössze 3.'),
    ('Jászárokszállás', 'A megye északi szélén fekszik, mint annak egyik legészakibb fekvésű települése, sík vidéken, Jászberénytől 17 kilométerre észak-északkeletre. Északi határában húzódik a Gyöngyös-patak. A közvetlen szomszédos települések: észak felől Adács, kelet felől Visznek, délkelet felől Tarnaörs, dél felől Jászdózsa és Jászberény, délnyugat felől Jászágó, nyugat felől Csány, északnyugat felől pedig Atkár és Vámosgyörk.'),
    ('Jéke', 'Az Északkelet–Nyírségben fekszik, Nyíregyházától mintegy 53 kilométerre északkeletre. Mai képét a kultúrnövényzet, a szántóföldek, gyümölcsösök és kertgazdaságok jellemzik, agrártájait félkultúr kaszálók és legelők színesítik. A gazdaságföldrajzi tényezők főként mezőgazdasági termelésre, ezen belül alma, burgonya, és kukorica termesztésére adnak lehetőséget.'),
    ('Jósvafő', 'A településen nyílik a Baradla-barlang. Miskolctól közúton körülbelül 65 kilométerrel északra, az Északi-középhegységben, azon belül az Aggteleki-karszt középső részén, az Aggteleki Nemzeti Park területén fekszik, a Jósva forrásvidékén. Mindössze néhány kilométerre fekszik a szlovák határtól, de a falu közigazgatási területének nincs határszakasza, az államhatár melletti területek az Aggteleki-karsztnak ezen a szakaszán részben Aggtelekhez, részben Szögligethez tartoznak.'),
    ('Kaba', 'Városi rangját 2003. július 1-jén kapta. Az Alföldön, a Hajdúság déli részén fekszik. A szomszédos települések: északkelet felől Hajdúszoboszló, kelet felől Hajdúszovát, délkelet felől Tetétlen, dél-délnyugat felől Báránd, délnyugat felől Püspökladány, északnyugat felől pedig Nádudvar. A megyeszékhelytől, Debrecentől 32 kilométerre dél-nyugatra helyezkedik el.'),
    ('Kacorlak', 'A településen polgárőrség működik. Nagykanizsa északi vonzáskörzetében fekszik, a várostól mintegy 10 kilométerre északra, a Principális-csatorna nyugati oldalán. Az út déli végpontjától, Újnéppusztától mintegy másfél, Pölöskefőtől kicsit kevesebb, mint három kilométerre helyezkedik el. Kacorlak első írásos említése 1314-ből való Lok néven helyezkedik el.'),
    ('Kacsóta', 'A további szomszédos települések: északkelet felől Csonkamindszent, délkelet felől Királyegyháza, délnyugat felől Szentdénes, nyugat felől Nagypeterd, északnyugat felől pedig Nagyváty. Kacsóta már az Árpád korban is lakott hely volt. 1375-ben említik először az oklevelek Kardosfalva néven. Ekkor a mai község helyén három falu is állt: Kardosfalva, Giróttfa és Boldogasszonyfa nevét említik itt a korabeli okiratok. 1542-ben neve Kachota-ként volt említve, s Giróttfa és Boldogasszonyfa már csak mint külterületi rész volt említve.'),
    ('Kadarkút', 'A kistérségek 2014-es megszüntetése előtt a Kadarkúti kistérség székhelye volt. Kaposvártól 25 kilométerre helyezkedik el, Belső-Somogy és a Zselic határán. A település alaprajza a 19. századi rendezésnek köszönhetően szabályos: egymásra merőleges utcákból áll. A miocén és pliocén időszakban a területet a Pannon-tenger borította, melynek visszahúzódását követően a terület jellemzően mocsaras volt.'),
    ('Kajdacs', 'A Duna-Sió közén, a Mezőföld déli részén terül el, Szekszárdtól 24 kilométerre észak-északnyugatra. A közvetlenül határos települések: észak felől Nagydorog, délkelet felől Tengelic, délnyugat felől Kölesd, nyugat felől Borjád (Kölesd része), északnyugat felől pedig Sárszentlőrinc. Északkelet felől a legközelebbi település Pusztahencse, de közigazgatási területeik nem érintkeznek.'),
    ('Kajárpéc', 'Felszíne változatos. Ez utóbbi esetben a 8306-os útra lekanyarodva végig kell haladni Gyömöre központján, majd e község déli szélétől mintegy 2 kilométernyire kell balra fordulni, a 83 125-ös számú mellékútra helyezkedik el. A település déli része, Kajár tulajdonképpen zsákfalunak tekinthető…'),
    ('Kajászó', 'A római birodalmat keletről megtámadó hunok a mai Százhalombatta térségénél keltek át a Dunán, és jelentős ütközet zajlott a közeli Tárnok-völgyben. Az ütközetben a hun Keve vezér is elesett, akit a monda szerint itt temettek el. Egyes források szerint maga Attila vezér is itt nyugszik. A település neve is innen eredeztethető: eredetileg Keveháza, majd Keveaszó, (Cuwe azoa, Keueozou), később Keazó, végül mai kiejtéssel Kajászó lett.'),
    ('Kakasd', 'Egykor különálló településrészei közül Belac a főúttól délre helyezkedik el, míg a történelmi Kakasd falu az úttól északra alakult ki. Határában, Bonyhád felé helyezkedik el a hozzá tartozó Széptölgyes. Kakasd közelében már a kőkorszakban település volt, a 12. század derekán határában templom állt. A községnév, először egy Zsigmond király korából való, 1436-ban kiadott oklevélben szerepel.'),
    ('Kakucs', 'Területén halad át a mélyebben fekvő dél-délkeleti részek belvizeit elvezető Duna-völgyi főcsatorna. A község 2180 hektáros területének felszínét részben erdősített kötött futóhomok borítja, de nyugat-délnyugati felén nedvesebb, jobb minőségű mezőségi és réti talajtípusok is megtalálhatók. Határának Pótharaszt­puszta felőli peremén (a Vajkó, a Kanászlapos stb. tájrészeken) kellemes kirándulóhelyek terülnek el.'),
    ('Kalaznó', 'A Tolnai-Hegyhát területén helyezkedik el, Hőgyésztől 6 kilométerre keletre. A közvetlenül határos települések: észak felől Szakadát, északkelet felől Varsád, délkelet felől Felsőnána, dél-délkelet felől Murga, nyugat felől Hőgyész, északnyugat felől pedig Diósberény. Csak nagyon kevés híja van annak, hogy nem határos dél felől még Tevellel is. Zsáktelepülés, csak közúton érhető el, a 65-ös főútról Hőgyész déli szélén kiágazó 63 127-es számú mellékúton.'),
    ('Kallósd', 'Kallósd a Zalai-dombság keleti vonulatán, a Zalától kissé nyugatra helyezkedik el. Almásházával és Bezeréddel földutak kötik össze. A településre Zalaszentgrótról jár pár busz, melyek közül kettő Keszthely irányába továbbközlekedik. A falu legjelentősebb vízfolyása a Kallósdi-patak. Kallósd első említése 1217-ből való a zalai vár földjeként. Temploma is ebben az időszakban készült.'),
    ('Kalocsa', 'Jelentős történelmi múltra tekint vissza Kalocsa, hiszen a honfoglalás óta város, István király óta a magyarság egyik kiemelkedő kulturális központja. A város egyike a négy magyarországi római katolikus érseki székhelynek, az államalapítás óta a magyar katolicizmus második központja. Híres iskolaváros, a 18. századtól meginduló oktatás az egyik legkiválóbb iskolai központtá tette a várost országos szinten helyezkedik el.'),
    ('Kamond', 'Két eredetileg különálló településrésze Nagykamond és az attól északra fekvő Kiskamond, mára a két községrész belterületei gyakorlatilag összeértek. A szomszédos települések: észak felől Nagypirit, kelet felől Kerta, délkelet felől Kisberzseny, dél felől Zalaszegvár, délnyugat felől Karakó, nyugat felől Kemenespálfa, északnyugat felől pedig Boba.'),
    ('Kamut', 'Békéscsabától északnyugatra, Murony, Mezőberény és Mezőmegyer közt helyezkedik el. Kamut nevét már az Árpád-korban említették az oklevelek és a 12. században már templommal rendelkezett. A mai Kamut határában, (tőle DNy-ra és ÉNy-ra), két Árpád-kori templom maradványa is előkerült.'),
    ('Kapolcs', 'Vigántpetend, Monostorapáti és Taliándörögd. A településen vélhetően már ősemberek is éltek (Kapolcsi Pokol-lik), a falu felett emelkedő Királykő szikla fölötti területen pedig – a helyi legenda szerint – Attila egyik vára állhatott.'),
    ('Kapoly', 'A déli szomszédságában fekvő településekkel a Szorosadtól idáig húzódó 6516-os út kapcsolja össze. Kapoly neve először a III. Béla király által a székesfehérvári János lovagok részére kiállított megerősítő levélben fordult elő. Nevének változatai: 1337-ben Keethkapul alakban írták, 1347-ben Egyházaskapoly, 1400-ban Kápolnáskapoly néven szerepelt. 1229-ben a székesfehérvári káptalan birtoka volt, de az 1267 évi pápai bulla szerint a tihanyi apátságnak is voltak itt birtokai.'),
    ('Kaposfő', 'A község nyugati szélétől ágazik ki a 61-esből a zsákfalunak tekinthető Kisasszond központjába a 66 163-as út. A község földrajzi fekvése gazdasági szempontból kedvező. Talaja a Kapos folyótól északra barna erdei talaj, délre pedig szürke erdei talaj, futóhomokkal keverve. Területe általában síkság, csak az északi részen emelkednek alacsonyabb dombok.'),
    ('Kaposgyarmat', 'Kaposvártól 18 kilométerre délkeletre, a Zselicben található. Kaposgyarmat, előbbi nevén Gyarmat nevét 1296-ban említették először, ekkor a Győr nemzetségbeli I. Ders fia, Ders, vásárolta meg. Az 1660. évi dézsmaváltságjegyzék szerint Imrefy Farkasné volt a birtokosa. 1715-ben gróf Esterházy József birtoka volt és csak 3 háztartást találtak itt. 1726-ban pedig már a herczeg Esterházy-féle hitbizományhoz tartozott.'),
    ('Kaposhomok', 'Kaposvártól 12 kilométerre keletre található, a Kapos jobb parti oldalán. Bár aránylag távol fekszik a Balaton déli partjától, szőlő- és borgazdasági szempontból mégis a Balatonboglári borvidék részét képezi. A közvetlenül határos települések: északkelet felől Baté, délkelet felől Kaposkeresztúr, délnyugat felől Szentbalázs, északnyugat felől pedig Taszár.'),
    ('Kaposkeresztúr', 'Kaposvártól keletre fekszik, légvonalban 13, közúton 17 kilométerre. A közvetlenül határos települések: észak felől Baté, északkelet felől Mosdós, délkelet felől Gödre (Kiskeresztúr), délnyugat felől Hajmás, nyugat felől Szentbalázs, északnyugat felől pedig Kaposhomok. Bár nincs túl közel a Balaton déli partjához, a település szőlő- és borgazdasági szempontból mégis a Balatonboglári borvidék részét képezi.'),
    ('Kaposmérő', 'Belterületének déli szélén húzódik a Kapos folyó, azon túl a zselici dombok szép környezete határolja. A falutól északra sík vidéket találunk. A közvetlenül határos települések: észak felől Hetes, északkelet felől Juta, kelet felől Kaposújlak, délkelet felől Kaposszerdahely, dél felől Szenna, délnyugat felől Bárdudvarnok, nyugat felől pedig Kaposfő.'),
    ('Kaposszerdahely', 'Két újabb településrész, a Kisszennai és a Szent István lakótelep a völgyre néző dombokon épült. Kaposszerdahely története 1230-ig nyúlik vissza, amikor is a Monoszló nemzetség fejének, Makariás ispánnak fia, Tamás vásártartási jogot kapott a szerdai napokra Ropoly vára alatt. 1245-ben az emiatt már Szerdahelynek nevezett falut a Dersfiek vásárolták meg, 1332-ben pedig már temploma és plébániája is volt.'),
    ('Kaposvár', 'A Dunántúl egyik legfontosabb gazdasági, kulturális, oktatási és sportközpontja, egyetemi város. A Kapos folyó mentén, a Somogyi-dombság területén fekszik. Körülbelül 60 000 fős lakosságával az ország tizenötödik és a Dél-Dunántúl második legnépesebb települése.'),
    ('Kaposújlak', 'A megyeszékhelytől alig 5 kilométerre található falut a Kapos folyó szeli ketté. Déli részén emelkedik a Zselic, amelynek erősen agyagos földjét erdők és szőlők borítják. Négy falurészből áll: a legrégebbi az úgynevezett belső falu, a második a község melletti dombon található Szarkavár, mely a nevét feltehetően a korábban itt állt Szarkaberki településről kaphatta.'),
    ('Kapuvár', 'A megye negyedik legnépesebb települése. Neve az egykori nyugati gyepűrendszer megerősített, védett átjárójára, kapujára utal. Sokáig Kapunak mondták. A Kapuvár szóhasználat csak a 17. századtól terjed, és igazán általánossá a 18. században vált. A Kisalföldön, a Győri-medence nyugati csücskében, két kistáj – a Rábaköz és a Hanság – találkozásánál fekszik.'),
    ('Karakó', 'A megye délkeleti szélén fekszik, a Marcal-medencében, a Marcal bal (nyugati) parti oldalán, a Torna-pataknak a folyóba való betorkollása közelében. Délnyugat felől a legközelebbi település Keléd, de közigazgatási területeik (kevés híján) nem érintkeznek. A legközelebbi város Jánosháza, alig 3 kilométerre helyezkedik el.'),
    ('Karakószörcsök', 'A közvetlenül határos települések: észak felől Kerta, északkelet felől Iszkáz, délkelet felől Tüskevár, dél felől Apácatorna, délnyugat felől Veszprémgalsa, nyugat felől pedig Kisberzseny. Először 1288-ban tűnt fel Zurchuk írásmóddal, később – 1426-ban – már Karakozurchek. Először királynéi birtokként szerepelt, majd kisebb nemesek birtokolták. Az egytelkes kisnemesek 1488-ban négy forint országos adót fizettek.'),
    ('Karancsalja', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Karancsalja a Litke és Salgótarján közt húzódó 2206-os számú úton érhető el a legegyszerűbben, a megyeszékhely felől számítva az első település. A Dobroda-patak völgyében fekvő Karancsalja Árpád-kori eredetű település. Nevét a községtől néhány kilométerre északkeletre, Szlovákia és Magyarország határán magasodó 727 méter magas Karancsról kapta, amit a „Palóc Olimposznak” is szokás nevezni.'),
    ('Karancsberény', 'A karancsi dombok között, a 336 méter magas Bodoló-hegy alatt található, két kis patak találkozásánál. A megyeszékhelytől, Salgótarjántól 13 kilométerre északnyugatra fekszik, a szlovák határ mellett terül el, gyönyörű környezetben. A Novohrad-Nógrád UNESCO Globális Geopark települése. A határ magyar oldalon csak két szomszédja van: dél felől Karancslapujtő, délnyugat felől pedig Karancskeszi, a szlovák oldalon viszont feltehetőleg négy településsel is határos.'),
    ('Karancskeszi', 'Salgótarjántól nyugatra fekszik, Karancslapujtő és Egyházasgerge között. Főutcája a 2205-ös utat és a 21-es főutat összekötő, Litke és Salgótarján között húzódó 2206-os út, a két végponti település közül Litkétől körülbelül 10, a megyeszékhelytől 12 kilométerre található. Karancskeszi a Novohrad-Nógrád UNESCO Globális Geopark települése. Karancskeszi (Keszi) Árpád-kori település.'),
    ('Karancslapujtő', 'Kizárólag közúton közelíthető meg. A falutól északkeletre emelkedik a 725 méter magas Karancs. A Novohrad-Nógrád UNESCO Globális Geopark települése. A megyeszékhelytől, Salgótarjántól légvonalban 9 kilométerre északnyugatra fekszik, ahonnan autóval a Litkére vezető, a Karancs lábánál futó 2206-os úton közelíthető meg. A szomszédos települések északon Karancsberény, nyugaton Karancskeszi, délen Etes, délkeleten pedig Karancsalja, rajtuk kívül Karancslapujtő közigazgatási területe keleten határos Salgótarjánnal is.'),
    ('Karancsság', 'Salgótarjántól északnyugatra, Szalmatercs, Ságújfalu, Karancskeszi és Nógrádmegyer közt fekszik. Északkelet felől a Karancs hegység, délről a Cserhát vonulatai szegélyezik. A Novohrad-Nógrád UNESCO Globális Geopark települése. Karancsság és környéke már a honfoglalás előtt is lakott hely volt, ezt bizonyítják az itt talált különböző, a földből előkerült használati tárgyak is.'),
    ('Karcag', 'A település nevét a karcagi származású Németh Gyula turkológus-nyelvész fejtette meg 1922-ben helyezkedik el. A név eredetijét adó szó – qarssaq – eszerint török eredetű, eredetileg pusztai rókát jelentett. A napjainkban is használt településnév egytagú személynév eredetű földrajzi név. A település valószínűleg az egykori azonos nevű tulajdonosáról kapta a nevét, aki 1330 körül még élhetett.'),
    ('Karcsa', 'A Bodrogközben fekszik, a szlovák határ mentén, Miskolctól mintegy 90 kilométerre északkeletre. A térséget határoló nagy folyóvizek közül sem a Bodroggal, sem a Tiszával nem érintkezik, átszeli viszont a Karcsa, amely egykor még hajózható folyónak számított, de ma már inkább csak csatornaként kanyarog a környéken. Különálló településrésze Becsked, a központjától bő másfél kilométerre északnyugatra helyezkedik el.'),
    ('Kardoskút', 'A szomszédos települések: észak felől Orosháza, délkelet felől Tótkomlós, délnyugat felől Békéssámson, nyugat felől pedig Székkutas. Keleti határszélén egy pontban érintkezik a közigazgatási területe Pusztaföldvárral is. Legfontosabb turisztikai vonzereje, a Körös–Maros Nemzeti Park egyik legértékesebb részének számító Kardoskúti Fehér-tó a község délnyugati határszéle közelében található.'),
    ('Karmacs', 'Az előbbi útból itt ágazik ki keleti irányban a Vindornyafokra vezető 73 163-as út, illetve nyugat felé a Zalaszentlászlón át Zalaszentgrótig húzódó 7336-os út. Autóbusszal leginkább Keszthely felől érhető el, de Zalaszentgrót, Sümeg és Szombathely felől is több járat közlekedik a településre. Karmacs a 13. században létrejött település, amely ekkor két jól elkülöníthető részből, a nemesi Kiskarmacsból és a várnépek (később jobbágyok) által lakott, később Nagykarmacsnak nevezett településrészből állt.'),
    ('Karos', 'A Bodrogközben fekszik, a szlovák határ mentén. A környező települések közül Karcsa 5 kilométerre keletre, Bodroghalom mintegy 8 kilométerre délnyugatra, Alsóberecki 7 kilométerre nyugatra, Felsőberecki pedig 10 kilométerre északnyugatra fekszik. Pácin és Vajdácska ugyancsak mintegy 8-8 kilométerre található (előbbi keleti, utóbbi nyugati irányban), de e két település már nem szomszédos Karossal.'),
    ('Kartal', 'A megye északkeleti határán fekszik, Budapesttől mintegy 40 kilométerre északkeletre. Két magyar nagytáj, az Alföld és az Északi-középhegység határa mentén helyezkedik el. A közvetlenül határos települések: észak felől Verseg, kelet felől Kerekharaszt, délkelet felől Galgahévíz, dél felől Hévízgyörk, délnyugat felől Aszód, északnyugat felől pedig Kálló.'),
    ('Karácsond', 'Gyöngyöstől 10 kilométerre található. Északi része a Mátra déli lejtőjére épült, míg déli része már az Alföld északi szélén, a Gyöngyösi-sík táhegységben fekszik. Földje ennek megfelelően csodálatos értékeket rejt. Északi részén, a tűzhányók láva talaján tüzes, kiváló szőlő terem, a déli, alföldi része pedig a gabona és mezőgazdasági termények számára nyújt optimális feltételeket.'),
    ('Karád', 'A községhez a legközelebbi városok Tab és Balatonlelle. Karád a balatoni régió háttértelepülése, a Balatonboglári borvidék részét képezi. A legújabb régészeti és történeti kutatások alapján Karád már Árpád fejedelem idején lakott volt. Erre bizonyíték a település „fekete” jelentésű kara török szóból származó neve. Karád és vidéke, feltehetően 948 után, már a bizánci érdekszférához tartozhatott.'),
    ('Kaskantyú', 'A Kiskunsági-homokháton fekszik. A települési szomszédai: észak felől Páhi, északkelet felől Orgovány, délkelet felől Bócsa, dél felől Soltvadkert, délnyugat felől Kiskőrös, nyugat felől pedig Tabdi. A qaçqınçıɣ szóból származik, ami azt jelenti, "mint egy szökevény".'),
    ('Kastélyosdombó', 'A Dráva völgyében, Barcstól keletre, Darány és Potony közt fekvő település. A térség legnagyobb városa, Pécs felől Szigetváron és Darányon át közelíthető meg a legegyszerűbben helyezkedik el. A somogyi megyeszékhely, Kaposvár felől pedig ugyancsak Szigetvár érintésével. Keresztülszeli a települést az EuroVelo nemzetközi kerékpárút-hálózat 13. számú, „Vasfüggöny” útvonalának horvát–magyar határ menti szakasza, amelynek a Drávatamási és Drávasztára közti 3. számú etapja érinti a falut.'),
    ('Kaszaper', 'Orosháza délkeleti vonzáskörzetében fekszik, a város és Mezőkovácsháza között, utóbbihoz közelebb. Szomszédai: észak-északkelet felől Csanádapáca, kelet felől Nagybánhegyes, délkelet felől Mezőkovácsháza, dél-délkelet felől Végegyháza, délnyugat felől Tótkomlós, északnyugat felé pedig Pusztaföldvár. Exklávé jellegű településrésze a belterületétől 4, nyugati határszélétől körülbelül 3 kilométerre fekvő Pusztaszőlős, aminek területét minden irányból tótkomlósi külterületek fogják közre.'),
    ('Kaszó', 'Az erdőkkel teljesen körülvett település ma leginkább vadászati lehetőségeiről ismert, valamint kisvasútjának, játszótereinek és tanösvényeinek köszönhetően különösen a kisgyermekes családok számára kedvelt turisztikai célpont. Népszerűségét nagyban köszönheti a környező erdők bőséges vadállományának, amely miatt a vidék Magyarország egyik legjobb minőségű vadászterületének számít.'),
    ('Katafa', 'Körmendtől 5 kilométerre délkeletre fekszik, a Vasi-Hegyhát tájegységben. A környező települések: észak felől Körmend, kelet felől Nagymizdó, délkelet felől Hegyhátsál, nyugat felől pedig Nádasd. Belterületén ma a 7445-ös út halad végig helyezkedik el. A település első ismert okleveles említése 1230-ból származik. Határában emelkedik a Várdomb, ahol régészek római kori leleteket találtak.'),
    ('Katymár', 'A szerbiai határ menti település az észak-bácskai löszhát és a Duna–Tisza közi homokbuckák találkozásánál fekszik, Bajától délkeleti irányban. Határában folyik a Kígyós-főcsatorna. Régen elérhető volt a Kiskunhalas-Bácsalmás-Regőce vasútvonalon is, de azon a vonalon a forgalmat 1960. november 1-jén beszüntették, a pályát pedig Bácsalmástól kezdve felszedték.'),
    ('Katádfa', 'A Botykapeterdi-árok, a Halas-árok és a Sebes-víz partján fekszik, Szigetvártól légvonalban kevesebb mint 7, közúton azonban mintegy 10 kilométerre délkeletre. A szomszédos Bánfa község mindössze 1 kilométerre keletre, Dencsháza 3 kilométerre nyugatra, Rózsafa 4 kilométerre északra, Nagypeterd 6 kilométerre északra fekszik a településtől. Neve a Kata személynévből és a falva szó összetételéből ered, eredetileg Katátfalva formában szerepelt, de ez a névváltozat idővel Katádfára módosult.'),
    ('Kazincbarcika', 'Miskolc és Ózd után a megye harmadik legnagyobb települése. Várossá növekedését a második világháború után megindult iparosodásnak köszönheti. Elődjei ipari jellegű települések, Sajókazinc bányászfalu és az 1920-as évek óta erőműnek otthont adó Barcika. Az 1947-ben összevont két település mai nevét a rákövetkező évben vette fel. 1954-ben városi rangot kapott és újabb falut csatoltak hozzá, Berentét.'),
    ('Kazsok', 'Kaposvártól északkeletre, Igal, Büssü, Magyaratád és Somogyszil között fekszik, központján a Batétól Igalig húzódó 6503-as út vezet keresztül. Kazsok Árpád-kori település. Nevét már 1244-ben említette oklevél Kosok írásmóddal. 1272-ben Kosuk alakban fordult elő és a nyúlszigeti apáczák birtoka volt. 1331-ben már plébániája is volt, és neve szerepelt az 1332-1337. évi pápai tizedjegyzékben is. 1449-ben Hunyadi János kormányzó, 1453-ban pedig V.'),
    ('Kazár', 'A községet körülvevő hegyek, dombok geológiai szempontból egyidősek a Mátrával – húszmillió évesek. A Karancs–Medves térség földtani alapját képező oligo-miocén korú tengeri üledékek igen gyakran barnaszéntelepekkel gazdagítják a föld belsejét. Kazár legkülönlegesebb természeti adottsága a riolittufa, amely kb. 20 millió éve, a középső miocén korban keletkezett, tehát egyidős a Mátrával és a Karanccsal.'),
    ('Kecel', 'Kecel földrajzilag a Duna–Tisza közi homokhátságon, a Bugaci-homokháton helyezkedik el, illetve három történeti-néprajzi táj: a Kiskunság, a Bácska és a Kalocsai Sárköz találkozásánál fekszik. A szomszédos települések: észak felől Kiskőrös, északkelet felől Soltvadkert, délkelet felől Imrehegy, dél felől Császártöltés, délnyugat felől Homokmégy, nyugat felől pedig Öregcsertő.'),
    ('Kecskemét', 'Lakónépesség szerint a Dél-Alföldön a második és Magyarországon a nyolcadik legnagyobb, közigazgatási terület szerint Magyarországon a hetedik, a Dél-Alföldön a második legnagyobb település. Félúton fekszik a főváros Budapest és az ország harmadik legnagyobb települése, a Dél-Alföld központja, Szeged között, mindkettőtől 86 kilométerre. Ásatások során a régészek bronzkori urnákat találtak, emellett a piarista gimnázium építése során avar sírokat is fedeztek fel.'),
    ('Kecskéd', 'Kecskéd a Vértes lejtőinek és a Bársonyos dombvidék találkozásánál fekszik. A szomszédos Környe 4, Kömlőd 6, Tatabánya 11, míg Tata 17 kilométer távolságra található a falutól. A legközelebbi város Oroszlány, amely 5 kilométerre található. Határszélét érinti még a 8143-as út is. Keleti határában fekszik egy kisgépes repülőtér (ICAO-kód: LHKD), amelynek jelenlegi üzembentartója a Tatabányai Oldtimer Aero Club.'),
    ('Kehidakustány', 'A nyugati oldalon Kehida, a keletin pedig Kustány községrész helyezkedik el. Országos közútként számozódik még a település két belső útja (7356-os, 7357-es), a falu két része között az előbbi út hídja biztosítja az átkelést. A Kehidakustány elnevezés a korábban önálló két település Kehida és Kustány összevonásával alakult ki.'),
    ('Kelebia', 'Vasútállomása határátkelőhely Magyarország és Szerbia között. Kecskeméttől mintegy 110 kilométerre található. A két legközelebbi város a nyugat felől szomszédos Tompa és a déli irányban mindössze 12 kilométerre lévő, de már a határ szerbiai oldalán található Szabadka. A térség nagyobb városai közül Szeged 48 kilométerre keletre, Baja hasonló távolságban nyugatra, Kiskunhalas 28 kilométerre északnyugatra, Bácsalmás 24 kilométerre délnyugatra található Kelebiától.'),
    ('Kelemér', 'A Sajó völgyétől északra, a Keleméri-patak völgyében terül el Putnoktól 9, Miskolctól közúton 51 kilométerre. A környező települések: Alsószuha 8 kilométer-re, Gömörszőlős 2 kilométer-re, Serényfalva 6 kilométer-re, Szuhafő 10 kilométer-re, Zádorfalva 5 kilométer-re. A legközelebbi város: Putnok 9 kilométer-re. A legközelebbi szlovákiai település Naprágy, 2 kilométer-re nyugatra helyezkedik el.'),
    ('Kelevíz', 'Ez a szócikk a településről szól, a kelevéz (kelevíz) nevű fegyverről lásd a lándzsa szócikket! Marcali déli szomszédságában helyezkedik el, a várostól mintegy 6 kilométerre. Kelevíz Árpád-kori település. Nevét 1273-ban Keleuez írásmóddal említette először oklevél, majd 1397-ben Keleuiz, 1417-ben Kelewyz alakban írták.'),
    ('Keléd', 'Keléd neve régi magyar személynévből származik. A névtípus és a régészeti leletek tanúsága alapján is Árpád-kori eredetű település. Az írott forrásokban a név csak igen későn, 1444-ben jelentkezik, idevaló nemes nevében. A török korig a környéken is birtokos köznemesi Kelédy családé. Az 1549. évi rovásadó jegyzékbe 3 kelédi jobbágyportát, 4 zsellért és 2 szolgát vettek fel.'),
    ('Kemecse', 'A környező települések közül Nyírbogdány 5, Vasmegyer 6,5, Nyírtura 7,5, Nagyhalász 9, Nyírpazony pedig 10,5 kilométer távolságra található. A közvetlen szomszédos települések, településrészek: észak felől Tiszarád, északkelet felől Vasmegyer, kelet felől Nyírbogdány, délkelet felől Nyírtura, dél felől Nyírpazony, délnyugat felől Nyíregyháza-Sóstóhegy, nyugat-délnyugat felől Kótaj, nyugat felől Nagyhalász-Homoktanya, északnyugat felől pedig Nagyhalász.'),
    ('Kemence', 'Az Ipoly völgyében, a Börzsöny északnyugati lábánál fekszik. Bernecebaráti, Tésa és Perőcsény települések határolják. A település első ismert írásos említése 1156-ból való. 1293-ban Cseszneki Miklós, Lőrinc és Szomor osztatlan birtoka volt. Egy 16. század eleji urbárium szerint a faluban 52 jobbágy és 10 zsellér élt. 16. század vége felé elnéptelenedik A 17. század elején visszatérnek lakói, és rohamos fejlődésnek indul a falu.'),
    ('Kemendollár', 'Helyi önkormányzata Pókaszepetken működik. Kemend és Ollár települések egyesítésével jött létre, mai neve a két településnév összevonásából keletkezett. Kemend neve a szláv eredetű kámeny (kő) szó magyar „d” képzővel ellátott változata lehet, az Ollár pedig valószínűleg francia eredetű személynévből származik .'),
    ('Kemeneshőgyész', 'A Marcal folyó bal partján, Magyargencs és Szergény közt fekszik. Kemeneshőgyész és környéke már a középkor előtt is lakott hely volt. Az itt folyó régészeti ásatások a falu külterületén még a középkorban elpusztult két település: Kagymat és Berhénd nyomait azonosították, de a külterületen számos, még fel nem tárt halomsír helyét is azonosította. nevét 1272-ben említette először oklevél. 1290-ben Erzsébet királyné adománylevele említette a falu nevét Hyulgyz néven helyezkedik el.'),
    ('Kemeneskápolna', 'A megyeszékhely, Szombathely mintegy 45 kilométerre, a legközelebbi város, Celldömölk körülbelül 10 kilométerre található. A szomszédos települések: északkelet felől Celldömölk, kelet felől Celldömölk-Izsákfa, dél felől Köcsk, nyugat felől Vásárosmiske, északnyugat felől pedig Mesteri. Közúton a legegyszerűbben Celldömölk felől érhető el, a 8433-as úton.'),
    ('Kemenesmagasi', 'Kemenesalja északi részén, a Marcal mellékének síkjában fekszik a csaknem ezer lakosú község. Területének nagyobb része jellegzetes Kemenes-vidéki síkság, mely többnyire mezőgazdasági művelés alatt áll. Csak délre, a Marcal folyó és a Cinca-patak találkozásának környékén levő rétek, és a Szergény felé eső határrészen emelkedő kicsiny vulkanikus dombok erdőfoltjai különülnek el a tájból.'),
    ('Kemenesmihályfa', 'Celldömölktől északnyugatra, Ostffyasszonyfa, Tokorcs és Kemenessömjén közt fekszik, utóbbival szinte teljesen összenőtt. A település és környéke már az újkőkor óta lakott helynek számított. Területéről a bronzkor, vaskor idejéből is kerültek elő leletek. A helyet először 1272-ben említették az oklevelekben, melyek két elpusztult faluról tudósítanak: Ol és Chep.'),
    ('Kemenespálfa', 'A község Pálfa és Martonfa egyesítésével jött létre. Martonfalva első említése 1457-ből származik. Később a Pálfalvay, Csáffordy, Martonfalvay családé. 1549-ben egytelkes nemeseké volt. Pálfalva későn, csak 1467-ben jelentkezik oklevélben, ekkor a Kelédi család tartott hozzá jogot. Később is köznemeseké volt. Az 1549. évi rovásadó-jegyzék szerint Pörös Péter, Demjéndi Sandrin, Páhy Pál és Szecsődy Osvát összesen 8 jobbágyportát, 5 zsellért, 1 pusztatelket, 2 allodiális telket és 3 szolgát birtokolt.…'),
    ('Kemenesszentmárton', 'A Kemenesalja északkeleti részén, a Cinca-patak mellett fekszik. Határa jellegzetes kemenesaljai hullámos síkság, mely szinte teljes egészében mezőgazdasági művelés alatt áll, bár találunk kisebb erdőfoltokat a falu nyugati és délkeleti határában is. A Cinca partjai mentén még néhol fellelhetők az egykori árterek növényzetének maradványai. Mellékága, a kicsiny Rőke ér felső szakaszánál, a Cser elsimuló lankái alatt vizenyős rétek borítják a felszínt.'),
    ('Kemenesszentpéter', 'A szomszédos települések: észak felől Rábasebes, kelet felől Egyházaskesző, dél felől Magyargencs, nyugat felől Pápoc, északnyugat felől pedig Vág. A település központján, annak főutcájaként végighúzódik a 8406-os út, ezen érhető el Pápa irányából, illetve nyugati szomszédai felől is.'),
    ('Kemenessömjén', 'Területének nagyobb része enyhén hullámos síkság, a Cinca-patak mellékén főként megművelt területekkel, rétekkel, amelyet északnyugatról szőlőhegyek szegélyeznek. A szomszédos települések: északkelet felől Vönöck, kelet felől Kemenesszentmárton, dél felől Celldömölk, nyugat felől Kemenesmihályfa, északnyugat felől pedig Csönge. Közigazgatási területe délkelet felől, egy rövid szakaszon érintkezik még Mersevát határával is.'),
    ('Kemestaródfa', 'A falu a Pinka és a Strém-patakok összefolyásánál fekszik Körmendtől 5 kilométerre nyugatra. Északról Vasalja, délről Csákánydoroszló határolja. Közvetlenül az osztrák határ mentén helyezkedik el. A mai település két, egykor önálló faluból, Kemesmálból és Taródfából egyesült 1939-ben helyezkedik el. Kemesmált 1409-ben Kemesmal, Taródfát 1418-ban Torlodfalua alakban említik először.'),
    ('Kemse', 'Sellyétől dél-délkeletre, Vajszlótól délnyugatra helyezkedik el. Központja mintegy 3,5 kilométerre van a Drávától és a déli országhatártól, de közigazgatási határa délen közel öt kilométer hosszan egybeesik a déli országhatárral. A szomszédos települések a határ magyar oldalán: észak felől Csányoszró, kelet felől Piskó, nyugat felől pedig Zaláta. Északkeleten egy egészen rövid szakaszon határos még Lúzsokkal is.'),
    ('Keménfa', 'A település a Zala folyó jobb partján, 150-200 méter magas észak-déli irányú dombok tövében fekszik. Keménfa gyönyörű természeti környezetben, Göcsej, az Őrség és a Hetés tájegységek találkozásánál található.'),
    ('Kenderes', 'Az Alföld szívében, a Szolnok-Túri síkon helyezkedik el, Szolnok és Debrecen között, de előbbihez lényegesen közelebb. Távolsága közúton Szolnoktól 38, Debrecentől 85, Budapesttől és Miskolctól 145, Szegedtől pedig 132 kilométer. A közvetlenül szomszédos települések: észak felől Kunhegyes, kelet felől Karcag, délkelet felől Kisújszállás, délnyugat felől Örményes, nyugat felől Fegyvernek, északnyugat felől pedig Tiszabő és Tiszagyenda.'),
    ('Kengyel', 'A települést keletről Kétpó és Mezőhék, délről Martfű, nyugatról Rákócziújfalu és Rákóczifalva, északról Szajol és Tiszatenyő határolja. Az autóbuszos közúti közösségi közlekedés szolgáltatója a Volánbusz. Az önkormányzat címe: 5083, Kengyel, Szabadság út 10., telefonszáma: (06) 56/583-400, faxszáma: (06) 56/583-409. E-mail címe: hivatal@kengyel.hu, hivatalos honlapja: www.kengyel.hu.'),
    ('Kenyeri', 'A szomszédos települések: észak felől Rábakecöl, északkelet felől Pápoc, délkelet felől Kemenesmagasi és Vönöck, dél felől Csönge, északnyugat felől pedig Nick. Közigazgatási területe délnyugati irányból, egészen rövid szakaszon, szinte pontszerűen érintkezik Uraiújfalu határszélével is. A Cser vidékén elhelyezkedő település első…'),
    ('Kenéz', 'A falu a Gyöngyös-sík délkeleti peremén, a Gyöngyös-patak mellett fekszik Szombathelytől 15 kilométerre keletre. Főutcája a 8443-as út, közúton csak ezen érhető el a megyeszékhely Szombathely és Ikervár felől is. Neve a szláv eredetű magyar kenéz tisztségnévből származik. 1237-ben villa Kyniz alakban szerepel, akkor említik plébániáját is. 1240-ben Terra Kyniz, 1284-ben Poss.'),
    ('Kenézlő', 'Közigazgatási területe szinte teljes egészében a Tisza és a Bodrog folyók által közrefogott kis tájegységben, a Bodrogközben helyezkedik el, de egy csekély, kevesebb, mint 20 hektárnyi terület hozzá tartozik a Tisza bal parti oldalán is. A környező települések közül Viss 3, Zalkod pedig 6 kilométerre található. A Tisza túlparti oldalán a legközelebbi községek Szabolcs, Balsa és Gávavencsellő (légvonalban egyaránt 7körülbelül 9 kilométerre).'),
    ('Kercaszomor', 'Kercaszomor a magyar-szlovén határon fekszik, Körmendtől 40 kilométerre, az Őrségben. A falu határában folyik a Kis-Kerka vagy más néven Kerca-patak. A mai település egy körülbelül 5 kilométer hosszú, egyutcás falu képét mutatja, mely eredetileg két különálló település volt: Kerca a község keletebbi, Szomoróc a nyugatabbi rész. A két legközelebbi település észak felé Bajánsenye, dél felé pedig Magyarszombatfa.'),
    ('Kercseliget', 'A déli határszélén található hármashatárpontot kopjafa is jelzi, ugyanott kilátó is létesült. Bár nincs túl közel a Balaton déli partjához, a település szőlőtermő területei mégis a Balatonboglári borvidék részét képezik. A közvetlenül határos települések: észak felől Csoma (Somogy) és Attala, északkelet felől Kapospula, kelet felől Jágónak (utóbbi három Tolna), dél felől Baranyajenő (Baranya), nyugat felől Nagyberki, északnyugat felől pedig Szabadi (utóbbi kettő ismét Somogy).'),
    ('Kerecsend', 'A község területét a Laskó-patak szeli ketté. Nevét írásban először egy pápai tizedjegyzék említi 1337-ben, Keresnuch írásmóddal. 1484-ben a Bakócz-graduále említi Kelechen alakban írva. A terület a egri püspöki birtokhoz tartozott. A török elől a lakosság 1556-ban elmenekült, az 1600-as években népesült be újra. 1687-ben teljesen elpusztult. 1731-ben német jobbágyokat telepítettek a faluba, később szlávok is jöttek a faluba.'),
    ('Kerecseny', 'A Kis-Balaton térségét a Principális-csatorna völgyével összekapcsoló, a 7522-es és 7527-es számú utakat összekötő 7525-ös út mentén fekszik, központja az abból dél felé kiágazó 75 126-os úton érhető el. Nevének eredetére többféle magyarázat is ismert. Az egyik személynévből eredezteti a keletkezését, a másik a szláv krecet szóból helyezkedik el. Miután a településnév írásképe a legkorábbi ismert említésétől fogva folyamatosan nagyon hasonlít a vadászsólyom jelentésű kerecsen névhez, nem lehet kizárni az abból való keletkezést sem.'),
    ('Kerekegyháza', 'Kecskeméttől mintegy 17 kilométerre nyugatra, Kunbaracstól 7,4 kilométerre délkeletre helyezkedik el. A szomszédos települések: észak felől Lajosmizse, kelet felől Kecskemét (Hetényegyháza), délkelet felől Ballószög, délnyugat felől Fülöpháza, nyugat felől Szabadszállás, északnyugat felől pedig Kunbaracs. A település a főutaktól kissé távolabb esik, csak mellékutakon érhető el.'),
    ('Kerekharaszt', 'A szomszédos települések: észak felől Heréd, északkelet felől Nagygombos (Hatvan része), kelet felől Hatvan, dél felől Tura, délnyugat felől Galgahévíz, nyugat felől pedig Kartal. Aszódtól mintegy 10 kilométer-re fekszik. Kerekharaszt 1947-ig nem volt önálló község.'),
    ('Kereki', 'A Balaton déli partjától 7 kilométerre délre, a Külső-Somogy dombvidékének északi peremén, a Köröshegyi-séd völgyében helyezkedik el, a Kaposvár–Szántód közötti 6505-ös út mentén. A völgy hossza körülbelül 15 kilométer, átlagos szélessége 300-400 méter, tengerszint feletti magassága 106 métertől a Gyugy-tető 312 méteres magasságáig terjed. A Malom-árok teraszához alkalmazkodva a Balatonföldvár-Andocsi-hát, a Balaton-árok húzódik a Jaba és a Kis-Koppány tábladarab közt.'),
    ('Kerepes', 'Keleti irányból a Gödöllői-dombság erdei veszik körbe, a környező dombok közt találjuk a 328 méteres Bolnokát. Igen sok régészeti lelőhelyet tártak fel itt, leleteik az újkőkortól kezdődnek. A Csörsz-árok egy szakasza a településtől északra húzódik. Első okleveles említése 1148-ban, „Kerepesi-rév”-ként (kerep: régi magyar szó. Jelentése: hajó, csónak).'),
    ('Keresztéte', 'Miskolctól közúton körülbelül 65 kilométerre északra található, a szlovák határtól kevesebb, mint 2,5 kilométer választja el. Zsákfalunak tekinthető, a központjába egyedül Szászfáról, a 2613-as útról letérve lehet eljutni, a Pamlényba vezető 26 124-es, majd az abból kiágazó 26 125-ös úton. Neve a szláv eredetű Krstata keresztnév magyar kiejtésű alakjának földrajzi névvé válásával keletkezett.'),
    ('Kerkabarabás', 'A Hetés területén fekszik, Lenti északi szomszédságában. Kelet felől szintén Lentihez tartozó külterületek határolják, és a várost leszámítva csak két további települési szomszédja van: észak felől Zalabaksa, délnyugat felől pedig Resznek. Kerkabarabás és a Kerka völgye már az újkőkorban is lakott hely volt, melyet a település közelében feltárt újkőkorból való.'),
    ('Kerkafalva', 'Önkormányzata Csesztregen működik. A település a Csesztreg–Bajánsenye közt húzódó, nemzetközi forgalmat is bonyolító 7416-os út mentén fekszik. Ez a településnév személynévből származik, a régi személynévadás egyik sajátossága volt a hét valamelyik napjáról való elnevezés. A másik községnév a szláv eredetű német népnevünkkel kapcsolatos, amelyet egykori német lakóiról kapott. 1379-ben említik „Pintekfalua” nevét, 1387-ben pedig „Nemetfalu”-ét.'),
    ('Kerkakutas', 'A Kerka és a falu határán keresztülfolyó Cupi-patak medre levágja a falut keletről határoló dombokat, összekötve ezt a területet a községtől délre kiszélesedő Lenti-síksággal. A Kerkafalvai Körjegyzőség legnagyobb lélekszámú települése. A szomszédos települések: keletről Kozmadombja, délről Csesztreg, nyugatról Alsószenterzsébet, északról pedig Kerkafalva.'),
    ('Kerkaszentkirály', 'Letenye és Lenti között fekszik, az előbbihez valamivel közelebb, az országhatár mentén, nem messze a magyar-horvát-szlovén hármas határtól, a Mura völgyében. A lakosok 86,88%-a római katolikusnak vallotta magát (11,3% nem nyilatkozott). 2022-ben a lakosság 93,3%-a vallotta magát magyarnak, 6,7% németnek, 3,1% egyéb, nem hazai nemzetiségűnek (3,6% nem nyilatkozott.'),
    ('Kerkateskánd', 'Kerkateskánd 1934-ben alakult Teskánd és Kerkatótfalu egyesítésével. Teskánd Árpád-kori település. Nevét már 1271-ben említették egy oklevélben Tuskand néven helyezkedik el. Neve valószínűleg a török eredetű Teskánd személynévből ered. Kerkatótfalu nevét a 15. században említette először oklevél. Az egymás mellett fekvő két falu története hasonló.'),
    ('Kerkáskápolna', 'Kerkáskápolna az Őrség történeti - néprajzi tájegység egyik települése. A Kerka kiszélesedő völgyében fekszik, ezért területe a többi őrségi településtől eltérően nagyrészt sík, illetve északi irányban enyhén emelkedő. Utóbbi innen egyenes vonalban folytatódik, egészen Őriszentpéter központjáig, de az a szakasz már csak számozatlan mezőgazdasági útként húzódik.'),
    ('Kerta', 'Szomszédai: észak felől Kiscsősz, kelet felől Iszkáz, dél felől Karakószörcsök, nyugat felől pedig Kamond. Közigazgatási területe északnyugaton érintkezik még Nagypirit és Kispirit határszélével is, de utóbbiak egyikével sincs közvetlen közúti kapcsolata. Kerta Árpád-kori település, nevét már 1272-ben említette oklevél Keercha, majd 1469-ben Kyrtha néven helyezkedik el.'),
    ('Kertészsziget', 'Északon a Berettyó-csatorna határolja. Települési szomszédai: északkelet felől Szerep, kelet felől Füzesgyarmat, dél felől Szeghalom, délnyugat felől Dévaványa, nyugat felől Ecsegfalva, északnyugat felől pedig Bucsa. A községhez tartozó tanyaközpontok: Görbesziget, Cserepes, Barnasziget és Akasztó. A település központja egyébként a 4206-os úttól néhány kilométerre délre esik, arról csak az oda leágazó, majd Szeghalom tanyavilága felé továbbvezető 4245-ös úton érhető el.'),
    ('Kerékteleki', 'A Kisalföld délkeleti részén, Kisbértől 9, Mezőörstől 10, legközelebbi szomszédjától, Bársonyostól pedig 3,5 kilométer távolságra található. Keréktelekit 1237-ben említik először az oklevelekben, Keregj alakban helyezkedik el. A nevében szereplő "telek" valószínűleg az elpusztult, üres "telek"-ké vált helyre utal. 1453-ban Kerekes Pál tatai várkapitány kapja királyi adományként Hunyadi Mátyás király-tól.'),
    ('Keszeg', 'Budapesttől kb. 45, Váctól 16 kilométerre fekszik. Keszeg nevének eredetéről biztosat nem tudunk. Egy elmélet szerint a feltételezett eredeti Kőszeg névalak a későbbiek folyamán, igazodás útján, Keszegre változott. Keszeg és környéke már a bronzkorban is lakott hely volt. A honfoglalás korában lakott településként "hadrendi szálláshely" lehetett, tehát a név honfoglalás kori "hadrendi név".'),
    ('Kesznyéten', 'Miskolctól közúton körülbelül 40 kilométerre délkeletre található. Közelében folyik a Sajóba a Takta patak és a Hernádból a Bőcs és Kesznyéten közti, az erőmű miatt létrehozott üzemvízcsatorna. Csak közúton közelíthető meg, nyugat felől, Kiscsécs érintésével a 3607-es, északról, Tiszalúc térsége felől a 3613-as úton, illetve Sajóörös érintésével, a 35-ös főútból Sajószögeden kiágazó 36 107-es számú mellékúton helyezkedik el.'),
    ('Keszthely', 'Bár már a római idők óta lakott hely, az első történelmi bizonyíték a település létezéséről egy 1247-es dokumentumból ismert. 1421-ben kapott mezővárosi címet. Későbbi története során igen sokat köszönhetett a Festetics családnak.'),
    ('Kesztölc', 'A Pilis-hegység Dorogi-medencére érkező délnyugati lejtőjén elhelyezkedő település. Budapesttől 39, Esztergomtól 9, Dorogtól 6 kilométer-re fekszik. A falu első okleveles említése 1075-ből való Kistelci alakban helyezkedik el. Géza király a garamszentbenedeki apátságnak adott itt 2 eke földet, 7 szőlőt, valamint 5 vincellért. 1333-ban az oklevelekben már mint az esztergomi káptalan faluját említik, s elhatárolják a szomszédos Nyirtől. 1512-ben ismét a garamszentbenedeki apátságot említik birtokosának.'),
    ('Keszü', 'A község Pécstől 5–7 kilométer-re délre-délnyugatra fekszik. A megyeszékhely közelsége mindig, de különösen a 20. század második felében alapvetően meghatározta Keszü sorsát, fejlődését vagy stagnálását, a lakosság életviszonyait, infrastrukturális ellátottságát, munkahelyét, óvodai, iskolai, kulturális és egészségügyi ellátottságát. Elmondható, hogy Keszü ma Pécsnek nemcsak szorosan vett vonzáskörzetéhez tartozik, hanem szinte részének tekinthető.'),
    ('Keszőhidegkút', 'Regöly-Szakály felé a 6318-as út vezet Keszőhidegkút irányából helyezkedik el. A falu házai a Tolnai-dombság egyik völgyében, lépcsőzetesen helyezkednek el. A falu az utcaneveket tekintve 3 (Petőfi, Kossuth, Fő) utcából áll, gyakorlatilag viszont elkülöníthető akár 5 utca is, melyek a domboldalon kanyarognak. Több (10-20) hideg vizű forrás ered itt és egy kis patak is keresztülfolyik a falun…'),
    ('Kevermes', 'Szomszédai: északkelet felől Lőkösháza – amely egyben a legközelebbi település is –, dél felől Dombegyház, délnyugat felől Kisdombegyház, nyugat felől Dombiratos, északnyugat felől pedig Nagykamarás. Délkelet felől a romániai Kürtöshöz és Kisiratoshoz tartozó külterületek határolják. A község déli részénél végzett ásatások alapján a környéket már a bronzkorban…'),
    ('Kilimán', 'Korábban vonattal elérhető volt a Szombathely–Nagykanizsa-vasútvonalon, de az alacsony utasforgalom miatt a 2010-es évek közepén a megálló megszűnt. Nevét az írásos forrásokban 1583-ban Kielmansiget, majd 1589-ben Kilmansiget néven említett palánkvárról kapta, amelyet a Kanizsa-patak (ma Principális-csatorna) mocsaras völgyének védelme céljából Andreas Kielman építtetett, aki 1577-től 1580-ig Kanizsa várának főkapitánya volt.'),
    ('Kimle', 'Kimle a Mosoni-Duna két partján fekszik, Mosonmagyaróvártól délkeletre mintegy 10 kilométer és Győrtől északnyugatra 30 kilométer távolságra. 1966-ban jött létre négy környékbeli település, Horvátkimle, Magyarkimle, Károlyháza és Novákpuszta egyesítetésével, a mai formájában pedig 2002-ben, Károlyháza kiválásával. Régészeti leletek bizonyítják, hogy a falu területe már évezredekkel a honfoglalás előtt lakott hely volt.'),
    ('Kincsesbánya', 'A móri körzethez tartozó községet a 3-3 kilométerre fekvő Iszkaszentgyörgy és Fehérvárcsurgó, illetve az 5 kilométerre fekvő Gúttamási zárja közre. Déli és nyugati irányból a Bakony váltakozó szintű hegyvonulatai, északról és keletről a Móri-árok határolják. A község centruma a 241 méter magas Szeghegy északkeleti lejtőjénél elhelyezkedő dombokra épült, váltakozó felszíne természeti szépséget kölcsönöz a több utcás, szórt településnek.'),
    ('Királd', 'Az Upponyi-hegység északi nyúlványaira épült, a Sajóba torkolló Királd-patak völgyében, Ózdtól 10 kilométerre keletre, Miskolctól közúton körülbelül 40 kilométerre északnyugatra. A környező települések közül Borsodbóta 4, Sajómercse 5, Sajóvelezd 7, Uppony pedig mintegy 8 kilométerre található. A legközelebbi város a körülbelül 8 kilométerre fekvő Putnok.'),
    ('Királyegyháza', 'A település 1940. május 31-én, Szentgálosiván ideiglenes néven jött létre Magyarszentiván, Vásárosszentgál és Gusztávműve puszta egyesülésével. Jelenlegi nevét 1941. március 13-án vette fel. A Mecsek és a Dráva közötti sík területen fekszik, közvetlenül Szentlőrinc délnyugati szomszédságában. A további szomszédos települések: észak felől Kacsóta, kelet felől Szabadszentkirály és Gerde, dél felől Magyartelek és Magyarmecske, délnyugat felől Gyöngyfa és Sumony, nyugat felől pedig Szentdénes.'),
    ('Királyhegyes', 'A Körös-Maros-közén fekszik. A legközelebbi város Makó, amelytől mintegy 10 kilométernyire található, de a környező települések szinte mindegyike ugyancsak hasonlóan hosszú, 8-10 kilométeres úttal érhető el innen. A község közigazgatási területe nyugaton és északon Makóval, északkeleten Csanádalbertivel határos, keleti szomszédja Csanádpalota, déli szomszédai pedig Magyarcsanád és Apátfalva.'),
    ('Királyszentistván', 'A Balaton-felvidéken, a Balatontól 6 kilométerre fekszik a Séd völgyében. A két legközelebbi várostól, Balatonfűzfőtől és Berhidától 7 kilométerre, illetve Veszprémtől 11 kilométer távolságra van. A települést körülölelő dombokról jó kilátás nyílik mind a Bakonyra, mind pedig a Balatonra helyezkedik el. Már a római időkben lakott volt, melyet római villamaradványok tanúsítanak.'),
    ('Kisapostag', 'Belterületének déli széle lényegében egybeépült Baracs Üdülőtelep nevű településrészével, de közigazgatásilag nem tartoznak össze. A területen már a bronzkorban is éltek emberek, akik az itt talált kerámiaedények után a kisapostagi kultúra nevet kapták. Későbbi emlékek közé sorolható a két római őrtoronymaradvány, amelyeket a 6-os út építése közben találtak.'),
    ('Kisapáti', 'A Tapolcai-medencében, a Szent György-hegy keleti oldalánál fekszik, Tapolcától 5 kilométerre délkeletre. Főutcája a várost Nemesguláccsal összekötő 7345-ös út, ezen keresztül Badacsony és a környék más Balaton-parti települései is könnyen elérhetők innen helyezkedik el. Első írásos említése 1222-ből van (Apaty). A arra utal, hogy a település a pannonhalmi apátság tulajdona volt, a Kis előtag a közeli Monostorapátitól való megkülönböztetésül lehet a névben.'),
    ('Kisar', 'Szomszédai: észak felől Tivadar, kelet (és dél) felől Nagyar, délnyugat felől Nábrád és Kérsemjén, nyugat felől Panyola, északnyugat felől pedig Gulács. A legközelebbi város a 6 kilométerre délre fekvő Fehérgyarmat, a környék más fontosabb települései közül Nagyar 4, Tarpa 5, Szatmárcseke pedig mintegy 12 kilométer távolságra található. A megyeszékhely, Nyíregyháza körülbelül 80 kilométerre fekszik innen.'),
    ('Kisasszond', 'A Somogyi-dombságban, a Zselic határán fekszik. A legközelebbi város, Kaposvár 11 kilométerre északkeletre van. Első ismert írásos említése 1324-ből való, nevét ekkor Kusazwnd alakban írták. 1363–1456 között a Kanizsai család birtokolta. Az 1671. évi török kincstári adólistán Kisasszonyfalva néven szerepelt. A 18–19. században Sárközy család birtoka volt. 1798 őszén hosszabb ideig náluk vendégeskedett Csokonai Vitéz Mihály.'),
    ('Kisasszonyfa', 'A település Pécstől délnyugatra, Szentlőrinctől délre, Sellyétől északkeletre, az Ormánságban fekszik, Magyartelek és Téseny között. Közútkapcsolata a közvetlen szomszédai közül csak a tőle nyugatra fekvő, már említett Magyartelekkel, illetve a keletre elterülő Tésennyel van, az 5803-as úton keresztül. Északi és déli szomszédai, Gerde és Ózdfalu lényegében zsákfalvak, melyekkel Kisasszonyfát csak földutak kötik össze.'),
    ('Kisbabot', 'A községhez tartozik Andahely puszta. A Rába és a Marcal által közrefogott területen helyezkedik el, határszélét mindkét folyó érinti, de lakott területei a Rábához közelebb fekszenek. Első okleveles említése 1222-ből ismert, amikor Rouz fia Joachim volt az ura. 1262-ben IV. Béla Baboti Ajándok fiát, Szolnokot és ennek fiait, Andrást és Adorjánt erősíti meg itteni birtokukban, melyet villa Bobuth néven említ. 1534-ben I.'),
    ('Kisbajcs', 'A megye északkeleti részén fekszik, a megyeszékhely Győrtől mintegy 2 kilométerre északkeletre. Természetföldrajzilag a Szigetköz délkeleti szegletében helyezkedik el, ott, ahol a Mosoni-Duna és az Öreg-Duna már közelítenek egymáshoz. A két folyó áradásai az elmúlt évszázadokban sokszor akadályozták a falu határának művelését, de az itt élőknek a magas belvízszinttel is gyakran szembe kellett nézniük.'),
    ('Kisbajom', 'A település említésével az 1397-ből származó oklevélben találkozhatunk először, nevét akkor így írták le: Kysbayon. 1440-ben Zagorhida Tárnok Demeter adománybirtoka volt, 1536-ban Wárday Tamásé. Az 1554. évi török kincstári adójegyzékben Kisbája néven fordul elő, 6 adóköteles házzal. 1598-''99-ben Horváth Ferenc a földesura, 1926-''27-ben Koroknay Mihály, 1660-tól a Koroknay és Topos családok birtoka a község. 1703-ban és 1715-ben a Koroknayaké és ekkor 19 háztartást írtak össze.'),
    ('Kisberzseny', 'Devecsertől nyugatra, Jánosházától keletre fekszik, a Torna patak jobb partján, a Marcalba való betorkollása közelében. A közvetlenül határos települések: észak felől Kerta, északkelet felől Karakószörcsök, délkelet felől Veszprémgalsa, nyugat felől Zalaszegvár, északnyugat felől pedig Kamond. Kelet felől a legközelebbi település Apácatorna, de a közigazgatási területeik nem határosak.'),
    ('Kisberény', 'A település neve először az 1332-1337. évi pápai tizedjegyzékben fordult elő Beren alakban, mivel ekkor a somogyi főesperességnek már plébániája volt itt. Két évszázad múltán, 1536-ban két Kisberény került az adólajstromba. Az egyik Török Bálint birtoka volt, a másikon Peresznei Istvánné, Peresznei Egyed, Lengyel Boldizsár és a Szentmiklósi Pálos Rend osztoztak.'),
    ('Kisbeszterce', 'Pécstől légvonalban mintegy 22 kilométerre északnyugatra fekszik, Mindszentgodisa és Bakóca között. Zsáktelepülés, közúton csak egy útvonalon érhető el. Oklevél először 1542-ből említette Byztrice formában helyezkedik el. Az ősszláv szó értelme: gyors folyású patak. A Kis előtag arra utal, hogy létezhetett a környéken a múltban egy Nagy előtagú helységjelölés is.'),
    ('Kisbodak', 'A település a Szigetköz középső harmadában, a Duna jobb partján található, Győrtől mintegy 30 kilométerre nyugatra, Mosonmagyaróvártól pedig nagyjából 15 kilométerre keletre fekszik. Szájhagyományok szerint az „Ezer-szigetek” egyik akkori magaslatán épült Bodak vagy Bodajk nevű halásztelep, amely szláv eredetű neve után ítélve nádasos, sásos, vízinövényekkel telített, mocsaras hely lehetett.'),
    ('Kisbucsa', 'A Zalai-dombságban, ezen belül az Egerszeg–Letenyei-dombság területén fekszik, a megyeszékhely Zalaegerszegtől 12 kilométerre keletre. A Szévíz-medence tőzegkincset rejt, melynek kitermelése jelenleg is folyik. A bányaterület vízi világában számos növény- és állatfaj honos. A homokbányában a Pannon-tenger üledékének maradványai lelhetők fel.'),
    ('Kisbudmér', 'Villánytól északra, Bólytól délnyugatra fekszik. A szomszédos települések: észak felől Nagybudmér, északkelet felől Borjád, kelet felől Pócsa, dél felől Kisjakabfalva, nyugat felől pedig Ivánbattyán helyezkedik el. A szomszédai közül, Borjádon felül csak Nagybudmérral van közúti kapcsolata. Az oklevelek 1285-ben említették először, Budmer néven helyezkedik el.'),
    ('Kisbágyon', 'A Cserhát délkeleti szélén fekszik, a Bujáki-patak völgyében. A legközelebbi városok Pásztó és Hatvan helyezkedik el. Árpád-kori település, a Szolnok nemzetség ősi birtoka volt. Nevét az oklevelek 1260-ban említették először, amikor e nemzetség tagjai megosztoztak birtokaikon, de e birtokok a 13. század végén lassanként más kezekbe kerültek. 1309-ben Guthai Pál vett itt birtokrészeket.'),
    ('Kisbárapáti', 'A Dunántúli-dombság Somogyi-dombságában fekszik, a Koppány folyó mellett. A megyeszékhelytől, Kaposvártól körülbelül 40 kilométerre északra, Balatonföldvártól is nagyjából ugyanekkor távolságra, délre helyezkedik el. Szomszédos települések: Fiad és Bonnya. A község több hajdani települése nyomát őrzi határában: az egyik Gyiszmó néven szerepelt, már az 1055-ös tihanyi alapítólevélben. 1267-ben a Szentszék ezt a birtokot Gyesznó vagy Apáti néven erősítette meg a tihanyi apátság részére.'),
    ('Kisbárkány', 'A község nyugodt, tiszta levegőjű környezetben fekszik, a Cserhát keleti részén, Salgótarjántól délnyugati, Bátonyterenyétől nyugati irányban. A Novohrad-Nógrád UNESCO Globális Geopark települése. Lényegében zsáktelepülésnek tekinthető, hiszen csak az említett mellékútról Nagybárkánynál nyugat felé letérő 21 138-as számú úton érhető el, amely a település központját elhagyva már csak erdészeti útként vezet tovább.'),
    ('Kisbér', 'A Bakony és a Vértes között északnyugat-délkelet irányban, mintegy 50 kilométer hosszúságban elnyúló, több kilométer széles hasadékvölgy, a Móri-árok északi, Igmánd–Kisbéri-medencére nyíló végénél helyezkedik el. Nevezik a Bakony kapujának is. Közlekedésföldrajzi szempontból kulcsfontosságú területen fekszik. Kisbér közúton Székesfehérvártól 50, Győrtől 36, Tatabányától 35, Komáromtól 26, Pápától 50 kilométer távolságra fekszik.'),
    ('Kiscsehi', 'A település Lispeszentadorjántól délnyugatra, Budafától és Budafapusztától nyugatra, Szentmargitfalvától északra, Csörnyeföldtől északkeletre helyezkedik el, a Szentadorjáni-patak két oldalán. A település a Maróci-víztározótól délkeleti irányban fekszik. A település említése 1808-ban Csehi, 1902-ben Kiscsehi. A község Bázakerettye szomszédságában fekszik, a településhez tartozik Budafapuszta, annak szép arborétuma, a vadászkastéllyal és az olajos emlékművel.'),
    ('Kiscsécs', 'A Sajó partján fekszik, Miskolctól közúton körülbelül 30 kilométerre délkeletre. A környező települések Girincs és Kesznyéten, a legközelebbi város Tiszaújváros. Kiscsécset 1319-ben említik először, Chech alakban helyezkedik el. A török időkben elpusztult, csak a 17. században települt újra helyezkedik el. A lakók nagy része halászattal és mezőgazdasággal foglalkozott.'),
    ('Kiscsősz', 'Celldömölktől délkeletre, Csögle és Iszkáz közt fekszik. Központján, annak főutcájaként csak az Iszkáztól Csögle érintésével Külsővatig húzódó 8413-as út halad végig, ezen érhető el a két végponti település irányából. Közigazgatási határszéleit, délkeleti és északnyugati irányból érintik még a 8403-as, illetve a 8415-ös utak is, ezek azonban a lakott területeit messze elkerülik.'),
    ('Kisdobsza', 'A szomszédos települések: kelet felől Nagydobsza, dél felől Zádor, nyugat felől Istvándi, északnyugat felől pedig Kálmáncsa. Autóbusszal Szigetvárról, illetve a Pécs-Zalaegerszeg távolsági járatokkal érhető el. Első említése 1277-ben, királynéi birtok. A kora középkorban egy Dobsza állt. A török hódoltság idején folyamatosan lakott hely volt. A 17. században a magyar lakosság mellett délszlávok (horvátok) is megjelentek.'),
    ('Kisdorog', 'Külterületként hozzátartozik Juhépuszta, Lászlómajor, Ódánypuszta és Ördögmalompuszta is. A Dunántúli-dombság Völgység nevű tájegységében, a Mucsi-Hidas-patak völgyében fekszik. A megye középső-déli részén, a megyeszékhelytől, Szekszárdtól körülbelül 20, Bonyhádtól mintegy 15 kilométerre található. A szomszédos települések: Bonyhádvarasd, Nagyvejke, Tevel, Kéty, Zomba, Bonyhád-Tabód.'),
    ('Kisdér', 'Pécstől délkeletre, 20 kilométer-re terül el. Kisdér fennmaradt első írásos emlékei 1314-ből valók, másfél évtized múlva már possessióként – nagyobb faluként – tartják számon. Nevét ekkor Kwzdyrnek írták, és a pécsi káptalan birtoka volt. A török megszállás idején a Pestényi, az Őri-Dachol családnak voltak itt részbirtokai. 1550 után Bika Imre szigeti hadnagy és a kisasszonyfai Istvánffyak, majd utóbbiakkal kötött házasság révén a Draskovich grófok birtokába került a terület.'),
    ('Kisecset', 'Rétságtól keletre, a Cserhátban fekszik. Zsáktelepülésnek tekinthető, mert közúton csak a 2118-as útból Kétbodonyban kiágazó 21 154-es számú mellékúton érhető el. A 19. században a gróf Buttler család is birtokos volt Kisecseten.'),
    ('Kisfalud', 'Magyarország északnyugati részén, ezen belül a Rábaköz tájegység délnyugati részén helyezkedik el, Kapuvártól mintegy 10 kilométerre délkeletre. A Kis-Rába kettészeli a települést, majd elágazva annak egy részét szigetbe zárja. Földrajzi helyzetéből adódóan e folyó szabályozása előtt a művelhető földek vizenyősek, azaz növénytermesztésre kevésbé alkalmasak voltak.'),
    ('Kisfüzes', 'A község a Mátra lábánál fekszik, Pétervásárától 5 kilométerre délkeletre. A további szomszédos települések: kelet felől Bükkszék, délkelet felől Terpes, dél felől Szajla, délnyugat felől pedig Recsk. Észak felől Tarnaleleszhez tartozó külterületek határolják, de utóbbi település lakott területei távol esnek tőle, a közöttük közúton mérhető távolság több mint 12 kilométer.'),
    ('Kisgyalán', 'A mai helyén a község az 1700-as évek elején alakult ki, a határos községek: Büssü, Gölle, Fonó és Zimány. A falu határát északon a „Hársasi út”, keleten a „Nagyárok”, délen a Gázlói-víz, nyugaton a Kerekesi árok határolja. A falu határa lankás, dombos jó termő agyagos föld, ami meghatározza a lakosság foglalkozását. Gyalán Árpád-kori település. Nevét 1250-ben említette először oklevél a Szák nemzetség Gyaláni ágával kapcsolatban helyezkedik el.'),
    ('Kisgyőr', 'Miskolctól közúton 16 kilométerre délnyugatra fekszik, a Bükk-vidék déli részén. Lényegében zsáktelepülésnek tekinthető, közúton csak a Miskolc-Vatta közt húzódó 2515-ös útból kiágazó 25 117-es számú mellékúton érhető el. Kisgyőr már a bronzkor óta lakott, a leleteket a Herman Ottó Múzeum őrzi Miskolcon. A település neve a gyűrű alakú földvárak nevéből ered, melyekből több is állt a környéken.'),
    ('Kisgörbő', 'A falu első ismert említése 1274-ből való Vindornyaszőlős határtelepüléseként. Földje mindig is rosszul termett, ezért komolyabb település sokáig nem alakult ki. A 16. században kifejezetten szegény faluként említették a községet. 1635-ben már mint puszta szerepelt a feljegyzésekben helyezkedik el. Később újra megindult az élet a faluban, de továbbra is szegény jobbágyi és zselléri település maradt.'),
    ('Kishajmás', 'A Zselic északkeleti részén helyezkedik el, az Orfűi-patak völgyében, Pécstől északnyugatra, Sásdtól délre, Oroszló délnyugati szomszédjában. Különálló településrésze az 1979-ig önálló Szatina, amely Kishajmástól mintegy 2 kilométerre fekszik észak-északnyugati irányban. Szatina zsákfalunak tekinthető, csak egy alsóbbrendű, számozatlan önkormányzati úton érhető el a 6601-esről letérve.'),
    ('Kisharsány', 'Siklós keleti vonzáskörzetében helyezkedik el. A szomszédos települések: észak felől Palkonya, északkelet felől Villánykövesd, kelet felől Nagyharsány, délkelet felől Siklósnagyfalu, dél felől Egyházasharaszti, délnyugat felől Siklós, nyugat felől pedig Nagytótfalu. Harsány (Kis-) nevét az oklevelek 1235-ben már említették.'),
    ('Kishartyán', 'A település a Cserhát legészakibb vonulatai és a Karancs között fekszik, Salgótarjántól mintegy 10 kilométerre nyugatra. A Novohrad-Nógrád UNESCO Globális Geopark települése. A települést érintő helyközi autóbuszvonalakː 1010, 1012, 3072, 3075, 3080, 3081, 3082. A kisközség már a középkorban létezett. Az 1548. évi adóösszeírásban teljesen elpusztult helységként van felvéve. 1562-63-ban a török hódoltsághoz tartozott, a szécsényi szandzsák községei között.'),
    ('Kisherend', 'Siklós északi vonzáskörzetében fekszik. A szomszédos települések: kelet felől Peterd, délkelet felől Újpetre, délnyugat felől Vokány, északnyugat felől pedig Egerág. Kisherend és környéke már az ókorban is lakott hely volt, amit a területén fellelhető nagyszámú római korból származó lelet is bizonyít. Herend (Kisherend) nevét az oklevelek 1282-ben említik egy odavaló lakos nevében. 1330-ban nevét Herend néven írták, és Ormándi Miklós birtoka volt, aki mivel fiu utóda nem született, itteni birtokát 1289-ben vejére Deniper fia Istvánra hagyta.'),
    ('Kishuta', 'A Zempléni-hegység középső részén helyezkedik el, a megyeszékhely Miskolctól közúton mintegy 90 kilométerre északkeletre, Sátoraljaújhelytől 20 kilométerre nyugatra. A közvetlenül szomszédos települések: északkelet felől Pálháza, kelet felől Kovácsvágás, dél felől Nagyhuta, északnyugat felől pedig Bózsva. Közúton Pálháza nyugati része felől érhető el, a 3708-as útból kiágazó 37 125-ös számú mellékúton.'),
    ('Kishódos', 'Szomszédai a határ magyar oldalán: észak felől Kispalád, délkelet felől Nagyhódos, délnyugat felől Rozsály, nyugat felől Tisztaberek, északnyugat felől pedig Botpalád. Északkelet felől a legközelebbi település az ukrajnai Nagypalád (Велика Паладь). Legközelebbi szomszédja a kevesebb, mint 2 kilométerre lévő Nagyhódos. A környék más települései közül Garbolc 4, Kispalád 7, Botpalád 9, Magosliget 12, Uszka 15, Tiszabecs 19, Sonkád 8, Kölcse pedig 12 kilométer távolságra található.'),
    ('Kisigmánd', 'Az M1-es vonalvezetésével megegyezik a közigazgatási határvonala. A település elnevezése a birtokos család nevéből eredeztethető. Első okleveles említése 1440-1446 között ismert, Kyswygman, 1453-ban Kis-Wigman formában. A Kis-előtag Nagyigmándtól különbözteti meg. A jövevény Wigman nemzetség a 11. század elején kapott itt birtokot. Területén több római kori kőemlék került elő. 1935-ben kutatást végeztek a temetőben és a református…'),
    ('Kisjakabfalva', 'A Villányi-hegység északkeleti oldalán fekszik, Villánytól északnyugatra. A további szomszédos települések: észak felől Kisbudmér, északkelet felől Pócsa, délnyugat felől Villánykövesd, északnyugat felől pedig Ivánbattyán helyezkedik el. Kisbudmérral és Ivánbattyánnal alsóbbrendű, burkolatlan mellékutak kötik össze. A falut 1400-ban említették először az írott források Zent Jacabfalua néven, 1465-ben már Jakabfalwának írták nevét.'),
    ('Kiskassa', 'Pécstől dél-délkeletre, Villánytól északnyugatra fekszik, földrajzi értelemben a Mecsek és a Villányi-hegység közötti terület része. A szomszédos települések: észak felől Birján, északkelet felől Belvárdgyula, délkelet felől Nagybudmér, dél felől Ivánbattyán, délnyugat felől Palkonya és Újpetre, nyugat felől Pécsdevecser, északnyugat felől pedig Peterd.'),
    ('Kiskinizs', 'Miskolctól északkeletre fekszik, közúton körülbelül 25 kilométerre. A környező települések közül Halmaj és Hernádkércs 3-3, Nagykinizs 4, Felsődobsza és Szentistvánbaksa 6-6 kilométerre található. A két legközelebbi város a 12 kilométerre lévő Szikszó és a 16 kilométerre fekvő Abaújszántó. Csak közúton érhető el, Halmaj vagy Hernádkércs érintésével, a 3703-as úton.'),
    ('Kiskorpád', 'A közvetlenül határos települések: észak felől Somogysárd, kelet felől Kaposfő, délkelet felől Kisasszond, dél felől Gige, délnyugat felől Csököly, nyugat felől Jákó és Nagybajom, északnyugat felől pedig Pálmajor. Nevét Villa Curpad alakban írva említi először egy 1324-es oklevél. A néhány évvel későbbi pápai tizedjegyzék már helyi plébániáról tett említést.'),
    ('Kiskunhalas', 'A település a Kiskunság egyik központja, amely nemcsak természeti szépségeiről és alföldi hangulatáról, hanem híres kézimunkáiról, különösen a világhírű halasi csipkéről is ismert. A település története egészen az Árpád-korig nyúlik vissza, a környék természeti kincsei, például a Sóstó és a Kiskunsági Nemzeti Park részei pedig ideális helyszínt nyújtanak a természetkedvelők számára.'),
    ('Kiskunlacháza', 'A Csepeli-síkon, Budapesttől délre helyezkedik el, a Ráckevei-Duna balparti oldalán. A szomszédos települések: észak felől Áporka, északkelet felől Délegyháza, kelet felől Bugyi, délkelet felől Apaj, dél felől Dömsöd, délnyugat felől Ráckeve, északnyugat felől pedig Szigetszentmárton helyezkedik el. Utóbbi két település már a Ráckevei-Duna túlsó partján, a Csepel-szigeten helyezkedik el.'),
    ('Kiskunmajsa', 'A Duna–Tisza közi homokhátságon, a Dorozsma–Majsai-homokháton, Kiskunhalas és Kiskunfélegyháza között helyezkedik el, a Majsa-Fehértói Főcsatorna mellett. A várost a hazai főutak mind elkerülik, csak mellékutakon érhető el a környező települések felől. Korábban érintette a várost a kecskeméti kisvasút hálózatához…'),
    ('Kiskutas', 'A település nevét 1211-ben II. Fábiánnak három fia: Krejnik, Androcinus, és Máté 1264-ben osztoztak meg Kutason, Aracsán és Lovásziban levő birtokaikon. 1364-ben a Kutasi család tagjai Kutasi Kálóz fia, Pál fia János és fia Kálóz megegyeztek kutasi birtokaikkal kapcsolatban. 1371-ben Ákos mester és fiai Kutasiként vannak említve. Ákos fia László 1386-ban kelt végrendeletében Kutas felét a feleségére hagyta, míg másik felét unokahugának, Sárának, Mikcs özvegyének hagyta.'),
    ('Kisköre', 'A szomszédos települések: észak felől Kömlő, északkelet felől Tiszanána, délkelet felől Abádszalók, dél felől Tiszabura [utóbbi kettő a folyó túlpartján], nyugat felől Pély, északnyugat felől pedig Tarnaszentmiklós. Különálló, külterületi településrésze Rákhát, a központjától néhány kilométerre északnyugatra helyezkedik el.'),
    ('Kiskőrös', 'A település szlovák neve Malý Kereš, vagyis „kis kőrös”. Horvátul két neve létezik: a felsőszentiváni horvátok által használt Kireš, és a bátyai horvátok által használt Kereša. Ezen a vonalon Kiskőrös területén egy megálló is létezett, Remerenció…'),
    ('Kislippó', 'Villánytól délkeletre fekszik, a déli (horvát) országhatártól alig néhány kilométerre. A szomszédos települések: északkelet felől Lippó, kelet felől Ivándárda, dél felől Illocska, délnyugat felől Lapáncsa, nyugat felől Magyarbóly, északnyugat felől pedig Márok.'),
    ('Kisláng', 'A Mezőföldön, 5316 hektáros területen helyezkedik el. Külterületét érinti még a Lepsénytől Mezőszentgyörgyre, majd onnan egy darabig délebbre továbbvezető 63 105-ös út is. Korábbi zsáktelepülés jellege mára, az újabb utak építésével megszűnt. A községet mindenki csak úgy ismeri, hogy szabályos, mérnök által tervezett település. A kb. 1,6–2 kilométeres utcák középen merőlegesen metszik egymást.'),
    ('Kisléta', 'A Nyírség déli részén helyezkedik el, a megyeszékhely Nyíregyházától 32, a környező települések közül Nyírbogáttól és Máriapócstól egyaránt 6-6, Nyírbátortól 12, Nagykállótól pedig 18 kilométerre. Kislétát a 14. század elején már említette írásos forrás. Nevét az oklevelek 1322-ben említik először, a Hont-Pázmány nemzetségbeliek a Balog-Semjén nemzetség tagjait eltiltották itteni birtokuk használatától helyezkedik el.'),
    ('Kislőd', 'A Bakony lábainál fekszik, egy háromszög alakú völgyben. A közvetlenül határos települések: észak felől Farkasgyepű, északkelet felől Csehbánya, kelet felől Városlőd, délkelet felől Szentgál, dél felől Úrkút, délnyugat felől Ajka, nyugat felől Ajkarendek (Ajka településrésze), északnyugat felől pedig Magyarpolány. A települést először egy 1492-es oklevélben említik mint a lövöldi (városlődi) karthauziak birtokát.'),
    ('Kismarja', 'A településtől nem messze található a jelenlegi magyar–román határ. Természetföldrajzi szempontból a Bihari-sík északkeleti peremén, a Berettyó–Kálló köze szomszédságában fekszik. Szomszédos települések: Hencida, Pocsaj, Esztár, Nagykereki és Bojt. A falu határánál folyik a Berettyó folyó. Vámospércs–Létavértes felől Pocsajig a 4807-es, onnan szintén a 4808-as úton érhető el.'),
    ('Kismaros', 'A Dunakanyarban a Duna bal partján, Verőce és Nagymaros között elhelyezkedő település. Itt egyesül az északról (Szokolya felől) érkező Török-patak (más néven Morgó-patak) a keletről (Verőce-Magyarkút felől) érkező Morgó-patakkal (más néven Les-völgyi-patak vagy Gimpli-patak). A Dunába torkollik annak 1689-1690-es folyamkilométerénél helyezkedik el.'),
    ('Kismányok', 'A Mecsek lábánál fekszik, egy völgyben. Bonyhádtól 8 kilométerre délnyugatra helyezkedik el. Kismányokot egy 1437-ben kiadott kanonikus oklevél említi először az ismert források közül, akkor még Nagymányok pusztájaként, később vált önálló településsé. Az 1526-os mohácsi vész után mindkét település elpusztult, magyar lakosságuk elmenekült, Kismányokon tizenkét üres ház maradt hátra helyezkedik el.'),
    ('Kisnamény', 'Szomszédai: észak felől Vámosoroszi, északkelet felől Csaholc, kelet-északkelet felől Túrricse, délkelet felől Gacsály, dél felől Császló, délnyugat felől Jánkmajtis, nyugat felől pedig Darnó. A térség fontosabb települései közül Fehérgyarmat 17,5, Gacsály 8, Jánkmajtis pedig 3,5 kilométer távolságra található. Jánkmajtis keleti részével (Jánk településrésszel) a 4142-es, Csaholccal a 4144-es utak kötik össze.'),
    ('Kisnyárád', 'Lánycsóktól kb. 8 kilométer-re északnyugatra található. Kisnyárád nevét 1285 körül említik egy oklevélben helyezkedik el. A település ekkor a királyi tárnokok jobbágyainak a földje volt, és IV. László odaadta (Németi) Leunard fiainak. 1292-1297 körül egy oklevélben idevaló lakosa tanúskodásáról van szó. 1335-ben papja 8 báni pápai tizedet fizetett.'),
    ('Kisnána', 'A Mátraalján található a 2416-os és a 24 131-es utak találkozásánál. Közeli települések: Domoszló, Vécs, Verpelét. A fellelhető iratok alapján megállapítható, hogy Kisnána már a 11. században is lakott volt, sőt egyesek szerint már a honfoglalás előtt is éltek itt embercsoportok. Az, hogy az Aba nemzetséghez tartozó Kompolti család birtokába mikor került ez a terület, pontosan nem bizonyítható.'),
    ('Kisnémedi', 'Kisnémedi a fővárostól 40 kilométerre északkeletre terül el, a Cserhátalja és a Gödöllői-dombság találkozásánál, a Némedi-patak völgyében. A környék legmagasabb pontja a falutól északra fekvő, 325 méter magas Baglyas-hegy. A település közúton Váchartyán keleti része felől érhető el, a 2105-ös útból kiágazó 21 114-es számú mellékúton, melynek végpontja Püspökszilágyon van.'),
    ('Kisoroszi', 'A Dunakanyarban, a Visegrádi-szoros áttöréses völgyének végén, a Duna főága és a Szentendrei-Duna által közrefogott Szentendrei-szigeten helyezkedik el. A közkedvelt északnyugati szigetcsúcs körülbelül 5 kilométeres hosszban teljes egészében a település közigazgatási területéhez tartozik. Tahitótfalutól a szigeten végighúzódó 1113-as úton közelíthető meg, vagy pedig a Dunabogdány és Visegrád határvonalától (Szentgyörgypusztától) induló komppal.'),
    ('Kispalád', 'A megye keleti részén, az ukrán határ mellett fekszik. Szomszédai a határ magyar oldalán: észak felől Magosliget, dél felől Kishódos, nyugat felől pedig Botpalád. Kelet felől a legközelebbi település az ukrajnai Nagypalád. A környék fontosabb települései közül Tiszabecs 14, Kölcse 12, Sonkád 8, Botpalád 2 kilométer távolságra található. A településen végighalad, nagyjából dél-északi irányban (bár jó néhány irányváltással) a 4143-as út, közúton ezen érhető el a két végponti település, Gacsály és Tiszabecs felől is.'),
    ('Kispirit', 'A legközelebbi szomszéd falu, a nyugati határában elterülő Nagypirit mindössze fél kilométerre fekszik tőle. Határa – elhelyezkedéséből adódóan – túlnyomórészt sík, csak a dél felől érkező apró vízerek völgyei alakítottak ki kisebb hullámokat a felszínen helyezkedik el. Észak felé kiterjedt füves területeket találunk (Marcali-rétek), míg másfelé szántóföldek, dél-délkeleti irányban, kicsit távolabb erdők koszorúzzák a határt.'),
    ('Kispáli', 'A megyeszékhely, Zalaegerszeg északi szomszédságában helyezkedik el. A városon kívül csak három települési szomszédja van: kelet felől Nagypáli, nyugat felől Kiskutas, északnyugat felől pedig Nagykutas.'),
    ('Kisrozvágy', 'A Bodrogköz magyarországi részének északi peremén helyezkedik el, közvetlenül a szlovák határ mellett, a megye székhelyétől, Miskolctól közúton mintegy 90 kilométerre északkeletre. A szomszédos települések a határ magyar oldalán: kelet felől Semjén, délkelet felől Ricse, nyugat felől pedig Nagyrozvágy. Észak felől, a határ túloldalán a két legközelebbi település Nagygéres (Veľký Horeš) és Kisgéres (Malý Horeš).'),
    ('Kissikátor', 'Ózdtól közúton 15, Salgótarjántól 40, Miskolctól 75 kilométerre, a Hangony jobb oldali mellékvölgyében található. Környéke igen szép vidék, vadban gazdag, jelentős erdőállománnyal, ahol manapság medve is felbukkanhat. A település az Árpád-kor óta lakott, először 1379-ben említik. A török időkben elpusztult, nemcsak a törökdúlás, hanem természeti csapások miatt is, de újra benépesült.'),
    ('Kissomlyó', 'A település környékén a honfoglalás előtti időkben avar és szláv népek éltek. A terület az államalapítás után a karakói várispánsághoz tartozott. Nevét 1309-ben említette először oklevél Hegyesomlo, Hethysomlia és Hegesumlia alakban helyezkedik el. A mai Kissomlyó névalak a 15. századtól használt. Kissomlyó az Árpád-kor végén a Héder nemzetség birtoka volt, később pedig a Somogyi és az Erdődy családok lettek itt jelentősebb birtokosok, ugyanakkor középnemesek is éltek a faluban.'),
    ('Kisszekeres', 'Szomszédai: észak felől Fülesd, északkelet felől Vámosoroszi, délkelet felől Darnó, dél felől Jánkmajtis, délnyugat felől Nagyszekeres, északnyugat felől pedig Nemesborzova és Mánd. Legközelebbi szomszédja Nagyszekeres, amitől mindössze 2 kilométer választja el. A legközelebbi város, Fehérgyarmat 12 kilométerre fekszik. A térség más fontosabb települései közül Csengersimától 18, Tunyogmatolcstól 17, Mátészalkától pedig 27 kilométer távolságra található.'),
    ('Kisszentmárton', 'Az Ormánság középső-déli részén helyezkedik el. A szomszédos települések: észak felől Baranyahídvég, északkelet felől Sámod, nyugat felől pedig Hirics. A település az itt előkerült régészeti leletek szerint már az ókorban is lakott volt. Az apátság birtoklásának emlékét az 1883-as térképen még feltüntetett Apáti puszta őrzi.'),
    ('Kissziget', 'A települést a Cserta és a Kisszigeti-patak fogja közre helyezkedik el. A hajdani itteni mocsárvilág egy szigetszerű szárazulatán alakult ki. Két tektonikailag kijelölt süllyedék metszi egymást ebben a térségben helyezkedik el. Az egyik egy észak–déli irányú, jellegzetesen menedékes völgy, mely a Göcsej területét választja ketté: ebben folyik a Közép-Zala vizeit összegyűjtő Cserta.'),
    ('Kisszállás', 'Kisszállás a Duna–Tisza köze déli részén helyezkedik el, Kiskunhalastól 22 kilométerre délre. Közigazgatási területének kiterjedése 9206 hektár, melyből 485 hektár a belterület. A szomszédos települések: észak felől Balotaszállás, kelet felől Öttömös, délkelet felől Kelebia, dél felől Tompa, délnyugat felől Mélykút, nyugat felől Jánoshalma, északnyugat felől pedig Kunfehértó.'),
    ('Kisszékely', 'A Tolnai-Hegyhát vonulatában fekszik, erdővel borított dombok között. A közvetlenül határos települések: észak felől Simontornya, északkelet felől Pálfa, délkelet felől Sárszentlőrinc, dél felől Nagyszékely, északnyugat felől pedig Tolnanémedi. A legközelebbi városok Simontornya (12 kilométerre északra) és Tamási (27 kilométerre nyugat-délnyugati irányban).'),
    ('Kisszőlős', 'A település a Marcal-medencében, a Pápa–Devecseri-síkon, a Somló hegyétől 4 kilométerre északra fekszik, a Hajagos-patak bal partján. Hajdan a helység a mostani helyétől délnyugatra feküdt három dűlő távolságra, amely a „Keresztfa-rend” nevet kapta az ott fennállott feszületről. Később ez a határrész „Tikhegy” néven vált ismertté, ahol talajművelés során lakott településre utaló cserépdarabok kerültek felszínre.'),
    ('Kistamási', 'Szigetvár vonzáskörzetében helyezkedik el, a város központjától légvonalban mintegy 7, közúton 11 kilométerre délnyugati irányban. A szomszédos települések: észak felől Nemeske, északkelet felől Molvány, dél felől Gyöngyösmellék, délnyugat felől pedig Pettend. Csak közúton közelíthető meg, a 6-os főútról Nemeske-Görösgalnál letérve, az 58 109-es számú mellékúton (ez az út innen még továbbvezet Pettend központjáig).'),
    ('Kistapolca', 'Siklóstól délkeletre, a Villányi-hegységtől délre helyezkedik el. A térség településeihez mérten a közigazgatási területe aránylag kicsi, így csak három települési szomszédja van: észak felől Nagyharsány, délkelet felől Beremend, nyugat felől pedig Siklósnagyfalu. Nevének jelentése: az ősi szláv alapszóból meleg vizű forrás. Első okleveles említése 1294-ben Topolcha, ugyanaz a neve a már akkor is működő hévizes helynek is a település területén.'),
    ('Kistarcsa', 'Kistarcsa területén eddig kevés régészeti ásatást végeztek, pedig a jelek arra mutatnak, hogy lelőanyagban gazdag a környék. Legkorábbi leleteink újkőkorszakiak (Kr. e. 4000–2500), a feltárásokból pedig arra lehet következtetni, hogy később is mindig éltek itt emberek. A már nemzetiség szerint is azonosítható maradványok alapján lakóhelyet alakítottak…'),
    ('Kistelek', 'Miután a török feldúlta az ország középső területeit, szükség volt az újbóli betelepítésekre, és ennek következtében Szeged és Kiskunfélegyháza közé félúton kitelepítettek 100 családot a Kis-Telek-i pusztára, aminek a leszármazottjai többé-kevésbé ma is itt élnek. A nevezetes 20. hosszúsági kör (meridián) csak pár kilométerrel található keletebbre a település központját képező körforgalomtól.'),
    ('Kistokaj', 'A Hejő patak partján helyezkedik el, Miskolc központjától mintegy 9 kilométerre, Szirma városrésztől 4 kilométerre délre. További szomszédai: kelet felől Sajópetri, délnyugat felől pedig Mályi. Közvetlenül határos még délkelet felől Sajóláddal is, de utóbbinak csak lakatlan külterületeivel érintkezik, maga a település a Sajó túlsó partján fekszik. Bortermelő hely, szőlő- és borgazdasági szempontból a Bükki borvidékhez (korábbi nevén Bükkaljai borvidék) tartozik.'),
    ('Kistolmács', 'Nagykanizsától nyugatra, Letenyétől 7 kilométerre északra terül el, a Béci-patak völgyében. Minden oldalról erdők határolják. A községről az 1200-as évekből maradt fenn dokumentum, 1235-től ismeretes, mint Tolmach. 1235-ben a település a Bánffy családé. 1524-ben a helység telkeinek több mint a fele elhagyatott volt. 1664-ben Tolmács magyar falu lett. 1703-ban kettő család, majd 1778-ban már 286 család lakja a települést.'),
    ('Kistormás', 'Tolna megye középső részén fekszik, a Tolnai–Hegyhát dombjai közt, Szekszárdtól 28 kilométerre északnyugatra, Gyönktől délkeletre. A kistormási völgyben bronzkori leleteket és kelta ezüstpénzeket találtak. A 18. század elején a település Kölesddel együtt Sinzendorf, majd a Mercy gróf birtokába kerül. Mercy, a temesvári Bánát telepítési biztosa saját birtokain is szívesen telepített le németeket.'),
    ('Kistótfalu', 'A Villányi-hegység északi oldalán, Vokánytól nyugatra fekvő község. Vonattal elérhető a (Pécs–)Villány–Magyarbóly-vasútvonalon helyezkedik el. A honfoglalás előtt a nagy Morva birodalom része volt, mely a honfoglalók megjelenésével hullott szét. A település közelében az elmúlt évezred elején a Római Birodalom XXII. légiójának őrhelyei állhattak, mivel a település közelében vezetett el a római hadiút.'),
    ('Kisunyom', 'Szombathelytől 10 kilométerre délre fekszik, a Gyöngyös-sík déli részén, a Sorok partján. A szomszédos települések: észak felől Balogunyom, kelet felől Sorokpolány, dél felől Egyházasrádóc, nyugat felől pedig Ják. Nevét középkori birtokosairól a Hermán nemzetségből származó Unyaniakról kapta. A név valószínűleg szláv (Unin) eredetű. Előtagja a szomszédos Nagyunyomtól különbözteti meg.'),
    ('Kisvarsány', 'A falu nevének „Varsány” tagja ómagyar törzsi helynév, míg „Kis-” előtagja megkülönböztetésül szolgál a szomszédos Nagyvarsánytól helyezkedik el. A szomszédos települések közül Nagyvarsány alig 1, Vásárosnamény mintegy 3 kilométerre található. A megyeszékhely, Nyíregyháza mintegy 60 kilométer távolságra fekszik. Közúton Vásárosnamény vagy Nagyvarsány érintésével érhető el, a 4115-ös úton.'),
    ('Kisvaszar', 'Már a római időkben és a középkorban is lakott hely volt. Nevét az oklevelek 1328-ban említették először Vossary, Vosar formában helyezkedik el. A tatárdúlás után Vaszar néven fordul elő és a siklósi Kán nemzetség birtoka. A 15. századtól a Bocskai, majd a Laczkó család birtoka lett. A falut a török időkben is lakták. A 18. század első éveiben donáció útján kapta hg.'),
    ('Kisvejke', 'Jellegzetes halmazfalu. A megyeszékhely, Szekszárd körülbelül 35 kilométerre, Bonyhád mintegy 20 kilométerre található. A szomszédos települések: Závod, Lengyel és Mucsfa. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják.'),
    ('Kisvárda', 'A település egykoron a Rétköz mocsarának védelmében épült. Nyíregyházától 47 kilométerre északkeletre, az ukrán határtól 22 kilométerre délre terül el. Északról Döge, északkeletről Fényeslitke, keletről Pap, délkeletről Anarcs, délről Ajak, nyugatról Rétközberencs, északnyugatról Kékcse határolja.'),
    ('Kisvásárhely', 'Önkormányzata Mihályfa községben működik. Emellett egy betonozott út vezet ugyanezen út Mihályfa–Szalapa közti szakaszára, illetve egy gyenge minőségű önkormányzati úton el lehet jutni innen Gógánfára is. Kisvásárhely a Marcal melletti vizenyős területek miatt nem tudott terjeszkedni, így mindig is apró településnek számított. Első említése 1382-ból való.'),
    ('Kiszombor', 'A Bánság Magyarországon maradt területén, Makótól délnyugatra, a Maros bal partján, a Torontál háromszögben, a román határ közelében helyezkedik el. A közvetlenül határos települések az országhatár magyar oldalán: észak felől Makó, délnyugat felől Kübekháza, nyugat felől pedig Ferencszállás. Nyugati határszéle érintkezik még Deszk legkeletibb külterületeivel is, de utóbbi lakott területei amúgy távolabb esnek Kiszombortól.'),
    ('Kiszsidány', 'Kőszegtől 10 kilométerre keletre fekszik. A szomszédos települések: észak felől Peresznye (légvonalban 2, közúton 4 kilométerre), kelet felől Csepreg (6 kilométerre), nyugat felől pedig Horvátzsidány (kevesebb, mint 1 kilométerre). Közigazgatási területének déli része érintkezik még az amúgy távolabb fekvő Tömörd és Kőszegpaty, illetve pontszerűen Kőszeg határszéleivel is.'),
    ('Kisújszállás', 'A név jelentése: a kis jelző a település viszonylag csekély kiterjedésével van kapcsolatban, az új ismételt vagy újabb megszállást jelez, míg a szállás szó a 14–15. században a kunoknak és a jászoknak a magyarokénál kötetlenebb és más szerkezetű falvait jelöli.'),
    ('Klárafalva', 'Makótól mintegy 13 kilométerre nyugatra, Szegedtől nagyjából 20 kilométerre keletre helyezkedik el. Közigazgatási területének északi szélét a Maros folyása jelöli ki – azon túl Maroslelével határos –, további szomszédai: kelet felől Ferencszállás, nyugat felől pedig Deszk. Déli irányban a legközelebbi település Kübekháza, de közigazgatási területeik nem érintkeznek, mert elválasztják őket egymástól Deszk kelet felé messze elnyúló külterületei.'),
    ('Kocs', 'Szomszédai: észak felől Mocsa, kelet felől Tata, délkelet felől Környe, dél felől Kömlőd, délnyugat felől Szákszend, nyugat felől pedig Nagyigmánd. Szerepe a helyi közlekedésben annak ellenére jelentős, hogy a fel- és lehajtási lehetőségek a sztrádán ezen a szakaszán korlátozottak: Budapest irányában a 67. kilométernél lévő Tata-Környe csomópontot, Győr irányában pedig a 85. kilométernél lévő Komárom-Kisbér csomópontot használhatják a Kocsra igyekvők.'),
    ('Kocsola', 'A település pontos keletkezésére vonatkozóan megbízható információk nincsenek, a kis számú írásos feljegyzések alapján csak mozaikszerűen állítható össze története. Múltjáról leletek, égetett agyagedények, római pénzek, kis szobrok tanúskodnak, amelyek ma a szekszárdi múzeumban láthatók. Valószínű, hogy a honfoglalók szálláshelye is volt. Szeghalmi szerint a 11. és a 12. században a Monoszló nemzetség tanyázott itt.'),
    ('Kocsord', 'A település neve növényi eredetű: a kocsord (vagy disznókömény) kórós növény, amelynek kénszagú gyökere van. E növénynevet jelentő szó vált helynévvé. Eredetileg természeti név volt, és területet jelölt, később átvitellel a településre vonatkoztatták (Szab.szatm, 64, FNESz.) A növényt a 16. században gyógynövénynek is gyakran használták. A környező települések közül Mátészalka 4, Győrtelek 3, Tunyogmatolcs 8, Fehérgyarmat 13, Ököritófülpös 9, Porcsalma pedig 16 kilométer távolságra található.'),
    ('Kocsér', 'Nagykőröstől 10 kilométerre kelet-délkeletre, Tiszakécskétől pedig 13 kilométerre északnyugatra helyezkedik el. Tipikus, mezőgazdasággal foglalkozó tanyás község. A 13. század óta lakott terület. Nevének első előfordulása a budai káptalan, 1488. május 22-i okiratában található. Jelentése ismeretlen, feltehetően kun eredetű. Kocsér mint puszta már 1649-ben szerepelt az oklevelekben helyezkedik el.'),
    ('Kokad', 'A határ magyar oldalán mindössze három települési szomszédja van: észak-északnyugat felől Újléta, kelet felől Álmosd, délnyugat felől pedig Létavértes. Határszéle délkeleten egy rövid (valószínűleg kevesebb, mint egy kilométeres) szakaszon egybeesik az államhatárral, a legközelebbi települések a határ túloldalán Csokaly (Ciocaia) és Bihardiószeg (Diosig).'),
    ('Kolontár', 'A Veszprém–Devecseri-árokban, a Torna-patak mentén, Devecsertől körülbelül 3 kilométerre délkeletre, Ajkától pedig körülbelül 5 kilométerre nyugatra helyezkedik el. A falu határában található, 58 hektáros területű Lőrintei-víztározó kedvelt horgászhely. A tó a közelében létezett − hajdan önálló, de már régen Kolontárhoz csatolt, majd elnéptelenedett − Lőrinte falu nevét őrzi.'),
    ('Komjáti', 'Körjegyzőség központja. Autóbusszal a Volánbusz által üzemeltetett 3707-es, 4124-es és 4136-os busszal közelíthető meg. A környező települések közül Bódvalenke és Tornanádaska 3-3, Bódvaszilas és Tornaszentandrás 4-4 kilométerre található. A legközelebbi város a 21 kilométerre fekvő Szendrő. Komjáti Árpád-kori település. Nevét már 1283-ban említették az oklevelek, Komnati…'),
    ('Komló', 'A megyeszékhely után a megye második legnépesebb települése. A település egy századon át szénbányászatáról volt nevezetes. Bányakincseinek köszönhetően a szocialista időkben erőteljesen fejlesztették, 1951-ben nyilvánították várossá. Mára Észak-Baranya meghatározó gazdasági, közigazgatási, kulturális és egészségügyi központja. Hozzá tartozik Sikonda üdülőfalu, 1954 óta Kisbattyán, Mecsekfalu és Mecsekjánosi, 1958 és 1992 között pedig Mánfa is a része volt Pécsbudafával együtt.'),
    ('Komlódtótfalu', 'Szomszédai: a Szamos túlpartján Csenger 1,7 kilométerre fekszik tőle délnyugatra – de híd csak távolabb található, és arra 9,3 kilométeres az út –, Szamosbecs 2 kilométerre északnyugatra, Csengersima 3,5 kilométerre északkeletre, a romániai Szamosdara pedig 4,2 kilométerre délkeletre – ám közvetlen határátkelő nincs. 3 kilométerre keletre fekszik a kihalt (az 1970-es nagy árvíz miatt elnéptelenedett) Nagygéc.'),
    ('Komlósd', 'Első ismert írásos említése 1398-ből származik, ekkor Babócsa várához tartozó Komlós nevű településként említették. A 15. század végétől a Batthyány család birtokolta. A török megszállás idején elpusztult, a 18. század elején települt be újra helyezkedik el.'),
    ('Komlóska', 'A szomszédos települések: északkelet felől Makkoshotyka, kelet felől Hercegkút, délkelet felől Sárospatak, dél felől Bodrogolaszi és Tolcsva, délnyugat felől Erdőhorváti, északnyugat felől pedig Háromhuta. Zsáktelepülés, közúton csak Erdőhorváti felől közelíthető meg, a 3716-os útból kiágazó 37 134-es számú mellékúton helyezkedik el. A település várát 1379-ben említik először, mikor is a birtokos Tolcsva nemzetség tagjai megosztoztak rajta.'),
    ('Komoró', 'A szomszédos települések: észak felől Tuzsér (4,5 kilométerre), kelet felől Mándok (közúton mintegy 8 kilométerre), dél felől pedig Fényeslitke (5 kilométerre). Közigazgatási területe északnyugat felől Zemplénagárdéval határos, amely légvonalban mintegy 8 kilométerre fekszik a folyó túlpartján, de közúton csak jóval hosszabb útvonalon érhető el. Nyugat felől a legközelebbi település Révleányvár, amely azonban szintén a Tisza túlpartján fekszik, és a két község közigazgatási területei nem is érintkeznek egymással.'),
    ('Komádi', 'Sarkad, Biharkeresztes, Berettyóújfalu és Szeghalom nagyjából azonos távolságra helyezkednek el a településtől (25–30 kilométer). Közigazgatásilag a városhoz tartozik Mihálytelep, Külsőiszap, Gyártelep és Dobaipuszta is. Folyója a Sebes-Körös, ami kelet-nyugati irányban halad át a város déli részén, körülbelül 12 kilométer hosszan helyezkedik el. Természetföldrajzi szempontból a Kis-Sárrét északi peremén, a Bihari-sík szomszédságában fekszik.'),
    ('Komárom', 'Komárom stratégiai helyen, a Duna 1768. folyamkilométerénél, a Vág és a Csallóközi Duna-ág torkolatánál fekszik. Korábban Magyarország nyugati folyami határállomása is volt, a schengeni egyezmény elfogadása óta azonban a határ ellenőrzés nélkül, szabadon átléphető. A Duna jobb partja már a római kor óta lakott, itt állt a Római Birodalom egyik jelentős határvárosa, Brigetio.'),
    ('Kondorfa', 'A falu a Vendvidék mellett, az Őrségben, Őriszentpétertől 8 kilométerre északra fekszik a 7453-as út mentén, a Lugos-patak völgyében, erdőktől körülvéve. Közigazgatási területét érinti a szalafői országút (a 7455-ös út) is. Főbb részei Alvég, Fővég és a Hegy. Neve eredetileg a német Krottendorf helynévből származik, mai alakja magyar hozzáigazítás.'),
    ('Kondoros', 'Az autóút folytatása jelenleg is épül Békéscsaba felé. Az autóút átadása jelentősen tehermentesíti a település főutcáját, mivel az átmenő forgalom jelentős részének az autóút jobb alternatívát jelent. A település menetrend szerinti személyszállító vonattal nem érhető el, mivel a Kisszénásról…'),
    ('Kondó', 'Miskolctól közúton 17 kilométerre északnyugatra fekszik. A környező települések: Parasznya (kb. 4 kilométer), Radostyán (3 kilométer), Sajókápolna (4 kilométer), Sajólászlófalva (kb. 2 kilométer), Varbó (kb. 5 kilométer), a legközelebbi város: Sajószentpéter (7 kilométer). A 2011-es népszámlálás során a lakosok 91,8%-a magyarnak, 0,5% cigánynak, 0,2% németnek, 0,2% ruszinnak mondta magát (8,2% nem nyilatkozott.'),
    ('Konyár', 'Debrecentől mintegy 30 kilométerre délre fekszik, az észak-alföldi régióban. A közvetlen szomszédos települések: észak felől Hajdúbagos, északkelet és kelet felől Hosszúpályi, délkelet felől Esztár, dél felől Hencida és Gáborján, délnyugat felől Szentpéterszeg, északnyugat felől pedig Derecske.'),
    ('Koppányszántó', 'Központján a Nagykónyi-Somogyacsa között húzódó, a 61-es főutat a 6505-ös úttal összekötő 6508-as út halad végig. A környező városok közül Tamási 17 kilométerre fekszik, de a település Tab és Dombóvár felől is elérhető. A terület az Árpád törzsé volt, az első írásos emlék szerint Álmos herceg tulajdonát képezte. Jelenlegi nevét 1902-től használja. Egy 1333-as adat szerint a Habold nemzetség virágzó birtoka, majd később a dömösi prépostsághoz került.'),
    ('Korlát', 'Ez a szócikk az építészeti elemről szól. A települést lásd itt: Korlát (település) Korlátot alkalmaznak nagyobb mélységeknél elvezető közlekedési vonalak mellett, különösen magas töltések szélein és hidak két oldalán a közlekedés biztonsága érdekében, vagy terek elválasztása céljából. Készülhet kőből, ilyenkor mellvédő fal a neve, fából, vasból, vagy kombinálva.'),
    ('Koroncó', 'Győr központjától mintegy 10 kilométerre délnyugatra fekszik. A közvetlenül határos települések: északkelet felől Gyirmót és Ménfőcsanak (mindkettő Győr része), délkelet felől Győrszemere, dél felől Tét, délnyugat felől Rábaszentmihály, nyugat felől Mérges, északnyugat felől pedig Rábapatona. Történeti források szerint egykor a határában feküdt egy Dusnok nevű település is.'),
    ('Kosd', 'Vác északkeleti szomszédságában, a Cserháthoz tartozó Kosdi-dombság vidékén, a Kosdi-patak két partján helyezkedik el. Különálló településrésze Cselőtepuszta, a központjától légvonalban mintegy másfél, közúton bő két kilométerre nyugatra helyezkedik el. Erről az útról közelíthető meg Cselőtepuszta is. Kosd Árpád-kori település. András király ajándékozta a váci püspökségnek.'),
    ('Kovácsszénája', 'A község Pécstől 25 kilométerre, a Mecsek északi-északnyugati lejtőin fekvő apró falu. A mérsékelten meleg nyarat enyhe tél követi. Az évi középhőmérséklet alig éri el a 10 °C-ot. A falu neve évszázadokig a szláv eredetű Kovacéna volt. A települést az 1290-es pápai tizedlajstromban említik először, amelyet az esztergomi káptalan magánlevéltára őriz. 14. századi történeti források önálló plébániájával jelentős helynek ismerik.'),
    ('Kovácsvágás', 'A közvetlenül szomszédos települések: észak felől Füzérradvány, északkelet felől Vilyvitány, kelet felől Mikóháza, dél felől Sárospatak, délnyugat felől Nagyhuta, nyugat felől Kishuta, északnyugat felől pedig Pálháza. Délkelet felől határos még Vágáshutával is, amely szinte enklávéként ékelődik be a határai közé. A települést 1427-ben említik először, a füzéri várhoz tartozott és a Perényiek birtoka volt.'),
    ('Kozmadombja', 'A település eredetileg a 86-os úttól keletre helyezkedett el, a törökdúlás után alakult ki a mai helyén. Három fő része: a Kámánszer, az Arany János utca és a belső falurész (Jókai utca). A település felszíne dombos, termőtalaja agyagos, erősen kötött. Közigazgatási területe 763 hektár. Egyértelműen nem eldöntött, hogy a megyebeli két Kozmadombja (Kozmadombja…'),
    ('Kozárd', 'A Kelet–Cserhát egyik hangulatos völgyében található. A legközelebbi települések: délnyugat felől Ecseg, észak felől pedig Alsótold, a legközelebbi város a keleti szomszédságában fekvő Pásztó. Salgótarjántól 30, Budapesttől mintegy 80 kilométerre fekszik. A Novohrad-Nógrád UNESCO Globális Geopark települése. A környékén emelkedő magaslatokat (Pogányvár 320 méter, Bézma 514 méter) erdők borítják, külterületei nagyrészt a Kelet-cserháti Tájvédelmi Körzet részét képezik.'),
    ('Kozármisleny', 'Közvetlenül Pécs közelében, tőle dél-délkeletre, a Baranyai-dombság vidékén helyezkedik el. Szomszédos községek: északkeleten Nagykozár, keleten Magyarsarlós, délen Szemely és Egerág, délnyugaton Pécsudvard. Földrajzi értelemben néhány kilométerre található a Mecsek hegység déli lábától. Pécsudvarddal az 5716-os út köti össze. A város történetének…'),
    ('Krasznokvajda', 'A Rakaca-patak völgyében, Miskolctól közúton körülbelül 60 kilométerre északkeletre található község két, korábban önálló település, a Csereháthoz tartozó Krasznokpuszta ("Krasznyik") és a Tornai-dombságban fekvő Vajda települések egyesítésével jött létre. Krasznokvajda a központja a "Hétközségnek" nevezett földrajzi-néprajzi mikrorégiónak, amelyhez rajta kívül Büttös, Kány, Keresztéte, Pamlény, Perecse és Szászfa tartozik.'),
    ('Kulcs', 'A Duna jobb oldalán, a Csepel-sziget legdélebbre fekvő településével, Makáddal szemközti oldalon helyezkedik el. Rácalmás és Adony között található. Dunaújvárostól 10 kilométer-re északra fekszik. Közúton a 6-os számú főúton helyezkedik el. Vasúton a Pusztaszabolcs–Dunaújváros–Paks vonalon helyezkedik el. Szent István király 1025-ben a Veszprém-völgyi apácáknak adta a mai Kulcs területén fekvő Szántó nevű helységet.'),
    ('Kunadacs', 'Közigazgatási területe 8997 hektár, melyből 1620 hektár természetvédelmi oltalom alatt áll. A szomszédos települések: észak felől Kunpeszér, északkelet felől Tatárszentgyörgy, kelet felől Kunbaracs, délkelet felől Kerekegyháza, délnyugat felől Szabadszállás, nyugat felől pedig Kunszentmiklós-Kunbábony. Az Adacs (Adach) név feltételezések szerint az ősi magyar Ada név egyik becézése.'),
    ('Kunbaja', 'Közvetlenül a déli (szerbiai) országhatár mellett fekszik, Bácsalmástól délkeleti irányban. A városon kívül, a határ magyar oldalán még három települési szomszédja van: észak felől Bácsszőlős, északkelet felől Csikéria, nyugat felől pedig Madaras. Lakott területe közúton csak egy irányból érhető el, az 5501-es és az 5507-es utak találkozási pontjától kiágazó 55 107-es számú mellékúton.'),
    ('Kunbaracs', 'Az Alföldön, a Kiskunságban fekszik, Kecskeméttől 24 kilométerre északnyugatra. A szomszédos települések: észak felől Tatárszentgyörgy (légvonalban 10, közúton 15 kilométerre), északkelet felől (6,5 kilométerre) Ladánybene, kelet felől Lajosmizse (légvonalban 12, közúton 15 kilométerre), délkelet felől Kerekegyháza (8,3 kilométerre), délnyugat felől pedig Kunadacs (légvonalban 9,1, közúton csaknem 20 kilométerre).'),
    ('Kuncsorba', 'A szomszédos települések: észak felől Örményes, északkelet felől Kisújszállás Csorba nevű településrésze, kelet felől Túrkeve, dél felől Mezőtúr, délnyugat felől Kétpó, nyugat felől pedig Törökszentmiklós. Túrkevével a 4203-as út köti össze. A közúti tömegközlekedést a Volánbusz járatai látják el. A területet 1240-ben a kunok kapták meg. 1261-ben az egri püspökség birtoka volt. 1395-ben Csorba János szállása, később Csorbaszállás néven volt említve.'),
    ('Kunfehértó', 'Magyarországon, az Alföld nyugati részén, Budapesttől 160 kilométerre délre, Jánoshalmától 12 kilométerre északkeletre, Kiskunhalas városától 11 kilométerre délnyugatra található. A Duna 50 kilométerre nyugatra, a Tisza 65 kilométerre keletre folyik Kunfehértótól. A szomszédos települések: észak felől Kiskunhalas, kelet felől Balotaszállás, délkelet felől Kisszállás, délnyugat felől Jánoshalma, nyugat felől Kéleshalom.'),
    ('Kunhegyes', 'Az Alföldön, a Közép-Tiszavidéken, a Tiszafüred–Kunhegyesi-sík és a Nagykunság északnyugati részén található, a Nagykunsági-főcsatorna közelében, a Kakat-ér mellett, Budapesttől 160, a Tisza-tótól (Abádszalóktól) kb. 15, a megye székhelyétől, Szolnoktól pedig kb. 50 kilométerre. A közvetlenül szomszédos települések: észak felől Abádszalók, északkelet felől Kunmadaras, kelet felől Karcag, dél felől Kenderes, nyugat felől Tiszagyenda, északnyugat felől pedig Tiszabura helyezkedik el.'),
    ('Kunmadaras', 'A Nagykunság középső részén fekszik, Budapesttől közúton 160, vasúton 180 kilométerre délkeletre. Keleti külterületeinek egy jelentős, mintegy 47 négyzetkilométernyi területe a Hortobágyi Nemzeti Parkhoz tartozik, s ily módon természetvédelmi oltalom alá esik. A közvetlenül határos települések: észak felől Tiszaörs, északkelet felől Nagyiván, kelet felől Nádudvar, délkelet felől Karcag és Berekfürdő, délnyugat felől Kunhegyes, nyugat felől Tomajmonostora, északnyugat felől pedig Tiszaszentimre helyezkedik el.'),
    ('Kunpeszér', 'A Kiskunság északi részén fekszik, Budapest déli határszélétől alig 40 kilométerre délre, Kunszentmiklóstól légvonalban 11, közúton körülbelül 14 kilométerre északkeletre. A szomszédos települések: észak felől Dabas, kelet felől Tatárszentgyörgy, dél felől Kunadacs, délnyugat felől Kunszentmiklós, északnyugat felől pedig Bugyi Ürbőpuszta településrésze.'),
    ('Kunszentmiklós', 'A Csepeli-sík és a Kiskunsági-homokhát határán, utóbbi északnyugati részén fekszik, Budapesttől mintegy 60 kilométerre délre. Különálló településrésze Kunbábony, mely a központjától mintegy 7,5 kilométerre keletre helyezkedik el. A szomszédos települések: észak felől Apaj és Bugyi, északkelet felől Kunpeszér, délkelet felől Kunadacs, dél felől Szabadszállás, délnyugat felől Dunavecse és Szalkszentmárton, nyugat felől Tass, északnyugat felől pedig Dömsöd.'),
    ('Kunszentmárton', 'A Hármas-Körös kanyarulata mentén fekszik. Az Alföldön, a Közép-Tisza-vidék és a Körös-Maros köze tájegységek találkozásánál, a Körösszögben, a Hármas-Körös bal partján helyezkedik el. Történelmi településmagja a Körös egyik kanyarulatához igazodva épült ki és két fő része van: Felvég és Alvég (utóbbit „Epreskertnek” is hívják). Budapesttől 132 kilométerre, Szegedtől 76 kilométerre, Szolnoktól és Kecskeméttől 50 kilométerre, Szarvastól és Szentestől pedig 25 kilométerre található.'),
    ('Kunsziget', 'Magyarország északnyugati részén, a Mosoni-Duna jobb partján helyezkedik el, a történelmi, földrajzi tájegységben, Tóközben. Mérsékelten meleg, száraz éghajlatú vidék. Az évenkénti napsütéses órák száma 1900 óra felett alakul, ebből a nyári évnegyed részesedése 770, a télié 180 óra. Az évi átlaghőmérséklet +10,0, a vegetációs időszakban +16,8 Celsius-fok, a hőmérséklet havi középértéke januárban –1,1, júliusban +21,0 Celsius-fok.'),
    ('Kunszállás', 'A Kiskunsági löszös háton, Kecskemét és Kiskunfélegyháza között fekszik. A szomszéd települések: észak felől Városföld, délkelet felől Kiskunfélegyháza, dél felől Bugac, délnyugat felől Fülöpjakab, északnyugat felől pedig Kecskemét Matkó nevű külterületi városrésze. Kunszállás területét már a bronzkorban is lakták.'),
    ('Kunágota', 'Az Alföld délkeleti részén, a román határ közelében található. Szomszédai: észak felől Medgyesegyháza, északkelet felől Almáskamarás és Nagykamarás, kelet felől Dombiratos, délkelet felől Magyardombegyház, dél felől Battonya, nyugat felől Mezőkovácsháza, északnyugat felől pedig Magyarbánhegyes. A legközelebbi városok: Battonya, Mezőkovácsháza. A település neve az először betelepülő kunokra és a falu egykori templomának védőszentjére…'),
    ('Kup', 'Pápa déli vonzáskörzetében, Bakonypölöske és Pápakovácsi között fekszik. A település már az újkőkorban is lakott volt, de az itt végzett régészeti kutatások során a bronz-korból és a rómaiak idejéből is kerültek elő leletek. A falu nevét egy 1240-ből való oklevél említette először írásos formában, ekkor a pápai uradalomhoz tartozott. Később Szapolyai István, majd a 16. századtól az Enyingi Török család birtoka lett.'),
    ('Kupa', 'A Cserehát közepén helyezkedik el, Szikszótól északra. A környező települések közül Felsővadász és Monaj 5-5, Homrogd 6, Tomor (földúton) 3 kilométerre fekszik, a legközelebbi város a 17 kilométerre lévő Szikszó. Előmutatták az egri káptalan és Beud fia Albert királyi ember megállapítását tartalmazó levelet, mely szerint Kupai Heym és rokonsága igazi…'),
    ('Kurd', 'A Kapos völgyében, Dombóvártól mintegy 18 kilométerre északkeletre fekszik. A honfoglalás után katonai kísérőnépek telepedtek le a környéken, valószínűleg ők alapították a falut, és róluk kapta nevét. A Kurd szó ugyanakkor egy török eredetű régi magyar férfinév, jelentése: farkas. Kurd és környéke már ősidők óta lakott hely volt. Határában bronzkori eredetű kétfülű bronzvedreket (cisztákat) és hamvasztásos temetkezés nyomait tárták fel.'),
    ('Kurityán', 'A település történelmi múltja a középkorig nyúlik vissza, és jelentős szerepet játszott a térség nemesi, egyházi és ipari fejlődésében. Kazincbarcika északi vonzáskörzetében fekszik, Miskolctól közúton 25 kilométerre északra. A környező települések: északkelet felől Ormosbánya, kelet felől Izsófalva (4 kilométer), délkelet felől Szuhakálló (5 kilométer), délnyugat felől Sajókaza, északnyugat felől pedig Felsőnyárád (2 kilométer).'),
    ('Kustánszeg', 'A falu helyén korábban három, mára elpusztult település állt. Kustánszeg első említése 1542-ből való. A falu a főleg római katolikusok által lakott Göcsejben a reformátusok egyik gócpontja lett. A huszadik század során fokozatos, bár mérsékelt ütemű fejlődés jellemezte a falut, ugyanakkor az elvándorlás, az elöregedés és a népesség lassú csökkenése is jellemző a településre helyezkedik el.'),
    ('Kutas', 'A mai település területe már a bronzkorban is lakott volt, később a rómaiak pedig katonai tábort is építettek a közeli Rinya-parton. A 10. században már a magyar Bogát vezér nemzetsége telepedett le itt. Úrnője 1146-ban a pannonhalmi Szent Benedek-rendnek adományozta, 1240-ben pedig a Kutasi család bérelte ki. Első temploma a 15. századból származik, de egy évszázad múlva megsemmisült.'),
    ('Kutasó', 'A település a Cserhát hegyei között fekszik, Hollókőtől mintegy 10 kilométerre délnyugatra. A Szuha-patak és az Egres-patak közötti lapos részre, a Királykára épült. Tengerszint feletti magassága körülbelül 300 méter. A Novohrad-Nógrád UNESCO Globális Geopark települése. Kutasó Hollókőtől 13 kilométerre fekszik, ahová kék túra útvonal vezet a községből.'),
    ('Kács', 'A Miskolci-Bükkalja déli részén, a Kácsi-patak völgyében helyezkedik el, Egertől légvonalban 23, Miskolctól közúton 39,5 kilométer távolságra. Csak közúton érhető el, Bükkábrányon és Tibolddarócon át, a 3-as főútból kiágazó 25 114-es számú mellékúton. Már Anonymus gesztája is említette a környéket, mely szerint a honfoglaló magyarok itt, a Nyárád-patak (ma Nyárád-ér) közelében pihenőt tartottak.'),
    ('Kákics', 'Szigetvártól délkeletre, Sellye közvetlen északi szomszédságában fekvő település. A lehetséges nyomvonalváltozatok egyike ugyanis közvetlenül Kákics keleti határánál húzódik, rövid szakaszon érintve a falu közigazgatási területét is, míg a B változat szerint a majdani új út a falutól néhány száz méterre nyugatra haladna…'),
    ('Kál', 'Észak-északnyugat felől gyakorlatilag teljesen összenőtt Kompolttal, a további szomszédos települések: észak felől Kápolna, északkelet felől Kerecsend, kelet felől Füzesabony, dél felől Erdőtelek, délnyugat felől pedig Tarnabod.'),
    ('Káld', 'Káld már az Árpád-kor-ban is lakott hely volt. Nevét 1255-ben említik először az oklevelek Cald néven helyezkedik el. Később többféle formában is írták: Kaáld, Káld, Felső-Káld, és Alsó-Káld néven is. A hagyományok szerint Árpád egyik unokája - a Horka méltóságot viselő Káld - Levente fia kapta szállásterületként a Káli medencét és környékét, s tőle kapta nevét a falu is.'),
    ('Kálló', 'Aszódtól 15 kilométerre, Budapesttől 55 kilométerre fekszik. A közvetlenül határos települések: északkelet felől Erdőtarcsa, délkelet felől Verseg, dél felől Kartal és Aszód, délnyugat felől Galgamácsa, északnyugat felől pedig Erdőkürt. Kálló (Pisk-) Árpád-kori település. Nevét 1246-ban említette először oklevél Pithcalo alakban írva és már ekkor egyházas hely volt.'),
    ('Kállósemjén', 'A környező fontosabb települések közül Nagykálló 8, Balkány 10, Levelek 16, Magy 12, Nyírbátor 17, Pócspetri 3, Máriapócs 10 kilométerre található. A közvetlen szomszédos települések: észak felől Apagy és Magy, kelet felől Pócspetri, délkelet felől Kisléta, dél felől Nyírgelse és Szakoly, délnyugat felől Balkány, nyugat felől Biri és Nagykálló, északnyugat felől pedig Napkor.'),
    ('Kálmáncsa', 'Szigetvártól északnyugatra, Szulok, Istvándi, Homokszentgyörgy és Merenye közt fekszik. Utóbbi végpontja, a kiágazásától számítva közel 11 kilométer után a községhez tartozó, a központtól északkeletre fekvő Lajosházapuszta településrész északi részén található. Kálmáncsa, középkori nevén Kálmán-Csehi, Kálmán-Király-Csehi Árpád-kori település. Nevét már 1193-ban említette oklevél.'),
    ('Kálmánháza', 'Az ország távolabbi részei felől az M3 autópályán közelíthető meg a legegyszerűbben, aminek legközelebbi le- és felhajtója alig 3 kilométerre található. Az első tanyát, az 1913-ban Szegegyházán felszínre került okmányok szerint Beck Pál alapította 1775-ben. Birtoka kb. 2 ezer hold, s ezen a területen kb 15-20 család élt. A mai Kálmánháza területét, 8 család művelte meg.'),
    ('Káloz', 'A település a Sárvíz-malomcsatorna mellett, nem messze a Sárvíztől, a Mezőföldön található. A hozzá közel fekvő települések: Soponya, Csősz, Tác (Gorsium), Kisláng, Sárkeresztúr, Sárszentágota, Sárbogárd és Dég. A környék gazdag vas-, kelta, avar és római kori emlékekben, melyek azt bizonyítják, hogy létezett település a mai település közelében. Feltételezhetően 1009-ben alapították, amikor…'),
    ('Kálócfa', 'Lenti és Zalalövő közt fekszik, nagyjából a két város között félúton. A közvetlenül határos települések: észak felől Kozmadombja, északkelet felől Pusztaapáti, délkelet felől Pórszombat, dél felől Zalabaksa, délnyugat felől Csesztreg, nyugat felől pedig Kerkakutas. Csak közúton érhető el, a 86-os főúton, mely a központján is végighalad dél-északi irányban.'),
    ('Kántorjánosi', 'A környező települések közül Mátészalka 15,5, Hodász és Őr 5-5, Vaja 9, Rohod 12, Vásárosnamény 29, Nyírbátor 17, Papos 12,5, Jármi pedig 10,5 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Vaja, északkelet felől Őr, délkelet felől Hodász, dél felől Nyírderzs, délnyugat felől Nyírgyulaj, nyugat felől Ófehértó, északnyugat felől pedig Baktalórántháza.'),
    ('Kány', 'A Tornai-dombságot alkotó lankák-dombhátak ölelésében húzódik meg, közel a szlovák határhoz. A legközelebbi határon inneni település Büttös, a legközelebbi város, Encs távolsága pedig körülbelül 30 kilométer. Neve a hadvezér jelentésű, török eredetű, magyar szóra vezethető vissza, mely valószínűleg személynévből lett helynévvé. Első említése 1319-ből származik, amikor egy egy esztendeje tartó perben kiegyeztek egymással a falu régi birtokosai a Buzitai Kardosok és az Aba nemzetség későbbi szikszói, makranci és idai ágának ősei.'),
    ('Kánya', 'Kánya a Balatontól 28 kilométerre, a tamási gyógyfürdőtől 22 kilométerre, az igali gyógyfürdőtől pedig 30 kilométerre fekszik. Szép természeti környezet veszi körül a települést, a vidéket egymás mögött húzódó dombok és völgyek tagolják. A község körül tavak és gazdag vadállománnyal rendelkező erdők találhatók. Az említett fürdőhelyek és kirándulóhelyek közelsége miatt a község megfelelő pihenésre ad lehetőséget.'),
    ('Kányavár', 'Nagykanizsától közúton körülbelül 40 kilométerre északnyugatra található. Déli szomszédja Lispeszentadorján (4 kilométerre), északi szomszédja Páka (3 kilométerre). Az Alsó-Válicka menti települést nyugati oldalról hegyvonulat, kelet felől pedig erdők, szántóföldek valamint rétek határolják. A falut a középkorban Kányafölde néven emlegették, csak a 17. században épült vár létesítése után kezdték Kányavárnak nevezni.'),
    ('Kánó', 'Az Aggteleki-karszt délkeleti, a Galyaság délnyugati részén helyezkedik el, a megyeszékhely Miskolctól 40 kilométerre északra. A közvetlenül határos települések: észak felől Égerszög (3 kilométer), északkelet felől Szőlősardó (4 kilométer), délkelet felől Felsőtelekes (4 kilométer), dél felől Rudabánya (9 kilométer) és Zubogy, délnyugat felől Imola (5 kilométer), északnyugat felől pedig Aggtelek.'),
    ('Kápolna', 'A kápolna (lat. capella, cappa szóból, ami a fejet is betakaró köpenyt jelent), istentiszteletre szolgáló templomszerű kisebb épület, vagy épületrész. Ilyeneket eredetileg a vértanúk sírja fölé emeltek, később a plébániatemplomoktól messzebb fekvő községekben vagy tanyákon, főképp a temetőkben, utak mellett, bérceken vagy az előkelők palotáiban létesítettek.'),
    ('Kápolnásnyék', 'A környező településekhez hasonlóan komoly gazdasági és kulturális fejlődés jellemzi a rendszerváltást követő időkben is. Hozzá tartozik Pettend, amely szintén dinamikusan gyarapszik. A Velencei-tó keleti szomszédságában fekszik, északi részét a csekési szőlőhegyek határolják. Keresztülfolyik rajta a Bágyom-ér, amely a Velencei-tóba torkollik. E helyzeténél fogva Kápolnásnyék mára a szűkebb térség közlekedési központjává vált.'),
    ('Káptalanfa', 'A Bakonyalja és Nyirádi-dombság területéhez tartozik. Legközelebbi szomszédai észak felől Nemeshany és Bodorfa, dél felől Gyepükaján helyezkedik el. A középkori falu azonosítását egyszerűvé teszi a máig használt Sárosfői major elnevezés. A község keleti végétől mezei út vezet a sárosfői majorhoz, amely a község római katolikus templomától kb. 5 kilométer-re fekszik délkeletre.'),
    ('Káptalantóti', 'Káptalantóti a Balaton-felvidéken, Tapolcától 6 kilométerre helyezkedik el. A kis falut a Tapolcai-medence szélén a Szent György-hegy, a Csobánc, a Gulács és a Tóti-hegy bazalt tanúhegyek ölelik át. Nevéből a Káptalan előtag azzal kapcsolatos, hogy a faluban egykor a győri káptalannak voltak birtokai. A Tóti név eredete valószínűleg nem a szlovák nemzetnévből származik, hanem a délszláv (szlovén-horvát) népcsoporthoz tartozó tót népnévből képződött.'),
    ('Kára', 'Tabtól délre, Miklósi és Szorosad közt fekvő település. Központján a Szorosadtól Kapolyig húzódó, a 6508-as és 6511-es utakat összekötő 6516-os út halad végig. Első alkalommal 1138-ban a dömösi prépostság irataiban szerepelt, Villa Kara néven. 1229-től a székesfehérvári káptalan tulajdona, de 1294-ben még a somogyi várnak is voltak itt tartozékai. Neve 1332-1337 között a pápai tizedjegyzékben is szerepelt, tehát már ekkor egyházas hely volt.'),
    ('Károlyháza', 'A település a Kisalföld északnyugati részén helyezkedik el, a Mosoni-síkság peremén, a Hanság és a Szigetköz határán. Közigazgatási területe négy településsel határos, északkelet felől Kimlével, dél felől Lébénnyel, nyugat felől Újrónafővel, észak felől pedig Mosonmagyaróvárral. A kutatásokból kiderült, hogy már a honfoglalás idején lakott hely volt.'),
    ('Kárász', 'Kárász és környéke már az őskorban lakott hely volt, később a rómaiak is megtelepedtek a környéken. Erre utalnak az itt talált csont- és kőszerszámok, római kori leletek. A település nevét az oklevelek 1325-ben említették először Karaz alakban írva. 1439-ben Albert magyar király egyik oklevelében volt említve a település neve egy panaszüggyel kapcsolatban. 1542-ben a pécsi püspökség birtokaként szerepelt.'),
    ('Kásád', 'Magyarország második legdélebben fekvő települése, Beremend után helyezkedik el. A Villányi-hegységtől délre, Beremendtől 3 kilométerre nyugatra, a magyar-horvát határ közvetlen közelében található, központját az utóbbitól kevesebb, mint 2 kilométer választja el. A határ magyar oldalán csak három települési szomszédja van: észak felől Siklósnagyfalu, kelet felől a már említett Beremend, nyugat felől pedig Old.'),
    ('Kátoly', 'A község a Pécs, Pécsvárad, Mohács és Bóly városok által alkotott négyszögben, annak is szinte a középpontjában helyezkedik el, légvonalban mérve Pécsváradtól és Bólytól is egyaránt nagyjából 12-12 kilométerre, Pécstől és Mohácstól pedig hasonlóképpen nagyjából 18-20 kilométer távolságra. Legfontosabb vízfolyása a Karasica-patak, mely a belterületének keleti széle mellett folyik el.'),
    ('Káva', 'A Gödöllői-dombság legdélibb vonulatánál (Monor-Irsai dombság) fekszik, Pilis, Bénye és Pánd között. Gyönyörű természeti környezet, változatos állat- és növényvilág jellemzi. A Monor-Irsai dombság legeldugottabb települése. Területén két nagy löszvölgy húzódik. Akác- és fenyőerdők övezik. A tájkép változatos, dombok, völgyek, rétek tarkítják a látványt.'),
    ('Kávás', 'A településen polgárőrség működik. Első okleveles említése 1330-ból való Kawas néven. 1351-ben a Kapornaki apátság tulajdonában volt. 1366-ban a Salomvári család tulajdonaként szerepelt. 1454-ben V. László adományaként a Kawassy család kap tulajdonrészeket. 1485-ben a csébi Pogány család tagjai szerzik meg.'),
    ('Kázsmárk', 'Az Északi-középhegységben, a Cserehát keleti részén, a Vasonca-patak völgyében fekszik. A megyeszékhelytől, Miskolctól 30 kilométerre északkeletre található. Abaújszántóval a 3703-as út köti össze. A közúti közösségi közlekedés autóbuszos szolgáltatója e településen is a Volánbusz. A települést 1332-ben említették először Casmar, Kasmar néven. 1332-ben a pápai tizedjegyzékben papját is említették, tehát ekkor már egyházas hely volt.'),
    ('Kék', 'A kék az egyik alapszín. Kiegészítő színe a fények esetén a sárga, festékek esetén narancssárga. Az emberi szem képes megkülönböztetni a fény látható hullámhossz tartományában: a szemben lévő, kék fényt érzékelő csapsejtek fényelnyelése a 370–530 nm-es tartományt fogja át, az érzékenység maximuma 420 nm-nél van.'),
    ('Kékcse', 'Északnyugati szélétől alig több mint egy kilométerre húzódik a Tisza, de közigazgatási területét a folyó nem érinti. A környező települések: észak felől Szabolcsveresmart (4 kilométerre), kelet felől Döge (légvonalban 4, közúton mintegy 6 kilométerre), délkelet felől Kisvárda (6,5 kilométerre), dél felől Rétközberencs (légvonalban 5, közúton több mint 10 kilométerre), nyugat felől Tiszakanyár (4 kilométerre).'),
    ('Kéked', 'Különálló településrésze Felsőkéked, mely a központjától csaknem másfél kilométerre északra helyezkedik el, már egészen a határ közelében. A két legközelebbi város Gönc és Pálháza. A közvetlen szomszédos települések a határ magyar oldalán: dél felől Pányok, délnyugat felől pedig Abaújvár. Kelet felől Füzérhez tartozó külterületek határolják, de az a település egyébként messzebb esik Kékedtől, abban az irányban a legközelebbi község Hollóháza (amellyel viszont közvetlenül nem határos).'),
    ('Kékesd', 'Pécsváradtól légvonalban 8, közúton mintegy 11-12 kilométerre délkeletre fekszik, a Geresdi-dombság délnyugati lábainál. A szomszédos települések: észak felől Fazekasboda, kelet felől Geresdlak, délkelet felől Maráza, dél felől Szellő, nyugat felől pedig Erzsébet. Az 1290-es évhez kötődik az első írásos emlék, ekkor Keykug, kykug, klwwkuth alakban említik a nevét, amely feltehetőleg „kék patak” jelentésű.'),
    ('Kékkút', 'A Káli-medence a Balaton-felvidék mediterrán jellegű, méltán népszerű vidéke. A változatos formájú hegyek által körbevett központi medence tőzeges láprétjének délnyugati részén találjuk Kékkút települést. Salföldtől körülbelül 3 kilométerre, Káptalantótitól körülbelül 5 kilométerre, Kővágóörstől mintegy körülbelül 4 kilométerre található. Régészeti leletek szerint erre vezetett a rómaiak Itáliából, Aquincumba vezető útja.'),
    ('Kéleshalom', 'Kéleshalom Hajós és Jánoshalma között helyezkedik el. Innen indul a Kígyós-főcsatorna. A község történetét számos érdekesség szövi át. Hol a szerencsejáték döntött sorsa felől, hol a területet megvásárló telepesek hagyták el titokban a földet (innen a vidék neve: Illancs).'),
    ('Kémes', 'A település Baranya déli részén, a Dráva völgyében, az Ormánság területén helyezkedik el, a Fekete-vízbe torkolló Pécsi-víz és a Kémesi-árok összefolyása közelében. E terület első lakóira utaló leletek a bronzkor késői szakaszából valók. A római időkben itt élőkre utaló lelet egy feltárt sír volt. A község nevének első írásos említése 1077-1095 közötti időkből…'),
    ('Kérsemjén', 'Fehérgyarmattól északnyugatra, a Szatmári-síkság szélén fekszik, a Szamos jobb parti oldalán. A térség fontosabb települései közül Nyíregyháza 80, Mátészalka 23, Fehérgyarmat 9, Tunyogmatolcs 12, Tivadar 10, Panyola 3, Nábrád 2, Szamoskér pedig [légvonalban, a folyó túlpartján] mindössze 1 kilométer távolságra található. A közvetlen szomszédos települések: északkelet felől Kisar, délkelet felől Nábrád, dél felől Szamoskér, nyugat felől Szamosszeg, északnyugat felől pedig Panyola.'),
    ('Kétbodony', 'Távolsága Budapesttől 70, Balassagyarmattól 23, Váctól 30 kilométer. A közvetlenül határos települések: észak felől Szente, kelet felől Kisecset, délkelet felől Szécsénke, dél felől Legénd, délnyugat felől Romhány, északnyugat felől pedig Szátok. Rövid ideig (1264–1276) a Margit-szigeti apácák is birtokolták, később ismét a Bodoni családhoz került. 1516–1541 között Werbőczy István volt a birtokosa.'),
    ('Kétegyháza', 'Az egyik legnagyobb magyarországi román nemzetiségű település: lakóinak mintegy 30 százaléka vallja magát románnak. Szomszédai: észak felől Gyula, kelet felől Elek, délnyugat felől Nagykamarás és Medgyesegyháza, északnyugat felől Újkígyós és Szabadkígyós.'),
    ('Kéthely', 'Marcalitól északra, Balatonkeresztúrtól délre, Balatonújlak és Marcali közt fekvő település. Szőlő- és borgazdasági szempontból a település a Balatonboglári borvidék részét képezi. Kéthely nevét az 1332–1337 évi pápai tizedjegyzék említette először, már ekkor egyházas hely volt. 1403-ban Keethel, 1455-ben Kedhely alakban írva említették az oklevelek.'),
    ('Kétpó', 'Talajának nagy része réti csernozjom. Jelentős élővize nincs. Határában található a Nagykunsági főcsatorna egyik ága. A szomszédos települések: észak felől Törökszentmiklós, északkelet felől Kuncsorba, délkelet felől Mezőtúr, dél felől Mezőhék, nyugat felől Kengyel, északnyugat felől pedig Tiszatenyő. A légvonalban mintegy 20 kilométerre fekvő Túrkevével ugyan a közigazgatási területe nem határos, de e város közelsége is befolyással van az itt lakók életére.'),
    ('Kétsoprony', 'Szomszédai: északkelet felől Kamut, kelet felől Békéscsaba, délkelet felől Telekgerendás, délnyugat felől Csorvás, északnyugat felől pedig Kondoros. Érdekesség, hogy a község egyik településrésze, mely légvonalban mintegy 1,5 kilométer távolságra fekszik Kétsopronytól északkeleti irányban, a Kutyaszorító nevet viseli. 2001-es adatok szerint Kutyaszorító lakónépessége 46 fő, a lakások száma 28 volt.'),
    ('Kéty', 'A közvetlenül határos települések: észak felől Felsőnána, délkelet felől Zomba, délnyugat felől Kisdorog, nyugat felől Tevel, északnyugat felől pedig Murga. Kétyet az írásos emlékek az 1730-as években említik először, ám a nemrég a Tolna Megyei Levéltárban rátaláltak egy 1708-as pecsétre helyezkedik el. A török időkben ez a falu is elnéptelenedett.'),
    ('Kétújfalu', 'Szigetvártól 13 kilométerre délnyugatra helyezkedik el. A mai település Magyarújfalu és Németújfalu egyesítésével keletkezett 1940-ben. A megyeszékhely, Pécs felől Szigetváron át közelíthető meg a legegyszerűbben helyezkedik el. Horvátul a település neve a drávakeresztúriak által használt Ujfaluba. Ezenkívül létezett még a barcsiak által használt Ufaluba és a tótújfalusiak által használt Vujfaluba alak is.'),
    ('Kóka', 'Kóka magyar eredetű szó. Czuczor Gergely és Fogarasi János szótárában is szerepel, jelentése lehet: egy kis darab fa, vagy a Czuczor szótár alapján lehet: "Szőlőnek kacsa, fogódzó görbe szára". A székelyek egy része a mai napig használja a szót, beszélnek bükkfakókáról, nyírfakókáról stb., sőt igét is alkotnak a székelyek, amikor a deszkát ki akarják szárítani, a deszkák közé kókát tesznek, ezt úgy is nevezik, hogy felkókálják.'),
    ('Kóny', 'Magyarország északnyugati részén, a Rábaköz határán helyezkedik el, Győr (22 kilométer) és Csorna (10 kilométer) között. Határában 250 hektárnyi védett terület a Fertő–Hanság Nemzeti Park része. Természeti értéke a tőzegtavak rendszere, melynek 60 hektáros vízterülete horgászásra, csónakázásra alkalmas. A település címerében korona és ló látható. Az előbb arra utal, hogy a falu II.'),
    ('Kópháza', 'A lakosság 31%-a horvát nemzetiségű, de nagy többségük egyúttal magyarnak is vallja magát. Magyarországon csak két további települési szomszédja van: nyugat felől Harka (4 kilométerre), délkelet felől pedig Nagycenk (6 kilométerre). Déli határszéle egybeesik a magyar-osztrák országhatárral, abból az irányból a legközelebbi település Sopronkeresztúr (Deutschkreuz).'),
    ('Kórós', 'Közvetlen szomszédai: észak felől Hegyszentmárton, kelet felől Rádfalva, délkelet felől Drávapiski, délnyugat felől Adorjás, nyugat felől pedig Páprád. Kórós vidéke régebben vizekben gazdag, eredetileg lápos, mocsaras terület volt, amit sűrű erdők borítottak. Ezt az állapotot mutatják az 1785-ös katonai felmérés térképei is. Az utak az ingoványos helyeken cölöpökkel erősített földsáncokon vezettek át.'),
    ('Kóspallag', 'A település területe a Duna–Ipoly Nemzeti Parkhoz tartozik. A település a Börzsönyben található, a Fekete-hegy, a Szép-bérc, a Kopasz-hegy és az Alsó-hegy által körbezárt Kóspallagi-medencében. A falutól keletre a Kishanta-patak, nyugatra a Korompa-patak folyik, amelyek tőle 2 kilométer-re délre egyesülnek, és Malomvölgyi-, majd Medres-patak néven folynak tovább, és végül Zebegénynél ömlenek a Dunába.'),
    ('Kótaj', 'Kótaj Szabolcs-Szatmár-Bereg vármegyében, a Nyíregyházi járásban. A vármegye legnépesebb, községi címmel rendelkező települése. A vármegye középső-északnyugati részén fekszik, a Rétköz és a Nyírség határán, a megyeszékhely Nyíregyházától mintegy 10 kilométerre északra.'),
    ('Köblény', 'Dombóvártól 16 kilométerre délkeletre fekszik. Az 1325-ben keletkezett oklevél Kubli néven említi, amely a feltételezések szerint régi magyar űrmértékre (köböl), vagy a fával bélelt kutak nevére is utalhat. A török időkben a szászvári török helytartósághoz tartozott, ekkor főleg rácok lakták, a jelenlegi helyétől lejjebb, délnyugatra fekvő települést.'),
    ('Köcsk', 'A Kemenesalja közepén, a Ság és a Kis-Somlyó hegy között, a Kodó-patak, illetve a Csikászó-patak mentén fekszik. A település két részre különül el: az egykori Kisköcskre, illetve az attól nyugatra fekvő Nagyköcskre. A település első írásos említése 1237-ből való (Kuscku), ekkor még egy község volt. A név török eredetű személynév. A falu első ismert birtokosa Köcski Sándor, Károly Róbert hadvezére és bizalmasa volt.'),
    ('Kökény', 'Pécstől délre fekszik, erdők között, a Malomvölgyi-tó közelében, dombos vidéken. A megyeszékhelyet leszámítva négy települési szomszédja van – délkelet felől Pogány, dél felől Szalánta, délnyugat felől Szilvás, északnyugat felől pedig Keszü –, de Keszüt kivéve mindegyiktől aránylag jelentős, 5körülbelül 8 kilométeres távolság választja el. Zsáktelepülésnek tekinthető, mert közúton csak egy útvonalon érhető el, az 5826-os útból kiágazó 58 146-os számú mellékúton.'),
    ('Kölcse', 'Kölcse az ország legkeletibb csücskében, a magyar-ukrán határtól alig 10 kilométerre fekszik, az Öreg-Túr ölelésében, az Erdőháton. Szomszédai: észak felől Tiszakóród, északkelet felől Milota, kelet felől Sonkád, dél felől Csaholc, dél-délnyugat felől Vámosoroszi, délnyugat felől Fülesd, nyugat felől Túristvándi, északnyugat felől pedig Szatmárcseke.'),
    ('Kölesd', 'Kölesd a Sió és Sárvíz mellett, Pakstól és Szekszárdtól egyaránt 25 kilométerre fekszik, a Tolnai-Hegyhát keleti oldalán. A nagy távolság okán fokozatosan lecsökkent a személyforgalom, emiatt 2009. december 13. óta itt nem állnak meg a vonatok. Már 3000 évvel ezelőtt virágzó városa volt itt a keltáknak. A Csont-hegy ormán állt tornyos váruk, városuk pedig a mocsaras vidéket szegélyező dombok oldalán terült el.'),
    ('Kölked', 'A Drávaközben, Mohácstól mintegy 5 kilométerre délre fekszik, a Duna főágának jobb partján, attól mintegy három kilométerre, közvetlenül Magyarország és Horvátország államhatára mellett. A Duna–Dráva Nemzeti Park egyik fontos tájegysége. A további szomszédos települések a határ magyar oldalán: kelet felől Homorúd, nyugat felől pedig Sátorhely és Nagynyárád.'),
    ('Kömlő', 'A közvetlenül szomszédos települések: észak felől Besenyőtelek és Mezőtárkány, kelet felől Sarud, délkelet felől Tiszanána, dél felől Kisköre és Tarnaszentmiklós, délnyugat felől Hevesvezekény, nyugat felől pedig Átány. A község határa alapvetően a száraz kontinentális éghajlatú területek közé tartozik, átlagosan 560–580 milliméter évi csapadékmennyiség jellemzi.'),
    ('Kömlőd', 'Hozzá tartozik Parnakpuszta (Parnaková Pusta) is. A Vértes hegység lábánál, a Tatai-hegysor (Bársonyos) dombvidékén fekszik. Oroszlánytól 9 kilométerre északnyugatra, Kisbértől 25 kilométerre keletre, Tatától 15 kilométerre délnyugatra, Tatabányától 15 kilométerre nyugatra található. Autóbusszal a település az 1256-os, 1702-es, 1848-as, 1851-es, 8464-es, 8574-es és 8594-es járatokkal érhető el.'),
    ('Kömpöc', 'A szomszédos települések: észak felől Csengele, délkelet felől Balástya, délnyugat felől Csólyospálos, északnyugat felől pedig Kiskunmajsa. A község neve feltehetőleg egy Kömpöcz nevű vitéz után származik. Több mint 200 évvel ezelőtt ez a pusztaság az egri érsek birtokába került. Az első betelepülők 1850-52 környékén jöttek, és a mai belterület helyén építettek, náddal, szalmával fedett kunyhószerű építményeket.'),
    ('Kömörő', 'A megyeszékhely, Nyíregyháza kb. 75 kilométer, Fehérgyarmat 9 kilométer, Penyige 5 kilométer, Túristvándi 5 kilométer, Kölcse 13 kilométer, Tiszabecs 21 kilométer, Mánd 8,5 kilométer, Tunyogmatolcs 14 kilométer távolságra található. Kömörő nevét az oklevelek 1344-ben említik először, Kemerew néven. 1300-as évek elején a Kömörey család volt birtokosa. 1344-ben I.'),
    ('Körmend', 'Földrajzilag a Nyugat-magyarországi peremvidék, azon belül pedig a Vas–Soproni-síkság és a Rábai teraszos sík vidékén, a Rába völgyében, a folyó bal parti oldalán helyezkedik el, a Pinka torkolatának közelében. A nyugati országhatár közelében fekvő jelentős közúti forgalmi csomópont.'),
    ('Környe', 'A Vértesalja északkeleti peremén, az Által-ér partján, Tatabányától mintegy 5 kilométerre helyzkedik el. Területe 45,37 km², melyhez még Környebánya, Szentgyörgypuszta, Tagyospuszta és Irtáspuszta is hozzátartozik. Autóbusszal a 770-es, 1254-es, 1256-os, 1257-es, 1628-as, 1702-es, 1784-es, 1824-es, 1841-es, 1842-es, 1843-as, 1844-es, 1845-ös, 1846-os, 1848-as, 1851-es, 1852-es, 1854-es, 8403-as, 8419-es, 8441-es, 8443-as, 8444-es, 8460-as, 8462-es, 8464-es, 8587-es és 8594-es járatokon érhető el a település.'),
    ('Köröm', 'A köröm (unguis), az ujjak végpercének háti oldalán fekvő, a közepén kissé domború, rugalmas szarulemez, amely a bőr irharétegének módosult részéhez rögzül, amit körömágynak neveznek. A körömcsúcs az ágyon túl szabadon kiáll, hátulsó és oldalsó szélei, a bőr redő alakú visszahajlása által képezett keretbe jutnak. A kereten túl kiemelkedő bőrszegélyeket körömsáncnak nevezik.'),
    ('Körösladány', 'Körösladány a Körös menti sík északi peremén, a Dévaványai-sík és a Kis-Sárrét szomszédságában települt. Keresztülfolyik rajta a Sebes-Körös, amelynek erős kanyarulatait a szabályozáskor levágták. A mélyebben fekvő területeket a szabályozás előtt időszakosan víz borította. A szomszédos települések: északkelet felől Szeghalom, kelet felől Vésztő, délkelet felől Bélmegyer, dél felől Mezőberény és Köröstarcsa, délnyugat felől Csárdaszállás és Gyomaendrőd, északnyugat felől pedig Dévaványa.'),
    ('Körösnagyharsány', 'Természetföldrajzi szempontból a Kis-Sárrét északkeleti peremén, a Sebes-Körös bal partján fekszik. Szomszédai: észak felől Körösszegapáti, nyugat felől Körösszakál, dél felől pedig Biharugra helyezkedik el. Keleti irányból Romániához tartozó területek határolják, a három legközelebbi, határon túli település északkelet felől Körösszeg (Cheresig), kelet felől Vizesgyán (Toboliu), délkelet felől pedig Rojt (Roit).'),
    ('Körösszakál', 'Területe 1502 hektár. A szomszédos települések: északkelet felől Körösszegapáti, délkelet felől Körösnagyharsány, dél felől Biharugra, nyugat felől pedig Magyarhomorog. A Tiszántúl nagyobb városai közül Gyulától és Debrecentől egyaránt 63-63 kilométerre fekszik. A településen nyugat-keleti irányban végighúzódik a Komádi-Biharkeresztes közti 4215-ös út, ezen érhető el mindkét végponti város irányából.'),
    ('Körösszegapáti', 'Természetföldrajzi szempontból a Bihari-sík délkeleti peremén, a Kis-Sárrét szomszédságában fekszik. Szomszédai: észak felől Told, északkelet felől Berekböszörmény, dél felől Körösnagyharsány, délnyugat felől Körösszakál és Magyarhomorog, északnyugat felől pedig Mezősas. Igen kevés a híja, hogy nem szomszédos Berettyóújfaluval is. A településen végighalad, nagyjából északkelet-délnyugati irányban a Biharkeresztes-Komádi közti 4215-ös út, közúton a két végponti város felől ezen érhető el a legegyszerűbben.'),
    ('Köröstarcsa', 'További szomszédai: észak felől Körösladány, nyugat felől pedig Csárdaszállás. [Kelet felől Mezőberényhez tartozó, jobbára lakatlan külterületek határolják.] Természetföldrajzi szempontból a Körös menti sík déli peremén, a Kettős-Körös bal partján, a Békési-hát szomszédságában fekszik. A Kettős-Körös hullámtere vadregényes, ligetes tájék, a bal partján a hullámtér helyenként 100 méteres, a töltés lábánál kubikgödrök sora húzódik.'),
    ('Körösújfalu', 'A település a Berettyó–Körös-vidék középtáj Kis-Sárrét kistáján található. Környezete a Sebes-Körös hordalékkúpjának déli lábánál elterülő, a tengerszint felett 85-95 méterrel fekvő, közel tökéletes ártéri síkság, amely holtmedrekkel és csatornákkal sűrűn be van hálózva. Külterületén feltöltődött ősfolyómedrek és magaspartok váltakoznak. A település közigazgatási területe 25,31 km².'),
    ('Kötcse', 'Az eseménynek a Dobozy-kúria ad helyet, amelyen elsősorban a keresztény-konzervatív elit gyűlik össze: politikusok, gondolkodók, tudósok, üzletemberek, akik a magyar közélet vezető alakjai közé tartoznak. A község a Balatonboglári borvidék része. A Somogyi-dombság északi részén, a Balatontól 9 kilométerre fekszik, körülbelül 130-260 méter tengerszint feletti magasságban, igen tagolt környezetben.'),
    ('Kötegyán', 'Természetföldrajzi szempontból a Körös menti sík délkeleti peremén, a Kis-Sárréttől délre terül el. Északkeleti, keleti, délkeleti és déli irányból is Romániához tartozó területek határolják, a legközelebbi települések ezekből az irányokból Nagyszalonta (Salonta), Illye (Ciumeghiu), Keményfok (Avram Iancu) és Ant (Ant). További szomszédai, már magyar területen: nyugat felől Sarkad, északnyugat felől pedig Méhkerék.'),
    ('Kövegy', 'Makótól keletre, a román határ közelében található. A legközelebbi település az északkeleti szomszédságában fekvő Csanádpalota. Egy kisebb kiharapódástól eltekintve trapéz alakú közigazgatási területét észak, kelet és dél felől is Csanádpalotához tartozó külterületek határolják, csak nyugat felől van másik szomszédja, Magyarcsanád. Délkeleti határszéléhez nagyon közel fekszenek Nagylak északi határrészei, de a két település területe nem érintkezik egymással.'),
    ('Köveskál', 'Köveskál a Balaton-felvidéken, a Káli-medence keleti részén található, a Balaton partjától körülbelül 7 kilométerre északra, Tapolcától mintegy 15 kilométerre kelet-délkeletre. Északi szomszédja a mintegy 5 kilométerre fekvő Balatonhenye, mely igen szép fekvésű és hangulatos zsáktelepülés, közúton csak innen közelíthető meg (a 7313-as útból kiágazó 73 126-os úton).'),
    ('Kübekháza', 'Szegedtől délkeletre, a Bánság Magyarországon maradt területén, a torontáli háromszögben helyezkedik el, közel a magyar, román és a szerb hármashatárhoz. Észak felől egyébként Klárafalva a legközelebb fekvő település, de a közigazgatási területeik nem érintkeznek.'),
    ('Külsősárd', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik, 152 hektáros kiterjedésével a megye legkisebb közigazgatási területű települése. Magyar település, nemzetiségiek, etnikai kisebbségiek nem lakják. A rédicsi plébánia filiája, lakosai római katolikusok.'),
    ('Külsővat', 'Külsővat a Kisalföld messze délre nyúló középtáján, a Marcal-medence nyugati szélének középső részén helyezkedik el. A medencén belül két kistáj (mikrorégió) találkozásánál fekszik, kisebb részben a Marcal-völgyében, nagyobbrészt pedig a Pápa–Devecseri-sík peremén. Maga Külsővat is itt, a Marcal jobb parti magaslatán települ. A Marcal-medence egy sajátos átmeneti tájegység a kiemelkedő Bakony és a lesüllyedő Győri-medence között, e kettősség teszi változatossá Külsővat vidékét is.'),
    ('Küngös', 'Küngös a Bakony és a Mezőföld találkozásánál fekszik, a két legközelebbi település a 3 kilométerre lévő Csajág és a 6 kilométerre fekvő Berhida. Közigazgatási területe határos még (földúton) Balatonkenesével, Papkeszivel, Ősivel és Fülével is. Berhida felé indulva a Bakony vonulatai láthatóak, ám ha Csajág felé indulunk el, akkor a Mezőföld tárul elénk.'),
    ('Kőkút', 'Rinyabesenyőtől északkeletre, Kadarkút, Hencse és Homokszentgyörgy között fekvő település. Kőkút nevét 1893-ban említették először. A település ekkor alakult a kivágott erdők helyén. Alsótapazd neve már a középkorban is ismert volt Tapazd néven. Gyöngyöspusztán áll a Festetics-kastély, melynek déli szárnya a nagykanizsai postaút lóváltó állomásának romjaira épült.'),
    ('Kőröshegy', 'A település jól ismert a Balatonhoz való közelsége miatt. Üdülőhely, amely évente több ezer látogatót vonz. Emellett híres a levendulása, amely a tihanyival vetekszik. A település a Balatonboglári borvidék része, szőlőtermelése és bora is nevezetes. A Balaton déli partjától 3 kilométerre délre, a Külső-Somogy dombvidékének északi peremén, a Köröshegyi-séd völgyében helyezkedik el, a Kaposvár–Szántód közötti 6505-ös út mentén.'),
    ('Kőröstetétlen', 'Cegléddel és Jászkarajenővel a 4609-es, Szolnok térségével és Nagykőrössel a 4613-as, Abonnyal pedig a 4616-os út köti össze. Anonymus szerint Árpád fejedelem itt táborozott, s itt szemlélte meg seregét, amellyel Szer felé vonult, hogy megütközzön Zalán (Salán) bolgár fejedelemmel. A Nagypengyom dűlőben bronzkori urnák, középkori település és temető nyomaira bukkantak a régészek.'),
    ('Kőszeg', 'Városrésze: Kőszegfalva. Gazdag múltja révén sokszor jelentős szerepet töltött be Magyarország és Ausztria történelmében. A város sikeres helytállása először a hírnevet, majd a gazdaság felvirágzást hozta el. Mivel ezt követően a háborúk már elkerülték, mára országunk műemlékekben egyik leggazdagabb városa lett.'),
    ('Kőszegdoroszló', 'Szombathelytől 15 kilométerre északnyugatra, Kőszegtől 9 kilométerre délre fekszik, Kőszeghegyalján, a Doroszlói-patak mentén. A szomszédos települések: észak felől Kőszeg, északkelet felől Kőszegfalva, kelet felől Lukácsháza, délkelet felől Gyöngyösfalu, dél felől Perenye, nyugat felől Kőszegszerdahely, északnyugat felől pedig Cák. A Kőszeg várához tartozó falu nevét először Durisley formában örökítették meg, 1279-ben.'),
    ('Kőszegpaty', 'A Gyöngyös-sík északnyugati részén fekszik, Kőszegtől 11 kilométerre délkeletre. A szomszédos települések: északkelet felől Tömörd, délkelet felől Vasasszonyfa, nyugat felől Pusztacsó, északnyugat felől pedig Nemescsó. Közigazgatási területe északon messze, több kilométerre elnyúlik a faluközponttól, így abból az irányból rövid szakaszokon határos még Kőszeggel, Horvátzsidánnyal és Kiszsidánnyal is.'),
    ('Kőszegszerdahely', 'Magyarország első natúrparkja, az Írottkő-Natúrpark egyik alapítója volt 1997-ben. A központi belterületen kívül lakott külterületei: Ereszténymajor, Fűtelekmajor, Zsáperhegy. Magyarország földrajzi kistájainak katasztere szerint a település nyugat-magyarországi peremvidék nagytáj Alpokalja középtájának Vas-hegy és Kőszeghegyalja kistájához tartozik.'),
    ('Kőszárhegy', 'Hegye a Sárrétből emelkedik ki. Valójában azonban nem egy hegyről van szó, hanem egy olyan hegyvonulatról, amit két egymásban olvadó hegy alkot: a Somlyó-hegy, ami a letermelése előtt 226 méter magas volt és a Szár-hegy (227,8 méter). A Somlyó-hegy Polgárdi felé húzódik, míg a Szár-hegy a vonulat Szabadbattyán felé néző végén terül el. Helytelen a „Kopasz-hegy” elnevezése a Szár-hegyre, amit a helybeliek közül sokan használnak.'),
    ('Kőtelek', 'A település elnyerte a Magyar Örökség díjat. Teljes lakott területe és közigazgatási területének túlnyomó része a jobb parton terül el, de egy kisebb rész (egy holtág által közrefogott, körülbelül 5 négyzetkilométernyi terület) a mai folyó bal parti oldalára esik. A közvetlen határos települések: észak felől Tiszaroff, kelet felől Tiszabő (mindkettő a Tisza túlsó, bal partján), dél felől Nagykörű, délnyugat felől Csataszög és Hunyadfalva, északnyugat felől pedig Tiszasüly.'),
    ('Kővágószőlős', 'Kővágószőlős Pécstől nyugatra, a Mecsekalján, a Jakab-hegy lábánál helyezkedik el. A hegy és a dombsor értékes természetvédelmi terület. A Jakab-hegyet felépítő permi vörös homokkő a falu feletti hegyoldalban sajátos sziklaformációkat alkot: a Babás-szerköveket, és a Zsongor-követ. A mélyebben található zöld homokkő uránt tartalmaz. Cserkúttal a 6605-ös útból kiágazó 66 136-os út köti össze.'),
    ('Kővágótöttös', 'A honfoglalás korából származó, ősmagyar település. Nevét 1332-ben a pápai tizedjegyzékben említették először Thutheus néven. 1332-ben Thetheus, 1397-ben Teuteusnak írták. Egy 1332-ben készült összeírás szerint a legkisebb méretű települések csoportjába sorolható. Kővágótöttös birtokosa mindvégig a pécsi káptalan volt. A falu a török hódoltság alatt ugyan mindvégig lakott maradt, népessége azonban megfogyatkozott.'),
    ('Kővágóörs', 'Kővágóörs az 1984-ben tájvédelmi körzetté nyilvánított Káli-medence déli kapujának tekinthető. Egy jó másfél kilométeres partszakasza és partközeli településrésze, Pálköve révén Balaton-parti település is egyben, de magát a falut alacsony dombok választják el a tótól. A közvetlenül határos települések: észak felől Köveskál, északkelet felől Zánka, kelet felől Balatonszepezd, délkelet felől Révfülöp, délnyugat felől Balatonrendes és Salföld, nyugat felől Kékkút, északnyugat felől pedig Mindszentkálla és Szentbékkálla.'),
    ('Lad', 'A mai község Magyarlad és Németlad egyesüléséből jött létre 1950-ben. A középkorban – éppúgy, mint napjainkban – Lad nevű helységként tartották számon: 1772-ben csak magyar nyelvet beszélő polgárok éltek a településen helyezkedik el. Ahogy Somogyban több helyen is, a 18. század közepén telepedtek a németek Ladra helyezkedik el. Új utcasorok épültek, és 1745-ben két részre szakadt a valójában egységes szerkezetű falu.'),
    ('Ladánybene', 'Az ország távolabbi részei felől az 5-ös főúton közelíthető meg a legegyszerűbben, örkényi vagy lajosmizsei letéréssel. Az utazási idő a megyeszékhelyről autóbusszal kb. 35 perc, személyautóval 25 perc, a fővárosból 1 óra 45 perc autóbusszal, személyautóval kb. 1 óra 15 perc.'),
    ('Lajoskomárom', 'A környező települések közül Mezőkomárom 5, Dég 7, Nagyberény 17,5, Ságvár pedig 23 kilométer távolságra található. Hátrányos közlekedésföldrajzi adottságú település: csak alacsonyabb rendű közúton érhető el. A terv azonban az uradalom tiltakozásán megbukott. A falu mély talajvizű löszös síkságon fekszik, a löszréteg vízi hordalékra és homokos, agyagos pliocén rétegekre épült.'),
    ('Lajosmizse', 'Lajosmizse külterületei részben még a Homokhátság eredeti felszíni formáit őrzik. Számos kisebb homokdűnét és homokhátat láthatunk itt, amelyek az uralkodó széliránynak megfelelő északnyugat-délkeleti irányba rendeződve szelik át a tájat. A magasabban fekvő dűnesorok között számos apróbb tó, illetve mocsár húzódik meg. A régi térképeken jelölt kis szikes tavak – Fehér-tó, Nyír-tó, Suba-tó –, mára kiszáradtak, többet a talajrendezések során lecsapoltak (Posta-tó), a Szászpa és a Dússzék horgásztóként funkcionál helyezkedik el.'),
    ('Lak', 'Edelénytől 13 kilométerre északkeletre, Szikszótól 18 kilométerre északra, Miskolctól pedig (közúton) 32 kilométerre északra található. A legközelebbi települések Hegymeg (2 kilométerre), Tomor (3 kilométerre), Szakácsi (5 kilométerre) és Irota (6 kilométerre). A legközelebbi város Edelény. Határszélét északnyugaton érinti még a 2615-ös út is. Lak nevét először 1222-ben említették az oklevelek Loch alakban írva.'),
    ('Lakhegy', 'A Felső-Kemeneshát kistájban helyezkedik el, egy fennsíkon. Központja azonban csak arról letérve közelíthető meg: Egervár és Győrvár között félúton lekanyarodva a 74 107-es számú mellékúton, vagy az egervári temető felől önkormányzati utakon.'),
    ('Lakitelek', 'A mai község Kecskemét város birtokaiból, puszták egyesítésével jött létre. Jelenleg külterületként Lakitelekhez tartozik: Felsőalpár, Kisalpár, Árpádszállás, Szikra, Szikra-Oncsatelep, Kapásfalu, valamint Tőserdő. Az Az Alföldön, a Duna–Tisza közi homokhátságon, a Pilis–Alpári-homokhát Tisza jobb partjáig érő délkeleti csücskében, a folyó partja mentén helyezkedik el.'),
    ('Lakócsa', 'Szomszédai észak-északkelet felől Teklafalu és Endrőc, kelet felől Drávafok, délről Felsőszentmárton, délnyugatról Szentborbás, nyugatról Tótújfalu, északnyugati irányból pedig Potony. Déli szomszédaival, Szentborbással és Felsőszentmártonnal az 5825-ös út köti össze. Lakócsa nevét az 1565-1566 évi török kincstári fejadójegyzék említette először Lankofcse alakban. 1571-ben csak 5 házat írtak benne…'),
    ('Lapáncsa', 'A Villányi-hegységtől délkeletre, Mohácstól délnyugatra, Villány várostól délre elterülő település morfológiai értelemben a Nyárád-harkányi löszvidékhez tartozik. A szomszédos települések: észak felől Magyarbóly, kelet felől Kislippó, délkelet felől Illocska, nyugat felől pedig Beremend. A község neve az írott forrásokban először 1349-ben bukkant fel Lappanch változatban.'),
    ('Laskod', 'A közvetlen szomszédos települések: észak felől Nyírtass, kelet felől Petneháza, délkelet felől Nyírjákó, dél felől Nyírkércs, délnyugat felől pedig Ramocsaháza. Északnyugat felől a legközelebbi település Berkesz, de közigazgatási területeik (kevés híján) nem határosak egymással. Csak közúton érhető el, Petneháza felől a 4105-ös útból kiágazó 41 105-ös számú mellékúton, vagy Nyírtass felől egy ugyancsak burkolt, de számozatlan, alsóbbrendű úton.'),
    ('Lasztonya', 'Bázakerettye északi szomszédjában fekvő település. Lasztonya nevét 1381-ben említették először az írásos forrásokban Lazthonya néven, mint a Bánffyak birtokát. 1416-ban Lasztonyai Pál is birtokos volt itt. 1644-ben a Nádasdy családé lett, majd Nádasdy Ferencet, mivel részt vett a Wesselényi-összeesküvésben lefejezésre ítélték, ezután Lasztonya is a kincstárra szállt, ahonnan az Esterházyak váltották meg, és övék maradt egészen 1848-ig.'),
    ('Legyesbénye', 'A Zempléni-hegység délnyugati vége közelében helyezkedik el, a Fúló-hegy lábainál, a megyeszékhely Miskolctól közúton 32 kilométerre keletre. Kelet felől teljesen összenőtt Bekecs községgel, ezen kívül csak két másik települési szomszédja van: nyugat felől Megyaszó, észak felől pedig Monok. Dél felől a legközelebbi község Taktaszada, délnyugat felől pedig a Gesztelyhez tartozó Újharangod, de közigazgatásilag egyikkel sem határos.'),
    ('Legénd', 'A szomszédos települések: észak felől Kétbodony, északkelet felől Szécsénke, kelet felől Nógrádkövesd, délkelet felől Nógrádsáp, délnyugat felől Nézsa, nyugat felől Alsópetény, északnyugat felől pedig Romhány. Csak közúton érhető el, Nézsa vagy Nógrádsáp felől, a 2115-ös útból kiágazó és ugyanabba visszacsatlakozó 21 153-as számú mellékúton. Legénd az Árpád-korban alapított község.'),
    ('Lendvadedes', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik. Lakossága kevesebb, mint 50 fő, lakónépesség tekintetében Magyarország tizenhatodik legkisebb települése. A Zalai-dombságban, ezen belül a Kerka-vidéken, illetve a Hetés tájegységben helyezkedik el, közvetlenül a szlovén határ mellett. Közigazgatási határa délnyugaton valamivel kevesebb, mint másfél kilométer hosszan esik egybe az országhatárral.'),
    ('Lendvajakabfa', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik. Lakossága kevesebb, mint 50 fő, 2011-es állapot szerint – lakónépesség tekintetében – Magyarország hetedik legkisebb települése volt. Lendvajakabfa nevét a levéltári adatok szerint 1345-ben említették először az írásos források, akkor még Jacobfia Janusfolua, vagyis Jakabfiajánosfalva néven helyezkedik el.'),
    ('Lengyeltóti', 'Ma a Balatonboglári borvidék részét képezi. Tóti neve a tót szóból ered: ez a régi magyar szóhasználatban a délszlávokra is vonatkozó népnév volt. Ez valószínűleg arra utal, hogy az Árpád-korban a déli szomszédunkban élő szlavónokat – tótokat – telepítettek be a községbe. Nevét 1116-ban említette először oklevél, később 1331-ben Thoty alakban fordult elő.'),
    ('Lenti', 'A Zalai-dombság nyugati peremén, a Kerka-folyó mentén helyezkedik el, a megye nyugati részén, közel a szlovén határhoz. A városban polgárőrség működik. A város területén fellelhető legkorábbi nyomok a római korból valók. Valószínűleg lakott település is volt itt, amit a borostyánút közelsége is bizonyít. Lenti első említése 1237-ből való még Nemith alakban írva.'),
    ('Lepsény', 'A település neve nagy valószínűséggel egy szláv eredetű személynévből, a Lepsa vagy Lepsan névből származhat. Ez a személynév a szláv „lepší”, azaz „jobb” jelentésű melléknévből képződött. A név magyar nyelvi környezetben az -ény képző segítségével helynévvé alakult. Az -ény végződés a magyarban gyakori módja a személynevekből származó településnevek képzésének.'),
    ('Lesencefalu', 'Közvetlen szomszédai kelet felé Lesencetomaj, nyugat felé Vállus és Várvölgy. A legközelebbi városok Tapolca és Keszthely, de nincs messze Sümeg sem. Északi határában kiágazik egy kanyargós önkormányzati út Lesenceistvánd felé is. A szinte teljesen erdővel borított terület jellemző alapkőzete a dolomit. Ezen a Dunántúli-középhegységre jellemző kőzeten sajátos ökológiai viszonyok által meghatározott növény- és állatvilág figyelhető meg.'),
    ('Lesenceistvánd', 'A Keszthelyi-fennsík és a Tapolcai-medence szélén, a Lesence-patak mellett fekszik. Kelet felől vulkanikus hegyek láncolata és a Bakony erdői övezik. Déli irányban alig 10 kilométer választja el a Balatontól. A közvetlenül határos települések: észak felől Sümeg, északkelet felől Tapolca, kelet és dél felől Lesencetomaj, délnyugat felől Lesencefalu, nyugat felől Várvölgy, északnyugat felől pedig Uzsa.'),
    ('Lesencetomaj', 'A Keszthelyi-fennsík északkeleti oldalán, a Tapolcai-medence szélén terül el, mint az ősi Tomaj nemzetség volt családi fészke, a mai megyehatár közelében, az Uzsától Balatonedericsig húzódó Lesence-patak mellett. A közvetlenül határos települések: kelet felől Tapolca, délkelet felől Raposka, dél felől Nemesvita, délnyugat felől Lesencefalu, északnyugat felől pedig Lesenceistvánd.'),
    ('Letenye', 'Letenye nevét először 1341-ben említik írásos forrásban „Letyne” alakban helyezkedik el. A település neve szláv eredetű, a leto szóval hozható kapcsolatba, amelynek jelentése „nyár”. Ebből adódóan a név eredeti jelentése feltehetően a nyári időszakkal, nyaralással vagy a melegebb évszakhoz kötődő sajátosságokkal állhatott összefüggésben. A szomszédos települések a határ magyar oldalán: észak felől Zajk, északkelet felől Becsehely, kelet felől Tótszentmárton, délkelet felől Tótszerdahely, északnyugat felől pedig Murarátka.'),
    ('Letkés', 'Az Ipoly bal partján fekszik, a Börzsöny nyugati lábánál, a Letkési-patak völgyében. A község területe 24,55 km2 2003 óta (korábban 24,39 km2). Északról Ipolytölgyes, keletről Nagybörzsöny és Márianosztra, délkeletről Ipolydamásd, délnyugatról Leléd és (igen rövid szakaszon) Helemba, nyugatról pedig Ipolyszalka községek határolják. Északi határát a Nyerges-patak, nyugati határát (mely egyben államhatár is Szlovákia felé) az Ipoly alkotja.'),
    ('Levelek', 'Mezőgazdasági jellegű település, 4800 katasztrális holdnyi megművelhető területtel. Ipar csak kis mértékben jelent meg. Földrajzi fekvése jó, adottságai miatt körzeti központként szerepel. Az út két oldalán cserjék és fák sokasága. Vadrózsa, hóbogyó, jázmin bokrok, fenyő, juhar, nyár és egyéb fák, köztük természetesen a vidékre jellemző akácosokkal.'),
    ('Levél', 'A település német neve Kaltenstein. Horvátul két neve van. A bezenyeiek Kajtištan-nak, a kimleiek Klatšajna-nak hívták. Az ország észak-északnyugati széle közelében fekszik, az osztrák határtól 7, a szlovák határtól 17 kilométerre. A közvetlenül szomszédos települések: észak felől Bezenye, kelet felől Mosonmagyaróvár, dél felől Mosonszolnok, nyugat-északnyugat felől pedig Hegyeshalom.'),
    ('Leányfalu', 'Legközelebbi szomszédai délről Szentendre, északról Tahitótfalu, nyugatról Pilisszentlászló, keleten, a Szentendrei-szigeten pedig Pócsmegyer, illetve kicsit délebbre Szigetmonostor. Pócsmegyerre a település központjából ingázott a rév 2024-ig. Kiemelt üdülőterület, a Duna–Ipoly Nemzeti Park része. Területén az ókor maradványai csak az 1900-as években kerültek napvilágra azon ismert tény következtében, hogy a rómaiak a Dunántúl területét az 1. század második felében…'),
    ('Leányvár', 'A közvetlenül határos települések: kelet felől Piliscsév, délkelet felől Pilisjászfalu, délnyugat felől Dág, nyugat felől Csolnok, északnyugat felől pedig Dorog. Észak felől a legközelebbi település Kesztölc, de a közigazgatási területeik nem érintkeznek. Leányvár autóval Budapest határától 30 perc alatt, Esztergomból 10 perc alatt érhető el.'),
    ('Libickozma', 'Lakosságszámát tekintve a megye és a Dél-Dunántúl legkisebb települése. A falu Belső-Somogy északi részén található a Marcalit Kaposvárral összekötő vonalon, az egykori "legrövidebb" út mentén, mintegy 20 kilométerre a Balaton déli partjától. Ma egyetlen szilárd burkolatú úton, a 6703-as útból kiágazó 67 128-as számú bekötőúton lehet elérni Somogyfajszról, de a környező erdőkön számos járható földút vezet keresztül, melyeken Pusztakovácsiból, Marcaliból (Boronka), Mesztegnyőről és Nagybajomból is meg lehet közelíteni.'),
    ('Lickóvadamos', 'A településen polgárőrség működik. Területe 6,69 négyzetkilométer, lakónépessége 218 fő, népsűrűsége pedig 32,6 fő/km². Két fő településrésze a délebbi Vadamos és az attól északabbra elterülő Nagylickó, a kettőt a Gellénházi-patak választja el egymástól. Liczkó már 1260-ban létezett. Különböző neveken szerepel, mint: Aqua Lysco, terra Lysco, Naglizkow, Kyslyzko, Felselyzko és Iborlysko. 1338-ban a besenyői nemesek Nagy- Liszkó nevű birtokot Isabori Jánosnak engedték át. 1513-ban Nagy- Liczkót Várföldével fogják együtt.'),
    ('Liget', 'Ez a szócikk a községről szól. A folyóiratról szóló cikk a Liget (folyóirat) címen található. A megyeszékhely Pécstől északra, Komlótól északkeletre fekszik, a baranyai Hegyháton. A falun a Ligeti-árok nevű vízfolyás folyik keresztül, amely nyugat felé továbbhaladva, Oroszló területén a Baranya-csatornába ömlik. A közvetlenül határos települések: észak felől Tékes, északkelet felől Kisvaszar, délkelet felől Mecsekpölöske, dél felől Magyarszék, délnyugat felől Magyarhertelend és Oroszló, északnyugat felől pedig Varga.'),
    ('Ligetfalva', 'A Zalai-dombság keleti részén helyezkedik el, a Zalaapáti-hát területén. A közvetlennül határos települések: északkelet felől Kehida (Kehidakustány része), kelet felől Örvényeshegy (Zalacsány része), délkelet felől Zalacsány, délnyugat felől Tilaj, nyugat felől Tilajújhegy (Tilaj része), északnyugat felől pedig Almásháza. Csak közúton érhető el, a 76-os főútról Zalacsány és Nagykapornak között kiágazó, kb. 1 kilométer hosszú bekötőúton (a 73 209-es számú mellékúton).'),
    ('Lippó', 'Szerbül és horvátul a települést hivatalosan a beremendiek által használt néven Lipovo-nak hívják, de a töttösiek a Lipova alakot is használták. Ez a jellegzetes dél-baranyai falu szelíd lankák között helyezkedik el, közel a déli országhatárhoz, azon a hullámos löszháton, melyet keletről a Duna határol, nyugat felől pedig a Szársomlyó 442 méter magas mészkő eredetű csúcsa zár.'),
    ('Liptód', 'A település német neve Litowr, míg horvátul két alak használatos: az erdősmárokiak egy része által használt Litoba és a lánycsókiak némelyike által használt Liptov. Pécsváradtól délkeletre, Bólytól északra, Mohácstól északnyugati irányban fekszik. A szomszédos települések: észak felől Maráza, északkelet felől Erdősmecske, kelet felől Kisnyárád, délkelet felől Babarc, dél felől Versend, délnyugat felől Máriakéménd, északnyugat felől pedig Szellő.'),
    ('Lipót', 'Önálló a Szigetköz közepén, a Duna jobb partján helyezkedik el. Mosonmagyaróvártól keletre 15 kilométer, Győrtől nyugatra 24 kilométer távolságra fekszik. A nyelvtudomány, valamint a helytörténészek egybehangzó véleménye szerint a falu egy Lipót nevű személyről neveztetett el, aki a település egykori birtokosa volt. Haller János szerint Lipoldt mosoni polgárnak IV.'),
    ('Lispeszentadorján', 'Lispeszentadorján Dél-Zalában, Nagykanizsától északnyugatra mintegy 30, Lentitől délkeletre 20, Letenyétől pedig 15 kilométerre északra fekszik az Egerszeg–Letenyei-dombság lankáinak ölelésében, a Szentadorjáni-patak forrásánál. Még egy rövid útszakasz számozódik országos közútként: a Fő út egy része a 75 803-as útszámozást viseli. A község 1937-ben jött létre Lispe, Szentadorján és Erdőhát települések egyesítéséből, de mindhárom históriájának kezdete jóval korábbra datálható.'),
    ('Liszó', 'A települést először 1296-ból említi ismert okleveles forrás, mint lakatlan területet, Terra Lyzou (Lizó) névvel. A középkori falu a török időben elpusztult. A településre vonatkozó név 1342-ben tűnik fel az Anjou-korban helyezkedik el. A falu már ekkor létezett, a Lizói Péter fiai és rokonuk, Lizói Demeter birtokperéről szóló végzés ismert. Rendezett községhatárról beszél a forrás.'),
    ('Litka', 'Miskolctól közúton 60 kilométerre északkeletre található. Zsáktelepülés, amely közúton csak Fulókércs felől érhető el, Fáj községen át, a 2626-os útból kiágazó 26 146-os úton. A környező települések: Fáj 5 kilométerre, Fulókércs 8 kilométerre, Novajidrány és Pusztaradvány 13 kilométerre helyezkedik el. A legközelebbi város, Encs 20 kilométerre fekszik.'),
    ('Litke', 'Salgótarjántól északnyugatra, Nógrádszakál és Ipolytarnóc között fekvő település. Az Ipoly bal partján, a szlovák határ mellett található, Salgótarjántól 21, Szécsénytől 20, Balassagyarmattól 42 kilométer távolságra. A Novohrad-Nógrád UNESCO Globális Geopark települése. Legközelebbi szomszédja, a szlovákiai Tőrincs légvonalban mindössze 2 kilométerre helyezkedik el.'),
    ('Litér', 'Litér a Balaton-felvidék keleti szélén, a litéri törés mentén fekszik, Balatonfűzfőtől 5 kilométerre északra, a 8-as főúttól bő 2 kilométerre délre, Veszprémtől pedig 9 kilométerre keletre. Több, egymástól korban és stílusban eltérő településrészből áll, sőt a közigazgatási területének van egy teljesen különálló, exklávé jellegű része is, a központtól néhány kilométerre délkeletre, Balatonfűzfő ipari övezetének északi része és Papkeszi között.'),
    ('Lothárd', 'A dimbes-dombos tájon hullámzó három utcájában a régi tornácos parasztházak mellett a hagyományt megőrző felújított és látványos új építésű házak virágos és gyümölcsöskertjei gyönyörködtetik az idelátogatókat. A falu szinte minden pontjáról fehéren ragyog az 1902-ben épült harangláb, illetve az 1980-as évek második felében, közösségi összefogással és a helybéliek adományaiból megépült templom.'),
    ('Lovas', 'Lovas a Balaton északi partján, a Királykút völgyének kapujában fekszik. Közvetlen szomszédai Paloznak, Felsőörs és Alsóörs. Nyugaton az Öreghegy és a Kishegy szőlőskertjei övezik. A két hegy között folyik a Lovasi-séd, amelynek vize évszázadokon keresztül több malomnak nyújtott energiát. Ezt a részt ma is Malomvölgynek nevezik. A falun római eredetű útvonal húzódik keresztül, amelynek itteni szakasza jelenleg részben a 7219-es, részben a 7221-es, részben pedig a 72 116-os számozást viseli.'),
    ('Lovasberény', 'Lovasberény a Velencei-hegység északi lábánál, a Lovasberényi-háton helyezkedik el. A Vértes déli és a Velencei-hegység északi nyúlványai között elterülő termékeny sík- és dombvidéket, amelyet a Rovákja-patak szel át, a Krisztus születése előtti 2. évezredben már gondolkodó, alkotó népek lakták. A bronzkorban Mihály-vár és térségét népesítették be, de a kelták és a rómaiak településnyomai, temetői is megtalálhatók a település mai határában helyezkedik el.'),
    ('Lovászhetény', 'Pécsváradtól 4 kilométerre keletre, míg Pécstől 21 kilométerre északkeletre található, a Geresdi-dombságon belül. Központjától különálló, attól légvonalban jó másfél, közúton bő két és fél kilométerre északra fekvő településrésze az egykor önálló (saját kápolnával és temetővel is rendelkező) Pusztakisfalu. A falu közepén egy mély árok húzódik, amely Pécsvárad irányában elsekélyesedik, a helybeliek ezt csak "gödör"-nek nevezik.'),
    ('Lovászi', 'Arany címerpajzson, zöld dombon ágaskodó ló, amely arra emlékeztet, hogy a település a királyi lovászok lakhelye volt. A címerben utalást találunk a múltban is meghatározó szőlőtermelésre egy szőlőfürt formájában, ugyanakkor a közelmúlt olajipari kapcsolatára egy fekete sáv utal. Letenye és Lenti között fekszik, előbbitől valamivel több, mint húsz, utóbbitól kevesebb, mint tíz kilométerre, a két várost összekötő 7538-as út mentén.'),
    ('Lovászpatona', 'Az enyhe lankák, az alacsony dombok és sekély völgyek változatos látványt nyújtanak. Győr felől Tétig a 83-as főúton, majd arról letérve Gyömörén keresztül ugyancsak a 8306-os úton lehet elérni. Lovászpatona nevét 1353-ban Pathona néven említette először oklevél, 1374-ben pedig már Louazapathana néven volt említve. A neve a Patona személynévből ered, ennek származása ismeretlen.'),
    ('Lucfalva', 'A községnév attól a Sámsontól származik, aki II. Béla király korában Borics trónkövetelő híveként lovagvárat kapott, ami a 13-15. század között Fehérkő váraként vált ismertté, de 1472-ben már bizonyosan romokban hevert. A legenda szerint a hírhedt rablólovag leánya, Lucia lehet a falu névadója, míg két fiúgyermekéről, Márkról és Sámsonról Lucfalva szomszéd települései kapták nevüket (Márkháza és Sámsonháza). "1227: ve.'),
    ('Ludas', 'Közigazgatási területe 10,79 km2, vagyis 1079 hektár. A közvetlen szomszédos települések: észak felől Detk, kelet felől Nagyút, dél felől Nagyfüged, nyugat felől Karácsond, északnyugat felől pedig Halmajugra helyezkedik el. Az ország távolabbi részei felől az M3-as autópályán közelíthető meg a legegyszerűbben, annak a nagyfügedi lehajtójánál letérve.'),
    ('Ludányhalászi', 'Az Ipoly völgye ma is az érintetlen természet jegyeit viseli magán helyezkedik el. A falu a folyó széles völgyének szélére, árvízmentes magaslatra épült. Ezzel együtt a tavaszi áradások jótékony hatása érezhető kiváló minőségű rétjének üdeségében, valamint a falut körülvevő tórendszer vízutánpótlásában helyezkedik el. Ludányhalászi a Novohrad-Nógrád UNESCO Globális Geopark települése.'),
    ('Lukácsháza', 'A Gyöngyös-sík északnyugati peremén, Szombathelytől 13 kilométerre északra, Kőszegtől 7 kilométerre délre, a Gyöngyös-patak mentén hosszan elnyúlva fekszik. Határa keleten sík, nyugaton dombos, itt található a község észak-déli fekvésű szőlőhegye is.'),
    ('Lulla', 'A falu úgynevezett szalagtelkes település. Négy falurészt különíthetünk el: Felső- és Alsófalu, Kisecseny, valamint Jabapuszta. A falu Tabtól 7, Torvajtól 3, Szántódpusztától 10, Sérsekszőlőstől 4 kilométerre található. A ma már Lulla belterületét is elkerülő Tab-Zamárdi út a 6501-es számozást viseli, míg a település központján végighaladó útvonal számozása 65 137-es.'),
    ('Lábatlan', 'A Duna mentén fekszik, a Gerecse északi lábainál, az országhatáron. A határ magyar oldalán csak két településsel határos közvetlenül: kelet felől Nyergesújfaluval, nyugat felől pedig Süttővel. Délkeleti irányban a legközelebbi település Bajót, de a közigazgatási területeik nem érintkeznek. Észak felől a legközelebbi szomszédos település a Szlovákiához tartozó Karva (Kravany nad Dunajom), a Duna túlpartján.'),
    ('Lábod', 'A legközelebbi város a 8 kilométerre fekvő Nagyatád. A Lábod környéki erdőség csodálatos természeti környezetet alkot, értékes növényvilága és szép kirándulóhelyei miatt szívesen keresik fel a turisták. Gazdag a vadállomány: a vadászok körében különösen híres a gímszarvas, épp ezért érthető, ha a vadászati szezonban jelentősen megnő a Lábod környékére látogatók száma.'),
    ('Lácacséke', 'Az 1950-es években jött létre a korábban önálló Láca és Cséke községek egyesítésével. Harmadik nagyobb településrésze Monyha. A Bodrogköz magyarországi részének keleti részén helyezkedik el, nem messze a szlovák határtól. A megyeszékhely Miskolctól közúton mintegy 120 kilométerre keletre fekszik. A környező települések közül Semjéntől 3, Dámóctól 4, Kisrozvágytól 5, Ricsétől mintegy 7 kilométer távolság választja el, az országhatár szlovák oldalán a legközelebbi község Perbenyik (Pribeník).'),
    ('Ládbesenyő', 'Edelénytől 5 kilométerre, a megyeszékhely Miskolctól közúton 26 kilométerre északra helyezkedik el. Különálló településrésze Andrástanya, mely az északi határszéle közelében található. A közvetlenül határos települések: észak felől Abod (8 kilométer), kelet felől Lak, dél felől Balajt (kb. 8 kilométer), nyugat felől pedig Szendrőlád (kb. 3 kilométer).'),
    ('Lánycsók', 'Itt találkozik a Duna-völgyének sík vidéke a Dunántúli-dombság lankáival. Legmélyebb része a tengerszint felett 98 méter, a legmagasabb területe 210 méter magasan fekszik. A napsütéses órák száma 2000–2050 óra évenként. Az évi középhőmérséklet 11 °C körül mozog, a csapadék évi mennyisége 650 mm körül van. A község patakja a Lánycsóki-patak (más néven Bég-patak, Mühlbach, Jenyei-árok) Mohács északi részén éri el a Dunát.'),
    ('Lápafő', 'A Dunántúli-dombság Somogyi-dombságában, a Lápa-patak mellett fekszik. A település neve is innen ered. A megyeszékhely, Szekszárd körülbelül 75 kilométerre, a legközelebbi város, Dombóvár mintegy 20 kilométerre fekszik. A szomszédos települések: Várong, Szakcs és Nak. Első írásos említése 1563-ból származik. Ekkor egy török adóösszeírás szerint a koppányi szandzsák része volt.'),
    ('Látrány', 'A község képében ma is őrzi a honfoglalók szállásainak jellegzetességét. Az egykori lakhelyek nagycsaládonként kör alakzatokat formáltak, közepén a közösség számára fenntartott térrel, a külső oldalon sánccal övezve. Később a népesség növekedésével és a házépítés térhódításával a közöttük hagyott üres területen házsorok és kanyargós utcák alakultak ki.'),
    ('Lázi', 'A Bakony északkeleti, lankás dombokká szelídült lábainál fekszik. Szomszédai: észak felől Táp, északkelet felől Tápszentmiklós, délkelet felől Sikátor, dél felől Veszprémvarsány, délnyugat felől Románd, nyugat felől Bakonypéterd, északnyugat felől pedig Győrasszonyfa. Kelet felől a legközelebbi település Bakonybánk, de közigazgatási területeik kevés híján nem határosak egymással.'),
    ('Lébény', 'Itt található hazánk egyik legépebben fennmaradt román stílusú monostortemploma, melynek építése 1208-ban kezdődött. A közvetlenül határos települések: észak felől Károlyháza és Kimle, északkelet felől Mecsér, kelet-délkelet felől Mosonszentmiklós, dél felől Győrsövényház, délnyugat felől Tárnokréti és Rábcakapi, nyugat felől Jánossomorja, északnyugat felől pedig Újrónafő.'),
    ('Léh', 'Az Északi-középhegységben, a Cserehát keleti részén, a Vasonca-patak völgyében fekszik, a megyeszékhely Miskolctól közúton kb. 30 kilométerre, északkeletre. A közvetlenül határos települések: észak felől Rásonysápberencs, északkelet felől Ináncs, kelet felől Csobád, délkelet felől Kiskinizs, dél felől Kázsmárk, délnyugat felől Homrogd, északnyugat felől pedig Monaj.'),
    ('Lénárddaróc', 'A Bükk-vidék területén fekszik, a megyeszékhely Miskolctól közúton 47 kilométerre északnyugatra. A környező települések: észak felől Csokvaomány (kb. 3 kilométer), északkelet felől Nekézseny (kb. 6 kilométer), kelet felől Nagyvisnyó, délkelet felől Szilvásvárad, délnyugat felől Bükkmogyorósd (6 kilométer), nyugat felől pedig Csernely (3 kilométer).'),
    ('Létavértes', 'Nagyléta és Vértes községek egyesítésével jött létre 1970-ben. Debrecentől 24 kilométerre, az Alföldön, a Dél-Nyírség és az Érmelléki löszös hát találkozásánál fekszik. Nagyléta és Vértes községek egyesítésével jött létre, előbbi a település keleti, utóbbi a nyugati felét alkotja. Közigazgatásilag hozzá tartozik még Cserekert is, mely a központjától mintegy 8 kilométerre délre helyezkedik el.'),
    ('Lócs', 'Büktől 6 kilométerre északkeletre, a Pós-patak mellett fekszik. A szomszéd települések: észak felől Iklanberény, északkelet felől Simaság, dél felől Bő, nyugat felől Bük és Csepreg, északnyugat felől pedig Tormásliget. Kelet felől a legközelebbi település Sajtoskál, de közigazgatási területeik – kevés híján – nem érintkeznek. Főutcája a kelet-nyugati irányban húzódó 8618-as út, ezen érhető el Simaság, illetve Bük-Csepreg irányából is.'),
    ('Lókút', 'Lókút Veszprémtől északra, Zirctől 7 kilométerre délre elterülő község a Bakonyban, azon belül a Magas-Bakonyban helyezkedik el. A völgyet, melyben az ófalu fekszik, délkeleti irányban a Kávás-tető, déli irányban a 644 méter magas Papod-tető szelíd lankái határolják. A jórészt mezőgazdaságból, fakitermelésből és bányászatból élő falut szántóföldek és legelők, valamint vadban gazdag erdők, vadvirágos, ligetes rétek övezik.'),
    ('Lónya', 'Két egyutcás falu, Kis- és Nagylónya egyesítéséből keletkezett. Új településrészek a két falu közt a 20. században épültek. Nyugati oldalról a Tisza, északi és keleti irányból az ukrán határ szegélyezi. A település mellett elhaladó Tiszát napjainkban fürdőzők helyett inkább a Nemzetközi Tisza-túra résztvevői és horgászok látogatják. A közvetlen szomszédos települések a határ magyar oldalán: dél felől Mátyus, délnyugat felől Benk, nyugat felől Tiszamogyorós, északnyugat felől pedig Eperjeske.'),
    ('Lórév', 'Lakóinak többsége szerb anyanyelvű, ezzel a település egyedülálló az egész országban – igaz, nagy többségük egyúttal magyarnak is vallja magát. A Csepel-sziget déli részén fekszik, közel a Duna főágához. A szomszéd települések: észak felől Ráckeve, kelet felől Szigetbecse, dél felől Makád, nyugat felől pedig a folyó jobb partján fekvő Adony. A Duna 2003-as alacsony vízállásakor, a falu határában lévő zátonyoknál folyamkotrás közben egy 1-3. század közötti római hajó roncsára bukkantak.'),
    ('Lövő', 'Az Vas–Soproni-síkság és a Kisalföld határán fekszik, Soprontól 27 kilométerre délkeletre, Fertőszentmiklóstól 14 kilométerre délnyugatra. Északnyugati szomszédja Sopronkövesd, de észak és kelet felől is e településhez tartozó külterületek határolják. A további szomszédos települések: dél felől Nemeskér, délnyugat felől Egyházasfalu, nyugat felől pedig Völcsej.'),
    ('Lövőpetri', 'A környék más települései közül Vásárosnamény 23, Nyírlövő 4, Pap 9, Aranyosapáti 8,5, Szabolcsbáka 5, Újkenéz 16, Tornyospálca 21, Jéke pedig 13,5 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Nyírlövő, északkelet felől Aranyosapáti, délkelet felől Gyüre, dél felől Gemzse, délnyugat felől Szabolcsbáka, északnyugat felől pedig Pap.'),
    ('Lúzsok', 'Az Ormánságban fekszik, a Drávától északra, Vajszló szomszédságában, tőle mintegy 4 kilométerre délnyugatra. Csak közúton közelíthető meg, legegyszerűbben Vajszlón keresztül, az 5823-as úton helyezkedik el. Az oklevelek 1346-ban említették először, Lusok módon írva. Az Ormánság közepén fekvő piciny település a tájegység körülbelül 45 falucskájának egyike.'),
    ('Lőkösháza', 'További szomszédai az ország határain belül: északnyugat felől Nagykamarás, nyugat felől pedig Kevermes. Ez utóbbi a legközelebbi szomszédja is egyben helyezkedik el. Keleti és déli irányból egyaránt romániai, Arad megyéhez tartozó települések, településrészek (Székudvar, Mácsa és Kürtös településekhez tartozó külterületek) határolják. Közúton a település csak mellékutakon közelíthető meg, mivel a térséget feltáró főutak nagyrészt messze elkerülik.'),
    ('Lőrinci', 'Az északi részén fekvő Selyp a város egyik kiemelkedő jelentőségű településrésze. A közvetlenül határos települések: észak felől Zagyvaszántó, északkelet felől Petőfibánya, kelet felől Ecséd, dél felől Hatvan, délnyugat felől Heréd, nyugat felől Nagykökényes, északnyugat felől pedig Héhalom.'),
    ('Madaras', 'Bácsalmástól délre, a szerb határ mellett fekszik a Bácsságban. Határában folyik a Kígyós-főcsatorna, melynek egyik oldalágán létesítették a Priszpa-tavat, utóbbi népszerű horgászhely. A település csak közúton közelíthető meg, Bácsalmás vagy Katymár érintésével, az 5508-as úton helyezkedik el. Az 55-ös főútról vagy Csávolynál letérve érhető el, Bácsbokod–Bácsborsód–Katymár községeken át, az 5505-ös, majd az 5508-as úton, vagy pedig Tataháza felől, Bácsalmáson keresztül az 5503-as, az 5501-es, végül ugyancsak az 5508-as úton.'),
    ('Madocsa', 'A Dunától 1,5 kilométerre nyugatra, a Dél-Mezőföld Kalocsai-Sárközzel határos peremétől 5–6 kilométerre keletre, az Duna jobbparti árterének egy magasabb hátán fekszik. Egyházi igazgatás szempontjából a Dunamelléki Református Egyházkerülethez, illetve a római katolikus egyház Pécsi egyházmegyéjéhez tartozik. Lakossága zömmel református vallású, így 15. századi temploma a török kiverését követő betelepítések után szintén református lett.'),
    ('Maglóca', 'A falu egy földhátságra települt, amelyet keletről és nyugatról is a Hanság idáig lenyúló mocsarai, vizenyős területei határoltak az elmúlt századokban. Ma is mélyebben fekvő területek ezek, amelyeket zömmel legelőnek, kaszálónak használnak. A hátság szántóföldjei mindig jó termést biztosítottak a falu lakosságának. A község határában (is) található a Sziget-erdő, amely egy részben keményfás, részben puhafás erdőtömb a hátság közepén.'),
    ('Maglód', 'Lakosainak száma 12 303 fő (2025. január 1.). A Pesti-hordalékkúpsíkság és a Gödöllői-dombság találkozásánál terül el, 180 méteres átlagos tengerszint feletti magasságban. Északi részén, a Hármas-hegynél ered az Alsó-Tápió. Budapest keleti szomszédságában helyezkedik el, központja a Belvárostól mintegy 28 kilométerre, a főváros XVII. kerületének határától azonban csak 3 kilométerre található keleti irányban.'),
    ('Magosliget', 'A határ magyar oldalán csak három településsel határos: észak felől a szomszédja Uszka, dél felől Kispalád, délnyugat felől pedig Botpalád. Északkeleti irányból az ukrajnai Tiszabökény (Тисобикень) a legközelebbi település, de valószínűleg szomszédos Tiszapéterfalvával (Пийтерфолво) is. A környező települések közül Uszka 3, Tiszabecs 7, Kispalád 5, Milota pedig 11 kilométer távolságra található.'),
    ('Magy', 'Baktalórántházától bő tíz kilométerre délnyugatra helyezkedik el, Levelek déli szomszédjában. További, közvetlenül határos települések még: kelet felől Ófehértó, dél felől Pócspetri, délnyugat felől Kállósemjén, északnyugat felől pedig Apagy. Északkeleti irányban a legközelebbi település Besenyőd, de a közigazgatási területeik nem érintkeznek. A többi környező településsel nincs közvetlen közúti kapcsolata.'),
    ('Magyaralmás', 'A A Móri-árok délkeleti végénél, a Sörédi-háton helyezkedik el, a megyeszékhely Székesfehérvár és Mór között nagyjából félúton, az utóbbihoz valamivel közelebb. A közvetlenül határos települések: észak felől Csákberény, kelet felől Zámoly, délkelet felől Sárkeresztes, nyugat felől Fehérvárcsurgó, északkelet felől pedig Söréd. Csak kevés híja van annak, hogy nem határos dél felől még Mohával is.'),
    ('Magyaratád', 'Kaposvártól északkeletre, Toponár városrész és Ráksi között fekszik, a Kaposvár-Szántód közti 6505-ös út mentén. Központjában ágazik ki az előbbi útból a 65 113-as út dél felé, a zsákfalunak tekinthető Patalom központjába. Magyaratád Árpád-kori település. Nevét 1284-ben már említették az oklevelek, mint a királyné hírnökeinek faluját. 1284-ben IV. László magyar király a falut Főnévi Lukácsnak adományozta, de Lukács testvérei, Kozma és Benedek, 1309-ben eladták a pécsi káptalannak.'),
    ('Magyarbánhegyes', 'Belterületének nagysága 290 hektár, amihez 3362 hektárnyi külterület tartozik. Szomszédai: északkelet felől Medgyesegyháza, délkelet felől Kunágota, délnyugat felől Mezőkovácsháza, nyugat felől Nagybánhegyes, északnyugat felől pedig Medgyesbodzás. A régészeti szórványok azt bizonyítják, hogy már a népvándorlás népei is megfordultak a mai falu területén.'),
    ('Magyarbóly', 'Villány 4,5 kilométer, Beremend 8,5 kilométer, Pócsa 9 kilométer, Borjád 11,5 kilométer, Bóly 17,5 kilométer, Mohács 30,5 kilométer távolságra található. A szomszédos települések: észak felől a Villányhoz tartozó Virágos, északkelet felől Márok, délkelet felől Kislippó, dél felől Lapáncsa, délnyugat felől Lapáncsa, északnyugat felől pedig Villány városa.'),
    ('Magyarcsanád', 'Magyarcsanád a Maros folyó közelében, a déli országhatár mellett fekszik, a Maros ugyanis ezen a szakaszán államhatárt képez Magyarország és Románia között. A legközelebbi közúti határátkelőhely Nagylaknál alig 8 kilométerre van Magyarcsanádtól. Belterülete nyugaton közvetlenül érintkezik Apátfalvával, további szomszédai észak felől Királyhegyes, kelet felől Kövegy és Csanádpalota, dél felől pedig a már Romániához tartozó Nagycsanád.'),
    ('Magyardombegyház', 'A Maros folyó sok-sok évezredek alatt lerakodott hordalékából alakult ki ez a sík vidék. Igen jó termőadottságai miatt már nagyon rég óta kisebb–nagyobb megszakításokkal lakott terület volt. Leleteket találtak a bronzkorból és a későbbi időszakokból is. A legrégebbi emberkéz alkotta emlék a Cikó-halom, amely a településtől 2,5 kilométer-re nyugati irányban található. 1814-ben a Nyéky földbirtokos család Makóról telepített református hitvallású zselléreket dohánykertészeknek a területre.'),
    ('Magyaregregy', 'Magyaregregy a Kelet-Mecsek lábánál fekszik a Boldogasszony völgyében, a Völgységi-patak mentén. A település és környéke már a rómaiak idején is lakott volt. 1554-ben már Egregy néven említi az írásos emlék, amely az éger fanévre utal. A középkorban itt állt a Szent Margit-kolostor is, a Kálvária-dombon a 18. században épült fel a Mária-kegytemplom.'),
    ('Magyaregres', 'A közvetlenül határos települések: észak felől Somogygeszti, északkelet felől Mernye, kelet felől Somogyaszaló, dél felől Kaposfüred (Kaposvár része), délnyugat felől Juta, nyugat felől Várda, észak-északnyugat felől pedig Alsóbogát. Csak kevés híja van annak, hogy nem határos északnyugati irányban még Somogyjáddal is, de a közigazgatási területeik nem érintkeznek.'),
    ('Magyarföld', 'A község északi oldalán folyik a Kerka-patak. A falu házai közvetlen közelében szántóföldek, rétek találhatók, kissé távolabb erdőségek húzódnak. A Szentgyörgyvölgyi Tájvédelmi Körzet területén fekszik gyönyörű környezetben. A középkorban ismert és jelentős hely volt. A települést a szájhagyomány szerint vendek, svábok és tótok alapították a 14. században.'),
    ('Magyargencs', 'A település a középkorban Laki Kaczor és a Gencsy család birtoka volt, de a 16. században gróf Cseszneky György győri várkapitány is gencsi birtokos volt. A 19. században a Károlyi, a szentmártoni Radó, a csengeri Háczky, a hertelendi és vindornyalaki Hertelendy, a Kisfaludy és a Gömbös családok rendelkeztek a faluban nagyobb földbirtokkal…'),
    ('Magyargéc', 'Szécsénytől keletre, a Szécsényhez tartozó Benczúrfalva és Nógrádmegyer község között található. A Novohrad-Nógrád UNESCO Globális Geopark települése. A falu eredetileg Gécz, 1881–1905 között Nagy-Gécz, 1905–1925 között Magyargécz, 1925-től Magyargéc. Magyargéc egykor a Kacsics nemzetség ősi birtoka volt. A 13. század elején az e nemzetségből származó Simon bán birtoka volt, akit Gertrúd magyar királyné meggyilkoltatásában való részessége miatt összes javaitól megfosztottak, majd birtokait II.'),
    ('Magyarhertelend', 'Komlótól nyugatra, a megyeszékhely Pécstől észak-északnyugatra fekszik, legfontosabb vízfolyása a Baranya-csatorna. Hozzá tartozik az egykor önálló Barátúr község, a központjától 2 kilométerre keletre. A közvetlenül határos települések: északkelet felől Liget, kelet felől Magyarszék, délkelet felől Mánfa, dél felől Orfű, délnyugat felől Kovácsszénája, nyugat felől pedig Bodolyabér.'),
    ('Magyarhomorog', 'Biharkeresztestől délnyugatra, Komádi és Körösszakál között fekszik. Természetföldrajzi szempontból a Bihari-sík déli peremén, a Kis-Sárrét szomszédságában helyezkedik el. Szomszédai: észak felől Mezősas, északkelet felől Körösszegapáti (Körmösdpuszta), kelet felől Körösszakál, délkelet felől Biharugra helyezkedik el. Dél, délnyugat és nyugat felől Komádihoz tartozó területek határolják, északnyugat felől pedig még határos Zsákával és Furtával is.'),
    ('Magyarkeresztúr', 'Magyarország északnyugati részén, a Rábaközben, annak délnyugati részén helyezkedik el. Lakott területét viszont csak alsóbbrendű utak érintik: délkelet-északnyugati irányban a 8605-ös, északkelet-délnyugati irányban a 8606-os út halad át a településen. Környéke már a régi korok embereinek is letelepedésre alkalmas vidék volt. A soproni múzeumba került mészbetétes díszítésű edények arról vallanak, hogy már a bronzkorban is ember lakott a Rábaköznek ezen a vidékén.'),
    ('Magyarkeszi', 'Területének nagysága 3185 hektár, ebből a belterület 356 hektár. A Tita-patak völgyében meghúzódó községet a 65-ös főútról az Iregszemcsénél leágazó mellékúton keresztül érhetjük el, ez az út Nagyszokolyig a 6407-es, onnantól a 6409-es számozást viseli. Fejér megye felől (Szabadhídvég) irányából Felsőnyéken át vezet ide az út (ez ugyancsak a 6409-es számozást viseli).'),
    ('Magyarlak', 'Magyarlak két szomszédos kisközség 1935-ös egyesítésével jött létre, Magyarlak és Háromház összevonásával. Magyarlak és Háromház eredete a középkorba nyúlik vissza. Háromház nevével először 1528-ban találkozhatunk. Magyarlakról az írott források első ízben 1354-ben tesznek említést "Lak" formában. A Magyarlak megnevezés már 1692 előfordul egy úriszéki per aktáiban, majd lassacskán kiszorítja a korábbi elnevezéseket.'),
    ('Magyarlukafa', 'A Zselic délnyugati részén helyezkedik el, központján a Somogyapátitól Vásárosbécig vezető 66 125-ös út halad végig. Magyarlukafát az oklevelek 1236-ban (más forrás szerint 1234-ben) említették először az oklevelek, Luca alakban írva, majd 1395-ben Lucafalwa, 1408-ban Lukafalwa, később Lukafa, Lukafalwa írásmóddal említik. A falut a török idők után sokáig csak mint pusztát említették kevés magyar lakossal. 1772-ben németek érkeztek ide, akik a faluban letelepedve üveghutát létesítettek itt.'),
    ('Magyarmecske', 'Szentlőrinctől délre, Sellyétől északkeletre fekszik, légvonalban mért távolsága mindkét várostól közel azonos, 11-12 kilométer, közúton azonban Sellyétől ennél kissé nagyobb távolság választja el. A közvetlenül szomszédos települések: észak felől Királyegyháza, kelet felől Magyartelek, északnyugat felől pedig Gyöngyfa. Délnyugaton Sumony lakatlan külterületeivel határos, de e község lakott területe valójában északnyugatra fekszik Magyarmecskétől, Gyöngyfán túl.'),
    ('Magyarnádalja', 'Az Alpokalján, a Csencsi-patak mellett fekszik, Körmendtől mintegy 5 kilométerre nyugatra. A megyeszékhelytől, Szombathelytől mért távolsága nagyjából 25 kilométer. A szomszédos települések: észak felől Harasztifalu, északkelet felől a Körmendhez tartozó Felsőberkifalu, kelet felől Körmend városa, dél felől Csákánydoroszló, délnyugat felől Kemestaródfa, nyugat felől pedig Vasalja.'),
    ('Magyarnándor', 'Az ország északi részében, az Északi-középhegység részét képező Cserhát középén, alacsony hegyek, dombok között helyezkedik el, Balassagyarmattól 14 kilométerre délre. Kelet-nyugat és észak-dél irányú utak kereszteződésében található a község. Így az Aszód-Balassagyarmat közötti úton Szlovákia, illetve a Rétság-Bánk-Romhány felőli út folytatásaként Cserháthalápon át Hollókő, vagy Pásztó és a Mátra, esetleg Hatvan és az Alföld felé lehet eljutni.'),
    ('Magyarpolány', 'Magyarpolány a Balatontól 35 kilométerre, a Bakony délnyugati lejtőin elterülő, erdőkkel övezett, mintegy 1270 főt számláló, sváb település, amely a Polányi Hosszúhegy és a Kálvária-hegy közti völgyben és azok lejtőin helyezkedik el. Festői fekvését ezen hegyek és a síkság találkozása adja. Éghajlata, levegője különösen az asztmatikus betegségben szenvedőknek kedvez.'),
    ('Magyarsarlós', 'Korábbi neve Magyarsóros volt, előfordul az említése Sóros, Sórós alakban is. Pécstől 10 kilométerre délkeletre fekszik, festői környezetben, egy öblös völgy védett ölelésében. Természetföldrajzilag a Dunántúli-dombságban, ezen belül a Dél-Baranyai-dombság középső részén helyezkedik el. Ez a kistáj a Mecsek és a Villányi-hegység között terül el, átlagos tengerszint feletti magassága 130–250 méter.'),
    ('Magyarszecsőd', 'Mindössze két települési szomszédja van: kelet felől Molnaszecsőd, délnyugat-nyugat felől pedig Körmend (északi és déli irányból is a városhoz tartozó külterületek határolják). A település első okleveles említése 1205-ből származik. Ekkor adományozta II. András Churnuk fia Istvánnak azzal a megkötéssel, hogy templomot építenek ide. A család ekkor vette fel a Szecsőd nevet.'),
    ('Magyarszentmiklós', 'A Zalai-dombságban fekszik, az Egerszeg–Letenyei-dombság területén. A közvetlenül határos települések: észak felől Magyarszerdahely, kelet felől Újudvar, dél felől Fűzvölgy. Nyugatról az amúgy jóval délebbre fekvő Homokkomáromhoz tartozó külterületek határolják. A legközelebbi város Nagykanizsa, körülbelül 14 kilométerre dél-délkeleti irányban helyezkedik el.'),
    ('Magyarszerdahely', 'A Zalai-dombságban fekszik, az Egerszeg–Letenyei-dombság területén. Határa részint dombos és sík, a település szabálytalan kiterjedésű. A közvetlenül határos települések: észak felől Kacorlak, északkelet felől Gelsesziget, kelet felől Újudvar, dél felől Magyarszentmiklós és Homokkomárom, délnyugat felől Eszteregnye és Oltárc, nyugat felől Bocska, északnyugat felől pedig Zalaszentbalázs.'),
    ('Magyarszombatfa', 'Az ország távolabbi részei irányából ez utóbbi úton közelíthető meg a legegyszerűbben, a 8-asról Csákánydoroszlónál délre letérve, Őriszentpéteren és Bajánsenyén keresztül. Lenti és Csesztreg felől Velemér érintésével érhető el a falu. 2004 óta Pártosfalva felől, Szlovénia irányából is elérhető. Első okleveles említése 1366-ból származik. A település szerkezete az Őrségtől eltérően Magyarszombatfa településrészen utcás faluképét mutatja.')
) AS v(name, panel_leiras)
WHERE c.name = v.name;

